static constexpr const char * kWorkcellStudioAssetMime = "application/x-workcell-studio-catalog-asset";

QTreeWidgetItem * find_asset_catalog_item_by_id(QTreeWidget * tree, const QString & requested_asset_id)
{
  const QString asset_id = requested_asset_id.trimmed();
  if (!tree || asset_id.isEmpty()) return nullptr;

  const auto find_in_subtree = [&asset_id](QTreeWidgetItem * root, const auto & self) -> QTreeWidgetItem * {
    if (!root) return nullptr;
    if (root->data(0, CatalogRoleAssetId).toString().trimmed() == asset_id) return root;
    for (int child_index = 0; child_index < root->childCount(); ++child_index) {
      if (auto * match = self(root->child(child_index), self)) return match;
    }
    return nullptr;
  };

  for (int index = 0; index < tree->topLevelItemCount(); ++index) {
    if (auto * match = find_in_subtree(tree->topLevelItem(index), find_in_subtree)) return match;
  }
  return nullptr;
}



QString canonical_skip_reason_key(const QString & reason)
{
  const QString token = reason.trimmed().toLower().replace('-', '_').replace(' ', '_');
  if (token.isEmpty()) return QStringLiteral("parse_error");
  if (token == QStringLiteral("missing_mesh_source_path") || token == QStringLiteral("missing_source_path")) return QStringLiteral("missing_source_path");
  if (token == QStringLiteral("file_not_found")) return QStringLiteral("file_not_found");
  if (token == QStringLiteral("unsupported_format") || token == QStringLiteral("unsupported_extension")) return QStringLiteral("unsupported_format");
  if (token == QStringLiteral("parse_error") || token == QStringLiteral("invalid_yaml_item") || token == QStringLiteral("missing_id")) return QStringLiteral("parse_error");
  if (token.startsWith(QStringLiteral("parse_error_"))) return token;
  if (token == QStringLiteral("duplicate_generated_visual_index_row")) return QStringLiteral("duplicate_generated_visual_index_row");
  if (token == QStringLiteral("oversized_mesh")) return QStringLiteral("oversized_mesh");
  if (token == QStringLiteral("unsafe_for_preview")) return QStringLiteral("unsafe_for_preview");
  if (token == QStringLiteral("zero_triangle_mesh")) return QStringLiteral("zero_triangle_mesh");
  if (token == QStringLiteral("hidden_by_filter")) return QStringLiteral("hidden_by_filter");
  if (token == QStringLiteral("suppressed_static_robot_fallback") ||
      token == QStringLiteral("suppressed_static_fallback")) return QStringLiteral("suppressed_static_robot_fallback");
  if (token == QStringLiteral("invalid_pose")) return QStringLiteral("invalid_pose");
  if (token == QStringLiteral("invalid_scale")) return QStringLiteral("invalid_scale");
  if (token == QStringLiteral("duplicate_id")) return QStringLiteral("duplicate_id");
  if (token == QStringLiteral("unknown_role_no_fallback") || token == QStringLiteral("unknown_geometry")) return QStringLiteral("unknown_role_no_fallback");
  return QStringLiteral("parse_error");
}
QString canonical_scene3d_token(const QString & value)
{
  const QString normalized = value.trimmed().toLower().replace('-', '_').replace(' ', '_');
  if (normalized == QStringLiteral("generated_preview") ||
      normalized == QStringLiteral("generated_urdf_visual") ||
      normalized == QStringLiteral("locked_generated_urdf") ||
      normalized == QStringLiteral("locked_generated_urdf_visual")) {
    return QStringLiteral("locked_generated_urdf_visual");
  }
  if (normalized == QStringLiteral("legacy_static_fallback")) return QStringLiteral("primitive_fallback");
  if (normalized == QStringLiteral("overlays") || normalized == QStringLiteral("helper_overlay")) return QStringLiteral("overlay");
  return normalized;
}

QString authored_pose_signature(
  const QString & id, double x, double y, double z,
  double roll, double pitch, double yaw)
{
  return QStringLiteral("%1|%2|%3|%4|%5|%6|%7")
    .arg(id.trimmed())
    .arg(x, 0, 'g', 17).arg(y, 0, 'g', 17).arg(z, 0, 'g', 17)
    .arg(roll, 0, 'g', 17).arg(pitch, 0, 'g', 17).arg(yaw, 0, 'g', 17);
}

// Use the same semantic normalization for loaded layout records and newly
// placed catalog instances.  In particular, "asset" is an input/catalog role;
// the canonical physical scene role is "object".
QString canonical_scene_hierarchy_role(
  const QString & raw_role, const QString & raw_category, const QString & fallback_text)
{
  auto classify = [](const QString & structured_text) {
    const QString lower = structured_text.trimmed().toLower();
    if (lower.isEmpty() || lower == QStringLiteral("unknown")) return QString();
    if (lower.contains("keepout") || lower.contains("exclusion") || lower.contains("safety_zone") || lower == QStringLiteral("safety")) return QString("safety_zone");
    if (lower.contains("home") || lower.contains("safe_joint_state") || lower.contains("safety_pose")) return QString("home_safety_pose");
    if (lower.contains("end_effector") || lower.contains("gripper") || lower.contains("tool")) return QString("end_effector_tool");
    if (lower.contains("support_surface") || lower.contains("table") || lower.contains("workbench")) return QString("support_surface_table");
    if (lower.contains("pick_source") || lower.contains("pick_zone")) return QString("pick_source_zone");
    if (lower.contains("place_target") || lower.contains("place_zone") || lower.contains("bin")) return QString("place_target_bin");
    if (lower.contains("camera") || lower.contains("sensor")) return QString("camera");
    if (lower.contains("conveyor")) return QString("conveyor");
    if (lower.contains("robot")) return QString("robot");
    if (lower.contains("object") || lower.contains("fixture") || lower.contains("asset")) return QString("object");
    return QString();
  };
  const QString structured = classify(raw_role + QStringLiteral(" ") + raw_category);
  if (!structured.isEmpty()) return structured;
  const QString lower = fallback_text.toLower();
  if (lower.contains("robot")) return QString("robot");
  if (lower.contains("end_effector") || lower.contains("gripper") || lower.contains("tool")) return QString("end_effector_tool");
  if (lower.contains("camera") || lower.contains("sensor")) return QString("camera");
  if (lower.contains("support_surface") || lower.contains("table") || lower.contains("workbench")) return QString("support_surface_table");
  if (lower.contains("conveyor")) return QString("conveyor");
  if (lower.contains("pick_source") || lower.contains("pick zone") || lower.contains("pick_zone")) return QString("pick_source_zone");
  if (lower.contains("place_target") || lower.contains("place zone") || lower.contains("place_zone") || lower.contains("bin")) return QString("place_target_bin");
  if (lower.contains("home") || lower.contains("safe_joint_state") || lower.contains("safe joint") || lower.contains("safety pose")) return QString("home_safety_pose");
  if (lower.contains("safety")) return QString("safety_zone");
  if (lower.contains("object") || lower.contains("fixture") || lower.contains("asset")) return QString("object");
  return QString("object");
}

QString scene3d_viewport_link_token(const ScenePreviewWidget::PreviewItem & item)
{
  const QString link =
    !item.visual_index_link_name.trimmed().isEmpty() ? item.visual_index_link_name :
    (!item.visual_index_link.trimmed().isEmpty() ? item.visual_index_link : item.display_name);
  return canonical_scene3d_token(link);
}

// The renderer deliberately retains generated links and diagnostic overlays, but
// the normal hierarchy is an authoring surface.  Keep this policy independent
// from renderer layer toggles so enabling a diagnostic layer cannot turn every
// URDF link or task helper into a user-facing scene owner.
bool is_user_facing_scene_hierarchy_item(const ScenePreviewWidget::PreviewItem & item)
{
  const QString id = canonical_scene3d_token(item.id);
  // Hierarchy admission is based on structured identity only. The shared
  // normalizer's label fallback remains available while ingesting legacy data,
  // but a friendly renderer label must not manufacture an authoring row.
  const QString role = canonical_scene_hierarchy_role(item.role, item.category, QString());
  const QString category = canonical_scene3d_token(item.category);
  const QString source_layer = canonical_scene3d_token(item.source_layer);
  const QString visual_source = canonical_scene3d_token(item.active_visual_source);
  const QString metadata = canonical_scene3d_token(item.metadata_tags);
  const QString source_file = canonical_scene3d_token(QFileInfo(item.source_path).fileName());

  // Source provenance outranks a generic renderer role. Generated visual rows
  // stay in the preview payload for rendering/diagnostics, never as owners.
  if (source_layer == QStringLiteral("locked_generated_urdf_visual")) return false;

  const bool generated_visual_identity =
    id.startsWith(QStringLiteral("generated_urdf")) ||
    !item.visual_index_link.trimmed().isEmpty() ||
    !item.visual_index_link_name.trimmed().isEmpty() ||
    !item.visual_index_visual.trimmed().isEmpty() ||
    !item.visual_index_visual_name.trimmed().isEmpty();
  if (generated_visual_identity) return false;

  const bool warning_or_helper =
    role == QStringLiteral("warning") || category == QStringLiteral("warning") ||
    role == QStringLiteral("safety_zone") || role == QStringLiteral("home_safety_pose") ||
    category == QStringLiteral("safety") || category == QStringLiteral("helper") ||
    metadata.contains(QStringLiteral("warning")) || metadata.contains(QStringLiteral("helper")) ||
    metadata.contains(QStringLiteral("keepout")) || metadata.contains(QStringLiteral("exclusion")) ||
    !item.alignment_warning.trimmed().isEmpty();
  if (warning_or_helper) return false;

  const bool authored_source =
    item.editable || item.linked_to_editable_layout_state ||
    source_layer == QStringLiteral("editable_layout") ||
    source_file == QStringLiteral("environment_yaml") ||
    source_file == QStringLiteral("environment_layout_yaml") ||
    source_file == QStringLiteral("workcell_studio_layout_yaml");
  const bool semantic_primitive = visual_source == QStringLiteral("semantic_primitive");
  const bool physical_target_bin =
    role == QStringLiteral("target_bin") || role == QStringLiteral("place_target_bin");

  // A derived destination/place-zone overlay follows its physical target and
  // must not become the hierarchy owner.
  if (source_layer == QStringLiteral("overlay") && !item.target_ref.trimmed().isEmpty()) return false;

  const bool task_only_semantic =
    role == QStringLiteral("pick_source_zone") || role == QStringLiteral("home_safety_pose") ||
    role == QStringLiteral("safety_zone") || category == QStringLiteral("pick_zone") ||
    (category == QStringLiteral("place_zone") && !physical_target_bin) ||
    metadata.contains(QStringLiteral("commissioning")) ||
    metadata.contains(QStringLiteral("drop_zone")) || metadata.contains(QStringLiteral("task_only"));
  if (task_only_semantic || (semantic_primitive && !authored_source)) return false;

  // Retain the established policy name while extending the same canonical
  // selection-owner path to fixed camera and support-surface owners.
  const bool canonical_robot_or_tool =
    (role == QStringLiteral("robot") || role == QStringLiteral("end_effector") ||
     role == QStringLiteral("end_effector_tool") || role == QStringLiteral("camera") ||
     role == QStringLiteral("support_surface") || role == QStringLiteral("support_surface_table")) &&
    source_layer == QStringLiteral("selection_owner_registry") && !generated_visual_identity;
  if (canonical_robot_or_tool) return true;

  const bool authored_physical_role =
    role == QStringLiteral("support_surface_table") || role == QStringLiteral("camera") ||
    role == QStringLiteral("target_bin") || role == QStringLiteral("place_target_bin") ||
    role == QStringLiteral("conveyor") || role == QStringLiteral("object");
  if (!authored_physical_role) return false;

  // Catalog instances are authored physical objects only when the complete
  // live-layout provenance contract agrees. Catalog metadata, staged mesh
  // previews, generated visuals, and fallback records must never become
  // additional rows merely because their semantic role normalizes to object.
  if (role == QStringLiteral("object")) {
    return source_layer == QStringLiteral("editable_layout") && item.editable &&
      !item.locked && item.linked_to_editable_layout_state;
  }

  // Locked canonical owners are useful hierarchy rows; locked generated link
  // records were rejected above by their visual-index identity.
  return authored_source || (!item.editable && item.locked &&
    source_layer != QStringLiteral("overlay") && visual_source != QStringLiteral("semantic_primitive"));
}

