  connect(
    scene_preview_widget_,
    &ScenePreviewWidget::preview_item_transform_changed,
    this,
    [this](
      const QString & id,
      double x, double y, double z,
      double roll, double pitch, double yaw)
    {
      const QString stable_id = id.trimmed();
      if (stable_id.isEmpty() || mounting_update_guard_) return;
      const QString echo = authored_pose_signature(stable_id, x, y, z, roll, pitch, yaw);
      bool mounted_graph = false;
      for (const auto & p : all_scene_preview_items_) mounted_graph = mounted_graph || p.mounting_yaml.contains("parent_object");
      if (mounted_graph && !pending_native_web_pose_signatures_.contains(echo)) {
        // Selection re-reports the current pose; only a moved asset is an edit.
        if (mounted_pose_unchanged(stable_id, x, y, z, roll, pitch, yaw)) return;
        commit_mounting_request({{"id", stable_id}, {"world_pose", QJsonObject{
          {"xyz", QJsonArray{x, y, z}}, {"rpy", QJsonArray{roll, pitch, yaw}}}}});
        return;
      }

      ScenePreviewWidget::PreviewItem before_item;
      bool found_authored_item = false;
      for (auto & item : all_scene_preview_items_) {
        if (item.id.trimmed() != stable_id) continue;
        before_item = item;
        found_authored_item = item.editable && !item.locked &&
          item.source_layer.trimmed() == QStringLiteral("editable_layout");
        item.x = x;
        item.y = y;
        item.z = z;
        item.roll = roll;
        item.pitch = pitch;
        item.yaw = yaw;
        break;
      }

      if (auto * canvas_item = find_canvas_item_by_stable_id(stable_id)) {
        const bool authored_transform_changed =
          std::abs(canvas_item->pos().x() / 100.0 - x) > 1e-12 ||
          std::abs(canvas_item->pos().y() / 100.0 - y) > 1e-12 ||
          std::abs(canvas_item->data(RolePoseZ).toDouble() - z) > 1e-12 ||
          std::abs(canvas_item->data(RoleRoll).toDouble() - roll) > 1e-12 ||
          std::abs(canvas_item->data(RolePitch).toDouble() - pitch) > 1e-12 ||
          std::abs(canvas_item->data(RoleYaw).toDouble() - yaw) > 1e-12;
        canvas_item->setPos(x * 100.0, y * 100.0);
        canvas_item->setData(RolePoseZ, z);
        canvas_item->setData(RoleRoll, roll);
        canvas_item->setData(RolePitch, pitch);
        canvas_item->setData(RoleYaw, yaw);
        const QString signature = authored_pose_signature(stable_id, x, y, z, roll, pitch, yaw);
        const bool native_bridge_echo = pending_native_web_pose_signatures_.remove(signature) > 0;
        if (authored_transform_changed && found_authored_item && !native_bridge_echo &&
            !canvas_item->data(RoleLocked).toBool() &&
            canvas_item->data(RoleSourceLayer).toString().trimmed() == QStringLiteral("editable_layout")) {
          ScenePreviewWidget::PreviewItem after_item = before_item;
          after_item.x = x; after_item.y = y; after_item.z = z;
          after_item.roll = roll; after_item.pitch = pitch; after_item.yaw = yaw;
          undo_stack_.push_back({QStringLiteral("live_transform"), stable_id,
            QPointF(before_item.x * 100.0, before_item.y * 100.0),
            QPointF(x * 100.0, y * 100.0), false, false, {}, before_item, after_item});
          redo_stack_.clear();
          scene_preview_widget_->set_native_authoring_history_available(true, false);
          mark_layout_dirty(QStringLiteral("Product View Transform"));
        }
      }

      if (scene_hierarchy_tree_) {
        for (int row = 0; row < scene_hierarchy_tree_->topLevelItemCount(); ++row) {
          auto * top = scene_hierarchy_tree_->topLevelItem(row);
          if (!top) continue;

          auto update_pose = [&](QTreeWidgetItem * tree_item) {
            if (!tree_item ||
                tree_item->data(0, TreeRoleId).toString().trimmed() != stable_id) {
              return false;
            }

            tree_item->setData(0, TreeRolePoseAvailable, true);
            tree_item->setData(0, TreeRolePoseX, x);
            tree_item->setData(0, TreeRolePoseY, y);
            tree_item->setData(0, TreeRolePoseZ, z);
            tree_item->setData(0, TreeRoleRoll, roll);
            tree_item->setData(0, TreeRolePitch, pitch);
            tree_item->setData(0, TreeRoleYaw, yaw);
            tree_item->setData(0, TreeRolePoseText,
              QStringLiteral("xyz=(%1,%2,%3) rpy=(%4,%5,%6)")
                .arg(x).arg(y).arg(z).arg(roll).arg(pitch).arg(yaw));
            return true;
          };

          if (update_pose(top)) break;

          bool found = false;
          for (int child = 0; child < top->childCount(); ++child) {
            if (update_pose(top->child(child))) {
              found = true;
              break;
            }
          }
          if (found) break;
        }
      }

      if (current_selected_scene_item_id_.trimmed() == stable_id) {
        SelectedSceneItemState refreshed = current_selected_scene_item();
        if (refreshed.valid) {
          selected_item_state_ = refreshed;
          refresh_selection_transform_editor_from_state(refreshed);
          refresh_selected_scene_item_labels(refreshed);
          refresh_selected_item_card();
        }
      }
    });
