void MainWindow::rebuild_digital_twin_canvas()
{
  // 2D fallback canvas rebuild only.
  // The 3D canvas is the embedded Web3D Product View hosted by ScenePreviewWidget in this same panel.
  // This 2D Layout shares selection/inspector state with it.
  const QString preserved_selected_id = current_selected_scene_item_id_;
  if (!digital_twin_canvas_) return;
  if (!digital_twin_scene_) {
    digital_twin_scene_ = new QGraphicsScene(digital_twin_canvas_);
    digital_twin_canvas_->setScene(digital_twin_scene_);
    connect(digital_twin_scene_, &QGraphicsScene::selectionChanged, this, &MainWindow::on_canvas_selection_changed);
  }
  digital_twin_scene_->clear();
  digital_twin_scene_->setProperty("workcellPhysicalBoundsValid", false);
  digital_twin_scene_->setProperty("workcellPhysicalBounds", QRectF());
  digital_twin_scene_->setProperty("workcellOverlayBoundsValid", false);
  digital_twin_scene_->setProperty("workcellOverlayBounds", QRectF());
  digital_twin_scene_->setSceneRect(-400, -300, 1200, 900);
  digital_twin_canvas_->setBackgroundBrush(QColor("#10161f"));

  QRectF overlay_bounds;
  bool has_overlay_bounds = false;
  const auto add_overlay_bounds = [&](const QRectF & bounds) {
    if (!bounds.isValid() || bounds.isNull()) return;
    if (!has_overlay_bounds) {
      overlay_bounds = bounds;
      has_overlay_bounds = true;
    } else {
      overlay_bounds = overlay_bounds.united(bounds);
    }
  };

  if (toggle_grid_box_ && toggle_grid_box_->isChecked()) {
    QPen grid_pen(QColor("#1f2a36")); grid_pen.setWidth(1);
    for (int x = -400; x <= 800; x += 40) {
      auto * line = digital_twin_scene_->addLine(x, -300, x, 600, grid_pen);
      line->setZValue(canvas_item_z_value("grid", "helper_overlay", "overlay", true));
      add_overlay_bounds(line->sceneBoundingRect());
    }
    for (int y = -300; y <= 600; y += 40) {
      auto * line = digital_twin_scene_->addLine(-400, y, 800, y, grid_pen);
      line->setZValue(canvas_item_z_value("grid", "helper_overlay", "overlay", true));
      add_overlay_bounds(line->sceneBoundingRect());
    }
  }
  QPen axis_pen(QColor("#3a4b5c")); axis_pen.setWidth(2);
  auto * x_axis = digital_twin_scene_->addLine(-400, 0, 800, 0, axis_pen);
  x_axis->setZValue(canvas_item_z_value("axis", "helper_overlay", "overlay", true));
  add_overlay_bounds(x_axis->sceneBoundingRect());
  auto * y_axis = digital_twin_scene_->addLine(0, -300, 0, 600, axis_pen);
  y_axis->setZValue(canvas_item_z_value("axis", "helper_overlay", "overlay", true));
  add_overlay_bounds(y_axis->sceneBoundingRect());
  auto * origin = digital_twin_scene_->addEllipse(-4, -4, 8, 8, QPen(QColor("#d9e2ec")), QBrush(QColor("#d9e2ec")));
  origin->setZValue(canvas_item_z_value("origin", "helper_overlay", "overlay", true) + 1.0);
  origin->setToolTip("World origin marker");
  add_overlay_bounds(origin->sceneBoundingRect());

  if (selected_scene_index_ < 0) {
    if (has_overlay_bounds) {
      digital_twin_scene_->setProperty("workcellOverlayBoundsValid", true);
      digital_twin_scene_->setProperty("workcellOverlayBounds", overlay_bounds);
    }
    return;
  }
  const auto & s = scene_browser_result_.scenes[(size_t)selected_scene_index_];
  auto model = workcell_builder::build_workcell_studio_canvas_model(s.scene_dir, s.scene_name);
  merge_active_editable_layout_session(&model);
  const QString layout_load_message = QString::fromStdString(model.layout_load_message).trimmed();
  if (!layout_load_message.isEmpty() && layout_load_message != last_layout_load_message_log_) {
    append_studio_log(layout_load_message);
    last_layout_load_message_log_ = layout_load_message;
  }

  QVector<QRectF> occupied_label_rects;
  QRectF physical_bounds;
  bool has_physical_bounds = false;
  const auto add_physical_bounds = [&](const QRectF & bounds) {
    if (!bounds.isValid() || bounds.isNull()) return;
    if (!has_physical_bounds) {
      physical_bounds = bounds;
      has_physical_bounds = true;
    } else {
      physical_bounds = physical_bounds.united(bounds);
    }
  };

  if (!show_reach_overlay_box_ || show_reach_overlay_box_->isChecked()) {
    auto * reach = digital_twin_scene_->addEllipse(-150, -150, 300, 300, QPen(QColor("#2dd4bf"), 2, Qt::DashLine)); // robot reach circle/arc
    reach->setZValue(canvas_item_z_value("reach", "helper_overlay", "overlay", true));
    add_overlay_bounds(reach->sceneBoundingRect());
  }
  auto * robot_base = digital_twin_scene_->addEllipse(-14, -14, 28, 28, QPen(QColor("#60a5fa"), 2), QBrush(QColor("#1d4ed8")));
  robot_base->setZValue(canvas_item_z_value("robot", "base", "editable_layout", false));
  robot_base->setToolTip("Robot base marker");

  for (const auto & entry : model.items) {
    const QString category = QString::fromStdString(entry.type);
    const bool is_editable_layout_item =
      entry.provenance == workcell_builder::WorkcellStudioItemProvenance::EditableLayout && !entry.locked;
    const bool is_editable_layout_provenance =
      entry.provenance == workcell_builder::WorkcellStudioItemProvenance::EditableLayout;
    const bool locked_for_canvas = !is_editable_layout_item;
    const QString canvas_access_label = is_editable_layout_item
      ? QStringLiteral("editable layout item")
      : (is_editable_layout_provenance ? QStringLiteral("locked editable layout item") : QStringLiteral("inspection-only preview"));
    auto * item = new DraggableCanvasItem(QRectF(0, 0, std::max(20.0, entry.width * 100.0), std::max(20.0, entry.depth * 100.0)));
    item->setPos(entry.x * 100.0, entry.y * 100.0);
    item->setPen(QPen(category_color(category).lighter(130), 2));
    item->setBrush(QBrush(category_color(category), Qt::SolidPattern));
    item->setToolTip(QString("%1 (%2) — %3")
      .arg(QString::fromStdString(entry.label), category, canvas_access_label));
    item->setData(RoleId, QString::fromStdString(entry.id));
    item->setData(RoleDisplayName, QString::fromStdString(entry.label));
    item->setData(RoleType, QString::fromStdString(entry.type));
    item->setData(RoleCategory, QString::fromStdString(entry.category));
    item->setData(RoleRole, QString::fromStdString(entry.role));
    item->setData(RoleLocked, locked_for_canvas);
    item->setData(RolePoseZ, entry.z);
    item->setData(RoleRoll, entry.roll); item->setData(RolePitch, entry.pitch); item->setData(RoleYaw, entry.yaw);
    item->setData(RoleSource, QString::fromStdString(entry.source_file));
    item->setData(RoleSourcePackage, QString(""));
    item->setData(RoleWidth, entry.width); item->setData(RoleDepth, entry.depth); item->setData(RoleHeight, entry.height);
    item->setData(RoleCatalogAssetId, QString::fromStdString(entry.catalog_asset_id));
    // Only a mesh-less item is a primitive; a mesh item never takes this role.
    item->setData(RoleGeometryType, entry.source_file.empty() && entry.mesh_path.empty()
      ? QString::fromStdString(entry.primitive_geometry_type) : QString());
    item->setData(RoleMeshScaleX, entry.mesh_scale_x); item->setData(RoleMeshScaleY, entry.mesh_scale_y); item->setData(RoleMeshScaleZ, entry.mesh_scale_z);
    const bool is_preview_placeholder = category.contains("placeholder", Qt::CaseInsensitive) || category == "warning";
    item->setData(RoleImported, false); item->setData(RoleGeneratedPlaceholder, is_preview_placeholder);
    item->setData(RoleWarning, QString::fromStdString(entry.warnings.empty() ? std::string() : entry.warnings.front()));
    item->setData(RolePoseText, QString("x=%1 y=%2 z=%3 r=%4 p=%5 y=%6").arg(entry.x).arg(entry.y).arg(entry.z).arg(entry.roll).arg(entry.pitch).arg(entry.yaw));
    QString source_layer = QStringLiteral("locked_generated_urdf_visual");
    switch (entry.provenance) {
      case workcell_builder::WorkcellStudioItemProvenance::EditableLayout:
        source_layer = QStringLiteral("editable_layout");
        break;
      case workcell_builder::WorkcellStudioItemProvenance::StaticFallbackPreview:
        source_layer = QStringLiteral("primitive_fallback");
        break;
      case workcell_builder::WorkcellStudioItemProvenance::GeneratedOrLegacyPreview:
      default:
        source_layer = QStringLiteral("locked_generated_urdf_visual");
        break;
    }
    item->setData(RoleSourceLayer, source_layer);
    item->setZValue(canvas_item_z_value(category, QString::fromStdString(entry.role), source_layer, locked_for_canvas));
    item->setFlags(QGraphicsItem::ItemIsSelectable | QGraphicsItem::ItemSendsGeometryChanges | (is_editable_layout_item ? QGraphicsItem::ItemIsMovable : QGraphicsItem::GraphicsItemFlag(0)));
    item->position_filter = [this](const QPointF & p){ return snap_canvas_position(p); };
    digital_twin_scene_->addItem(item);
    add_physical_bounds(item->sceneBoundingRect());

    if (toggle_labels_box_ && toggle_labels_box_->isChecked()) {
      const bool secondary_label = !is_editable_layout_item;
      const bool visible_by_default = should_show_2d_label(entry, preserved_selected_id);
      QString label_text = QString::fromStdString(entry.label);
      if (label_text.trimmed().isEmpty()) label_text = QString::fromStdString(entry.id);
      if (!is_editable_layout_item) label_text = QStringLiteral("🔒 ") + label_text;
      auto * txt = digital_twin_scene_->addSimpleText(compact_canvas_label(label_text));
      QFont label_font = txt->font();
      label_font.setPointSize(secondary_label ? 7 : 8);
      txt->setFont(label_font);
      txt->setBrush(QBrush(secondary_label ? QColor("#a7b0bd") : QColor("#d8dee9")));
      txt->setZValue(item->zValue() + 2.0);
      const bool placed = place_2d_label_without_overlap(txt, item->sceneBoundingRect(), &occupied_label_rects);
      if (!placed && is_important_canvas_anchor(category, QString::fromStdString(entry.role)) &&
          source_layer != QStringLiteral("editable_layout") && item->data(RoleWarning).toString().isEmpty() &&
          item->data(RoleId).toString().trimmed() != preserved_selected_id) {
        delete txt;
        txt = nullptr;
      } else {
        if (!placed) txt->setPos(item->sceneBoundingRect().topLeft() + QPointF(0, -txt->boundingRect().height() - 2));
        item->set_label_item(txt, visible_by_default);
        add_overlay_bounds(txt->sceneBoundingRect());
      }
    }
    if ((!show_camera_fov_overlay_box_ || show_camera_fov_overlay_box_->isChecked()) && category.contains("camera", Qt::CaseInsensitive)) {
      QPolygonF fov; fov << QPointF(item->pos().x()+12, item->pos().y()+12) << QPointF(item->pos().x()+150, item->pos().y()-40) << QPointF(item->pos().x()+150, item->pos().y()+64);
      auto * fov_item = digital_twin_scene_->addPolygon(fov, QPen(QColor("#ffd166"), 2), QBrush(QColor(255, 209, 102, 45))); // camera FOV wedge/cone
      fov_item->setZValue(canvas_item_z_value("camera_fov", "helper_overlay", "overlay", true));
      add_overlay_bounds(fov_item->sceneBoundingRect());
    }
    if (!show_pick_place_overlay_box_ || show_pick_place_overlay_box_->isChecked()) {
      if (category.contains("pick", Qt::CaseInsensitive)) {
        auto * pick_overlay = digital_twin_scene_->addRect(item->sceneBoundingRect().adjusted(-4,-4,4,4), QPen(QColor("#00d1b2"),2,Qt::DashLine));
        pick_overlay->setZValue(canvas_item_z_value("pick_zone", "helper_overlay", "overlay", true));
        add_overlay_bounds(pick_overlay->sceneBoundingRect());
      }
      if (category.contains("place", Qt::CaseInsensitive)) {
        auto * place_overlay = digital_twin_scene_->addRect(item->sceneBoundingRect().adjusted(-4,-4,4,4), QPen(QColor("#ff7b72"),2,Qt::DashLine));
        place_overlay->setZValue(canvas_item_z_value("place_zone", "helper_overlay", "overlay", true));
        add_overlay_bounds(place_overlay->sceneBoundingRect());
      }
    }
    if (toggle_warnings_box_ && toggle_warnings_box_->isChecked() && !item->data(RoleWarning).toString().isEmpty()) {
      auto * w = digital_twin_scene_->addSimpleText(QString("⚠ %1").arg(compact_canvas_label(item->data(RoleWarning).toString())));
      QFont warning_font = w->font();
      warning_font.setPointSize(7);
      w->setFont(warning_font);
      w->setBrush(QBrush(QColor("#ff8e72")));
      w->setZValue(canvas_item_z_value("warning", "label", "overlay", true));
      if (!place_2d_label_without_overlap(w, item->sceneBoundingRect().adjusted(0, item->boundingRect().height() + 2, 0, item->boundingRect().height() + 2), &occupied_label_rects, 2.0)) {
        w->setPos(item->sceneBoundingRect().bottomLeft() + QPointF(0, 2));
      }
      add_overlay_bounds(w->sceneBoundingRect());
    }
  }

  if (model.items.empty()) {
    auto * empty_label = digital_twin_scene_->addSimpleText("No previewable layout metadata. Generate preview/readiness or add layout items.");
    empty_label->setZValue(canvas_item_z_value("warning", "label", "overlay", true));
    empty_label->setPos(-360, -260);
    add_overlay_bounds(empty_label->sceneBoundingRect());
    append_studio_log(QString("Scene canvas: '%1' has 0 editable layout items and 0 URDF visual preview locked items. Missing files may include environment.yaml, scene_manifest.yaml, layout/workcell_studio_layout.yaml.").arg(selected_scene_name()));
  } else {
    append_studio_log(QString("Scene canvas: loaded %1 item(s) for '%2' from %3.").arg(model.items.size()).arg(selected_scene_name(), selected_scene_path()));
  }
  if (!show_trajectory_overlay_box_ || show_trajectory_overlay_box_->isChecked()) {
    auto * trajectory = digital_twin_scene_->addLine(20, 10, 180, -60, QPen(QColor("#38bdf8"), 2, Qt::DashDotLine));
    trajectory->setZValue(canvas_item_z_value("trajectory", "helper_overlay", "overlay", true));
    add_overlay_bounds(trajectory->sceneBoundingRect());
  }
  if (toggle_warnings_box_ && toggle_warnings_box_->isChecked()) {
    QStringList issues;
    if (!s.has_environment_yaml) issues << "missing environment.yaml";
    if (!s.has_package_xml) issues << "missing package.xml";
    if (!s.has_launch_demo) issues << "missing launch/demo.launch.py";
    auto task = load_scene_task_intent_summary(s.scene_dir);
    if (task.status != "READY") issues << "missing task intent";
    if (task.tool_id == "unknown") issues << "missing robot/gripper metadata";
    if (!issues.isEmpty()) {
      auto * safety_warning = digital_twin_scene_->addSimpleText("⚠ " + compact_canvas_label(issues.join(" | ")));
      QFont safety_font = safety_warning->font();
      safety_font.setPointSize(7);
      safety_warning->setFont(safety_font);
      safety_warning->setBrush(QBrush(QColor("#ff8e72")));
      safety_warning->setZValue(canvas_item_z_value("warning", "label", "overlay", true));
      safety_warning->setPos(-380, -280);
      add_overlay_bounds(safety_warning->sceneBoundingRect());
    }
  }
  if (!preserved_selected_id.isEmpty()) {
    apply_scene_selection(preserved_selected_id, QStringLiteral("unknown"), false, false);
  }
  digital_twin_scene_->setProperty("workcellPhysicalBoundsValid", has_physical_bounds);
  digital_twin_scene_->setProperty("workcellPhysicalBounds", physical_bounds);
  digital_twin_scene_->setProperty("workcellOverlayBoundsValid", has_overlay_bounds);
  digital_twin_scene_->setProperty("workcellOverlayBounds", overlay_bounds);
  if (digital_twin_canvas_ && digital_twin_canvas_->scene() && has_physical_bounds) {
    digital_twin_canvas_->fitInView(physical_bounds.adjusted(-24, -24, 24, 24), Qt::KeepAspectRatio);
  }
  refresh_minimap_card();
}

void MainWindow::refresh_scene_builder_left_explorer()
{
  sync_selected_scene_state();
  scene_builder_editor_scene_path_ = selected_scene_path();
  rebuild_digital_twin_canvas();
  populate_scene_hierarchy();
  populate_asset_catalog();
  populate_scene_files_tab();
}

void MainWindow::refresh_scene_builder_view_chips()
{
  bool launch_ready = false;
  if (has_selected_scene()) {
    const auto & s = scene_browser_result_.scenes[static_cast<size_t>(selected_scene_index_)];
    launch_ready = s.has_launch_demo && s.has_package_xml;
  }
  if (scene_builder_launch_chip_) scene_builder_launch_chip_->setText(QString("Launch Artifacts: %1").arg(launch_ready ? "Present" : "Missing"));
  if (scene_builder_safety_chip_) scene_builder_safety_chip_->setText("Safety: Fake hardware");
  if (scene_builder_generate_launch_button_) scene_builder_generate_launch_button_->setVisible(has_selected_scene() && !launch_ready);
  if (canvas_mode_label_) {
    const QString view_label = scene_builder_is_3d_view_ ? "Product View" : "2D Layout Draft";
    const QString base_mode = canvas_mode_label_->text().section("·", 0, 0).trimmed();
    canvas_mode_label_->setText(base_mode + " · " + view_label);
  }
}


void MainWindow::set_canvas_interaction_mode(CanvasInteractionMode mode)
{
  if (mode != CanvasInteractionMode::Place) clear_armed_asset_placement();
  canvas_mode_ = mode;
  QString n = "Select";
  if (mode == CanvasInteractionMode::Place) n = "Place · Q/E rotate · Esc cancel";
  if (mode == CanvasInteractionMode::Move) n = "Move";
  if (mode == CanvasInteractionMode::Inspect) n = "Inspect";
  if (scene_preview_widget_ && scene_preview_widget_->embedded_web_authoring_active()) {
    scene_preview_widget_->set_authoring_mode(
      mode == CanvasInteractionMode::Move ? QStringLiteral("move") : QStringLiteral("select"));
  }
  if (canvas_mode_label_) canvas_mode_label_->setText("Mode: " + n);
  refresh_scene_builder_view_chips();
}

bool MainWindow::eventFilter(QObject * watched, QEvent * event)
{
  // The hierarchy reads Ctrl/Shift from the click itself (global keyboard state can be stale).
  if (scene_hierarchy_tree_ && watched == scene_hierarchy_tree_->viewport() && event &&
      (event->type() == QEvent::MouseButtonPress || event->type() == QEvent::MouseButtonRelease)) {
    hierarchy_click_modifiers_ = static_cast<QMouseEvent *>(event)->modifiers();
  }
  if (scene_builder_path_label_ && watched == scene_builder_path_label_ && event && event->type() == QEvent::Resize) {
    update_scene_builder_path_header(selected_scene_state_.valid ? selected_scene_state_.name : QString(), selected_scene_path());
  }
  if (scene_builder_top_controls_host_ && watched == scene_builder_top_controls_host_->parent() && event &&
    event->type() == QEvent::Resize)
  {
    update_scene_builder_top_controls_overflow();
  }
  if (asset_catalog_tree_ && watched == asset_catalog_tree_->viewport() && event) {
    if (event->type() == QEvent::MouseButtonPress) {
      auto * mouse_event = static_cast<QMouseEvent *>(event);
      if (mouse_event->button() == Qt::LeftButton) catalog_drag_start_ = mouse_event->pos();
    } else if (event->type() == QEvent::MouseMove) {
      auto * mouse_event = static_cast<QMouseEvent *>(event);
      if (!(mouse_event->buttons() & Qt::LeftButton)) return QMainWindow::eventFilter(watched, event);
      if ((mouse_event->pos() - catalog_drag_start_).manhattanLength() < QApplication::startDragDistance()) return QMainWindow::eventFilter(watched, event);
      auto * item = asset_catalog_tree_->itemAt(catalog_drag_start_);
      if (!item) return QMainWindow::eventFilter(watched, event);
      const int idx = item->data(0, CatalogRoleIndex).toInt();
      if (idx < 0 || idx >= asset_catalog_entries_.size()) return QMainWindow::eventFilter(watched, event);
      const auto & e = asset_catalog_entries_[idx];
      if (!item->data(0, CatalogRolePlaceable).toBool() || !e.editable ||
          !e.disabled_reason.trimmed().isEmpty()) {
        const QString reason = !e.disabled_reason.trimmed().isEmpty()
          ? e.disabled_reason : QStringLiteral("asset is not currently placeable");
        QToolTip::showText(QCursor::pos(), QString("Cannot place here: %1").arg(reason), asset_catalog_tree_);
        return true;
      }
      auto * mime = new QMimeData();
      mime->setData(kWorkcellStudioAssetMime, e.asset_id.toUtf8());
      auto * drag = new QDrag(asset_catalog_tree_);
      drag->setMimeData(mime);
      const Qt::DropAction result = drag->exec(Qt::CopyAction);
      if (result == Qt::IgnoreAction && place_asset_armed_ && armed_asset_id_ == e.asset_id) {
        clear_armed_asset_placement();
        set_canvas_interaction_mode(CanvasInteractionMode::Select);
      }
      return true;
    }
  }
  if (digital_twin_canvas_ && watched == digital_twin_canvas_->viewport() &&
    event && event->type() == QEvent::ContextMenu)
  {
    auto * context_event = static_cast<QContextMenuEvent *>(event);
    show_canvas_context_menu(context_event->globalPos());
    return true;
  }
  if (digital_twin_canvas_ && watched == digital_twin_canvas_->viewport() &&
    event && event->type() == QEvent::MouseButtonPress && place_asset_armed_)
  {
    auto * mouse_event = static_cast<QMouseEvent *>(event);
    if (mouse_event->button() == Qt::LeftButton && digital_twin_canvas_->scene()) {
      const QPointF scene_pos = digital_twin_canvas_->mapToScene(mouse_event->pos());
      commit_armed_asset_placement(scene_pos);
      return true;
    }
  }
  return QMainWindow::eventFilter(watched, event);
}

void MainWindow::update_scene_builder_top_controls_overflow()
{
  if (!scene_builder_top_controls_host_ || !scene_builder_secondary_overflow_button_ ||
    !scene_builder_secondary_overflow_menu_)
  {
    return;
  }
  const int available_width = scene_builder_top_controls_host_->parentWidget() ?
    scene_builder_top_controls_host_->parentWidget()->width() : width();
  const bool constrained = available_width < 1280;
  scene_builder_secondary_overflow_menu_->clear();
  auto * scene_builder_view_menu = scene_builder_secondary_overflow_menu_->addMenu("View");
  scene_builder_view_menu->setObjectName("sceneBuilderViewMenu");
  scene_builder_view_menu->addAction(scene_builder_show_left_panel_action_);
  scene_builder_view_menu->addAction(scene_builder_show_right_panel_action_);
  scene_builder_view_menu->addAction(scene_builder_focus_3d_action_);
  auto * secondary_layout_menu = scene_builder_secondary_overflow_menu_->addMenu("Layout");
  secondary_layout_menu->addAction(scene_builder_action("layout.undo"));
  secondary_layout_menu->addAction(scene_builder_action("layout.redo"));
  secondary_layout_menu->addAction(scene_builder_action("layout.save"));
  secondary_layout_menu->addAction(scene_builder_action("layout.duplicate"));
  secondary_layout_menu->addAction(scene_builder_action("layout.remove"));
  scene_builder_secondary_overflow_menu_->addAction(scene_builder_action("operate.operator_preview"));
  const auto remap_menu = [this](QToolButton * button) {
      if (!button || !button->menu()) return;
      scene_builder_secondary_overflow_menu_->addMenu(button->menu());
    };
  if (constrained) {
    remap_menu(scene_builder_camera_view_button_);
    remap_menu(scene_builder_overlays_button_);
    remap_menu(scene_builder_canvas_more_button_);
    remap_menu(scene_builder_visual_modes_button_);
  }
  if (scene_builder_camera_view_button_) scene_builder_camera_view_button_->setVisible(!constrained);
  if (scene_builder_overlays_button_) scene_builder_overlays_button_->setVisible(!constrained);
  if (scene_builder_canvas_more_button_) scene_builder_canvas_more_button_->setVisible(!constrained);
  if (scene_builder_visual_modes_button_) scene_builder_visual_modes_button_->setVisible(!constrained);
  scene_builder_secondary_overflow_button_->setVisible(constrained);
}

void MainWindow::sync_scene_builder_view_actions()
{
  scene_builder_panel_state_syncing_ = true;
  if (scene_builder_show_left_panel_action_ && scene_builder_left_panel_) {
    const QSignalBlocker blocker(scene_builder_show_left_panel_action_);
    scene_builder_show_left_panel_action_->setChecked(!scene_builder_left_panel_->isHidden());
  }
  if (scene_builder_show_right_panel_action_ && scene_builder_right_panel_) {
    const QSignalBlocker blocker(scene_builder_show_right_panel_action_);
    scene_builder_show_right_panel_action_->setChecked(!scene_builder_right_panel_->isHidden());
  }
  if (scene_builder_focus_3d_action_) {
    const QSignalBlocker blocker(scene_builder_focus_3d_action_);
    scene_builder_focus_3d_action_->setChecked(scene_builder_focus_3d_active_);
  }
  scene_builder_panel_state_syncing_ = false;
}

void MainWindow::save_scene_builder_panel_state()
{
  if (!scene_builder_splitter_ || scene_builder_focus_3d_active_ || scene_builder_panel_state_syncing_) return;
  // Before its first layout a splitter reports sizes proportional to Qt's ~100 px default width
  // (e.g. 33/33/32); persisting those overwrote the user's panel widths on every start. Only a visible,
  // laid-out splitter (the only kind a user can drag) is saved.
  if (!scene_builder_splitter_->isVisible() || scene_builder_splitter_->width() < 400) return;
  const QList<int> sizes = scene_builder_splitter_->sizes();
  if (sizes.size() != 3) return;
  // Hidden panes report zero.  Only a visible, non-zero pane may update its
  // independently remembered width.
  if (scene_builder_left_panel_ && !scene_builder_left_panel_->isHidden() && sizes[0] > 0)
    scene_builder_preferred_left_width_ = sizes[0];
  if (scene_builder_right_panel_ && !scene_builder_right_panel_->isHidden() && sizes[2] > 0)
    scene_builder_preferred_right_width_ = sizes[2];
  scene_builder_last_splitter_sizes_ = {
    scene_builder_preferred_left_width_, qMax(1, sizes[1]), scene_builder_preferred_right_width_};

  QSettings settings;
  QVariantList persisted_sizes;
  for (const int size : scene_builder_last_splitter_sizes_) persisted_sizes.append(size);
  settings.setValue(QStringLiteral("scene_builder/main_splitter_sizes"), persisted_sizes);
  settings.setValue(QStringLiteral("scene_builder/preferred_left_width"), scene_builder_preferred_left_width_);
  settings.setValue(QStringLiteral("scene_builder/preferred_right_width"), scene_builder_preferred_right_width_);
  settings.setValue(QStringLiteral("scene_builder/left_panel_visible"),
    scene_builder_left_panel_ && !scene_builder_left_panel_->isHidden());
  settings.setValue(QStringLiteral("scene_builder/right_panel_visible"),
    scene_builder_right_panel_ && !scene_builder_right_panel_->isHidden());
  settings.setValue(QStringLiteral("scene_builder/native_layout_version"), 3);
}

void MainWindow::apply_scene_builder_panel_visibility(
  bool left_visible, bool right_visible, bool persist)
{
  if (!scene_builder_splitter_ || !scene_builder_left_panel_ || !scene_builder_right_panel_) return;
  scene_builder_panel_state_syncing_ = true;
  scene_builder_left_panel_->setVisible(left_visible);
  scene_builder_right_panel_->setVisible(right_visible);

  const QList<int> current = scene_builder_splitter_->sizes();
  const int measured_total = scene_builder_splitter_->width();
  const int total = qMax(900, measured_total > 0 ? measured_total :
    current.value(0) + current.value(1) + current.value(2));
  const int center_minimum = qMin(720, qMax(520, total / 2));
  int left = left_visible ? qMax(1, scene_builder_preferred_left_width_) : 0;
  int right = right_visible ? qMax(1, scene_builder_preferred_right_width_) : 0;
  if (left_visible) left = qMin(left, qMax(1, total - center_minimum - right));
  if (right_visible) {
    const int right_available = qMax(1, total - center_minimum - left);
    right = qMin(qMax(240, right), right_available);
  }
  const int center = qMax(1, total - left - right);
  scene_builder_splitter_->setSizes({left, center, right});
  scene_builder_panel_state_syncing_ = false;
  sync_scene_builder_view_actions();
  if (persist) save_scene_builder_panel_state();
}

QPointF MainWindow::snap_canvas_position(const QPointF & pos) const
{
  if (!snap_to_grid_box_ || !snap_to_grid_box_->isChecked()) return pos;
  const double step_px = std::max(1.0, snap_step_m_ * 100.0);
  return QPointF(std::round(pos.x() / step_px) * step_px, std::round(pos.y() / step_px) * step_px);
}

void MainWindow::refresh_minimap_card()
{
  if (!minimap_view_ || !digital_twin_scene_) return;
  if (!minimap_scene_) minimap_scene_ = new QGraphicsScene(minimap_view_);
  minimap_scene_->clear();
  QRectF physical_bounds;
  bool has_physical_items = false;
  for (auto * gi : digital_twin_scene_->items()) {
    if (!gi->data(RoleRole).isValid() || gi->data(RoleRole).toString() != "asset") continue;
    if (!has_physical_items) {
      physical_bounds = gi->sceneBoundingRect();
      has_physical_items = true;
    } else {
      physical_bounds = physical_bounds.united(gi->sceneBoundingRect());
    }
    minimap_scene_->addRect(gi->sceneBoundingRect(), QPen(QColor("#94a3b8"), 1), QBrush(QColor(148,163,184,90)));
  }
  if (!has_physical_items) {
    minimap_view_->setVisible(false);
    return;
  }
  const QRectF padded_bounds = physical_bounds.adjusted(-20.0, -20.0, 20.0, 20.0);
  minimap_scene_->setSceneRect(padded_bounds);
  if (digital_twin_canvas_) {
    const QRect viewport = digital_twin_canvas_->viewport()->rect();
    const QRectF visible_rect = digital_twin_canvas_->mapToScene(viewport).boundingRect();
    minimap_scene_->addRect(visible_rect, QPen(QColor("#38bdf8"), 2), Qt::NoBrush);
  }
  minimap_view_->setScene(minimap_scene_);
  update_minimap_backend_presentation();
  minimap_view_->fitInView(padded_bounds, Qt::KeepAspectRatio);
}

void MainWindow::update_minimap_backend_presentation()
{
  if (!minimap_view_ || !scene_preview_widget_) return;

  const bool embedded_web3d_presented =
    scene_preview_widget_->embedded_web_product_view_presented();
  if (embedded_web3d_presented) {
    minimap_view_->setVisible(false);
    minimap_view_->setMinimumSize(0, 0);
    minimap_view_->setMaximumSize(0, 0);
    return;
  }

  minimap_view_->setMinimumSize(150, 90);
  minimap_view_->setMaximumSize(150, 90);
  minimap_view_->setVisible(minimap_requested_visible_);
}

void MainWindow::select_canvas_item(QGraphicsItem * item)
{
  if (!item || !inspector_label_) return;
  refresh_selection_transform_editor_from_item(item);
  inspector_update_guard_ = true;
  refresh_selected_scene_item_labels(current_selected_scene_item());
  const QString warning_text = item->data(RoleWarning).toString().isEmpty() ? QString("none") : item->data(RoleWarning).toString();
  inspector_warning_label_->setText(warning_text == "none" ? "No item warnings" : "Warning: " + warning_text);
  append_studio_log("selected item reach status: preview-only");
  append_studio_log("selected item collision status: preview-only");
  if (pick_place_details_label_) pick_place_details_label_->setText(pick_place_details_label_->text() + QStringLiteral("\nLinked hierarchy item: %1").arg(item->data(RoleId).toString()));
  inspector_update_guard_ = false;
}

void MainWindow::apply_scene_selection(const QString & id, const QString & role, bool intentional_clear, bool center_canvas)
{
  if (mate_active() && !mate_selection_passthrough_) {
    // While mating, a hierarchy click or an asset-level viewport click chooses
    // the part for the current step; it never changes the mate behind its back.
    if (!id.trimmed().isEmpty()) mate_controller_->hint_asset(id.trimmed());
    return;
  }
  sync_selected_scene_state();
  const QString selected_id = id.trimmed();
  const QString selected_role = role.trimmed().isEmpty() ? QStringLiteral("unknown") : role.trimmed();
  // A plain selection replaces the multi-selection; internal re-selection of the
  // reference (Ctrl+click, Make Reference) keeps it. Views follow on every exit path.
  if (!selection_set_passthrough_) {
    if (!selected_id.isEmpty()) selection_set_.select_only(selected_id);
    else if (intentional_clear) selection_set_.clear();
  }
  struct SyncSelectionOnExit { MainWindow * window; ~SyncSelectionOnExit() { window->sync_selection_set_views(); } } sync_on_exit{this};

  if (selected_id.isEmpty()) {
    if (!intentional_clear) return;
    current_selected_scene_item_id_.clear();
    selection_update_guard_ = true;
    if (scene_hierarchy_tree_) {
      scene_hierarchy_tree_->clearSelection();
      scene_hierarchy_tree_->setCurrentItem(nullptr);
    }
    if (digital_twin_scene_) digital_twin_scene_->clearSelection();
    if (scene_preview_widget_) scene_preview_widget_->select_preview_item(QString());
    selection_update_guard_ = false;
    sync_selected_item_state();
    refresh_selected_scene_item_labels(selected_item_state_);
    refresh_selected_item_card();
    refresh_delete_selected_action();
    refresh_duplicate_selected_action();
    append_studio_log("Selected item: <none> (unknown)");
    return;
  }

  const auto find_preview_item_by_id = [&](const QString & stable_id) -> const ScenePreviewWidget::PreviewItem * {
    const QString trimmed_id = stable_id.trimmed();
    if (trimmed_id.isEmpty()) return nullptr;
    for (const auto & item : all_scene_preview_items_) {
      if (item.id.trimmed() == trimmed_id) return &item;
    }
    return scene_preview_widget_ ? scene_preview_widget_->preview_item_by_id(trimmed_id) : nullptr;
  };
  const ScenePreviewWidget::PreviewItem * matched_preview_item = find_preview_item_by_id(selected_id);
  bool active_scene_item_present = matched_preview_item != nullptr;
  if (!active_scene_item_present && scene_hierarchy_tree_) {
    for (int row = 0; row < scene_hierarchy_tree_->topLevelItemCount() && !active_scene_item_present; ++row) {
      auto * tree_item = scene_hierarchy_tree_->topLevelItem(row);
      if (!tree_item) continue;
      active_scene_item_present = tree_item->data(0, TreeRoleId).toString().trimmed() == selected_id;
      for (int child = 0; child < tree_item->childCount() && !active_scene_item_present; ++child) {
        auto * node = tree_item->child(child);
        active_scene_item_present = node && node->data(0, TreeRoleId).toString().trimmed() == selected_id;
      }
    }
  }
  if (!active_scene_item_present && digital_twin_scene_) {
    for (auto * item : digital_twin_scene_->items()) {
      if (item && item->data(RoleId).toString().trimmed() == selected_id) {
        active_scene_item_present = true;
        break;
      }
    }
  }

  // A non-empty ID is a selection attempt, never an implicit clear. Web3D may
  // receive stale task references (for example commissioning_object) that are
  // not placed objects in the active payload. Preserve the valid selection and
  // report each missing ID only once for this scene payload.
  if (!active_scene_item_present) {
    const QString scene_key = selected_scene_state_.name.trimmed().isEmpty() ? selected_scene_name() : selected_scene_state_.name.trimmed();
    const QString warning_key = QStringLiteral("missing_scene_selection|%1|%2").arg(scene_key, selected_id);
    if (!emitted_scene_diagnostic_log_keys_.contains(warning_key)) {
      emitted_scene_diagnostic_log_keys_.insert(warning_key);
      append_studio_log(
        QStringLiteral("Ignored selection id absent from active scene payload; existing selection preserved: %1").arg(selected_id),
        workcell_builder::StudioLogSeverity::Warning,
        warning_key);
    }
    return;
  }

  current_selected_scene_item_id_ = selected_id;
  selection_update_guard_ = true;

  bool matched_tree_item = false;
  if (scene_hierarchy_tree_) {
    QTreeWidgetItem * matched = nullptr;
    for (QTreeWidgetItemIterator it(scene_hierarchy_tree_); *it && !matched; ++it) {
      if ((*it)->data(0, TreeRoleId).toString().trimmed() == selected_id) matched = *it;
    }
    if (matched) {
      matched_tree_item = true;
      scene_hierarchy_tree_->setCurrentItem(matched);
    }
  }

  QGraphicsItem * matched_canvas_item = nullptr;
  if (digital_twin_scene_) {
    for (auto * gi : digital_twin_scene_->items()) {
      if (gi && gi->data(RoleId).toString().trimmed() == selected_id) {
        matched_canvas_item = gi;
        break;
      }
    }
    if (matched_canvas_item) {
      digital_twin_scene_->clearSelection();
      matched_canvas_item->setSelected(true);
      if (center_canvas && digital_twin_canvas_) digital_twin_canvas_->centerOn(matched_canvas_item);
      if (auto * rect = qgraphicsitem_cast<QGraphicsRectItem *>(matched_canvas_item)) {
        rect->setPen(QPen(QColor("#f8fafc"), 3));
      }
    } else {
      digital_twin_scene_->clearSelection();
    }
  }

  // The Web3D mate overlay highlights the mate's parts itself; its selection and gizmo stay put.
  if (scene_preview_widget_ && !(mate_selection_passthrough_ && scene_preview_widget_->embedded_web_authoring_active())) {
    scene_preview_widget_->select_preview_item(selected_id);
  }
  selection_update_guard_ = false;

  const bool selection_resolved = matched_tree_item || matched_canvas_item || matched_preview_item;
  if (!selection_resolved) return;

  if (matched_canvas_item) {
    select_canvas_item(matched_canvas_item);
  } else {
    sync_selected_item_state();
    refresh_selected_scene_item_labels(selected_item_state_);
    refresh_selection_transform_editor_from_state(selected_item_state_);
  }
  if (scene_builder_right_panel_) {
    // Selecting reveals a hidden Inspector; it must not re-apply remembered widths to
    // panels that are already shown, or every selection makes the panels jump.
    if (scene_builder_right_panel_->isHidden())
      apply_scene_builder_panel_visibility(
        scene_builder_left_panel_ && !scene_builder_left_panel_->isHidden(), true);
    if (scene_builder_inspector_tabs_) {
      const int selection_tab = 0;
      scene_builder_inspector_tabs_->setCurrentIndex(selection_tab);
    }
  }

  const auto selected_state = current_selected_scene_item();
  refresh_selected_item_card();
  const QString selected_scene_name_for_log = selected_scene_state_.valid ? selected_scene_state_.name : QStringLiteral("unknown");
  const QString selected_source_layer_for_log = selected_state.source_layer.isEmpty() ? QStringLiteral("unknown") : selected_state.source_layer;
  append_studio_log(QString("Scene3D selection changed: scene=%1 id=%2 editable=%3 locked=%4 source_layer=%5")
    .arg(selected_scene_name_for_log, selected_id,
      selected_state.editable ? "true" : "false", selected_state.locked ? "true" : "false",
      selected_source_layer_for_log));
  append_studio_log(QString("Selected item: %1 (%2) type=%3 source=%4 editable=%5 locked=%6")
    .arg(selected_id, selected_role, selected_state.role_or_category, selected_state.source_path,
      selected_state.editable ? "true" : "false", selected_state.locked ? "true" : "false"));
  refresh_delete_selected_action();
  refresh_duplicate_selected_action();
}

void MainWindow::mark_layout_dirty(const QString & reason)
{
  // Preserve the dirty authoring snapshot assembled by Inspector Apply. A
  // Product View refresh can transiently report the pre-edit preview pose;
  // recapturing here would overwrite the pending authored value immediately
  // before serialization.
  if (!layout_dirty_) capture_active_editable_layout_session();
  layout_dirty_ = true;
  schedule_operator_preview_update();
  layout_saved_ = false;
  notify_mate_scene_changed();
  validation_stale_ = true;
  launch_artifacts_ready_ = false;
  // Structural edits are native-session authority even when Web3D owns the
  // visible editor. Do not wait for (or let) browser polling hide this state.
  if (save_layout_button_) save_layout_button_->setEnabled(!read_only_preview_active());
  if (save_layout_button_) {
    save_layout_button_->setProperty("layoutDirty", true);
    setWindowModified(true);
    save_layout_button_->style()->unpolish(save_layout_button_);
    save_layout_button_->style()->polish(save_layout_button_);
  }
  if (layout_state_label_) {
    layout_state_label_->setText(QString("Unsaved Layout Edits: %1").arg(reason));
  }
}

void MainWindow::capture_active_editable_layout_session()
{
  // Keyed by canonical scene path, not display name: two checkouts can hold a
  // cell with the same name, and the retained session must never leak across.
  const QString scene_key = selected_scene_path().trimmed();
  if (scene_key.isEmpty()) return;
  if (editable_layout_session_scene_name_ != scene_key) {
    editable_layout_session_items_.clear();
    editable_layout_session_scene_name_ = scene_key;
  }

  editable_layout_session_items_.clear();
  for (auto preview_item : all_scene_preview_items_) {
    if (preview_item.source_layer != QStringLiteral("editable_layout") ||
        !preview_item.editable || preview_item.locked ||
        deleted_layout_item_ids_.contains(preview_item.id)) continue;
    if (auto * canvas_item = find_canvas_item_by_stable_id(preview_item.id)) {
      preview_item.x = canvas_item->pos().x() / 100.0;
      preview_item.y = canvas_item->pos().y() / 100.0;
      preview_item.z = canvas_item->data(RolePoseZ).toDouble();
      preview_item.roll = canvas_item->data(RoleRoll).toDouble();
      preview_item.pitch = canvas_item->data(RolePitch).toDouble();
      preview_item.yaw = canvas_item->data(RoleYaw).toDouble();
      preview_item.sx = canvas_item->data(RoleWidth).toDouble();
      preview_item.sy = canvas_item->data(RoleDepth).toDouble();
      preview_item.sz = canvas_item->data(RoleHeight).toDouble();
      preview_item.source_path = canvas_item->data(RoleSource).toString();
    }
    editable_layout_session_items_.push_back(preview_item);
  }
  // Some authored physical items are represented by a derived preview record
  // rather than a native canvas item. Preserve the selected editable record
  // in the same session projection so Save Layout serializes its Inspector
  // pose along with ordinary canvas-backed items.
  const auto selected = current_selected_scene_item();
  if (selected.valid && selected.editable && !selected.locked &&
      selected.source_layer.compare(QStringLiteral("editable_layout"), Qt::CaseInsensitive) == 0) {
    bool present = false;
    for (auto & item : editable_layout_session_items_) {
      if (item.id != selected.id) continue;
      present = true; item.x = selected.pose_x; item.y = selected.pose_y; item.z = selected.pose_z;
      item.roll = selected.roll; item.pitch = selected.pitch; item.yaw = selected.yaw;
      item.sx = selected.dim_x; item.sy = selected.dim_y; item.sz = selected.dim_z;
    }
    if (!present) {
      ScenePreviewWidget::PreviewItem item;
      item.id = selected.id; item.display_name = selected.display_name; item.category = selected.category;
      item.role = selected.role; item.x = selected.pose_x; item.y = selected.pose_y; item.z = selected.pose_z;
      item.roll = selected.roll; item.pitch = selected.pitch; item.yaw = selected.yaw;
      item.sx = selected.dim_x; item.sy = selected.dim_y; item.sz = selected.dim_z;
      item.source_layer = selected.source_layer; item.source_path = selected.source_path;
      item.editable = true; item.locked = false;
      editable_layout_session_items_.push_back(item);
    }
  }
}

void MainWindow::merge_active_editable_layout_session(
  workcell_builder::WorkcellStudioCanvasModel * model) const
{
  if (!model || !layout_dirty_ ||
      editable_layout_session_scene_name_ != selected_scene_path().trimmed()) return;
  std::vector<workcell_builder::WorkcellStudioCanvasItem> session_items;
  for (const auto & item : editable_layout_session_items_) {
    if (deleted_layout_item_ids_.contains(item.id)) continue;
    workcell_builder::WorkcellStudioCanvasItem canvas_item;
    canvas_item.id = item.id.toStdString();
    canvas_item.catalog_asset_id = item.catalog_asset_id.toStdString();
    canvas_item.label = item.display_name.toStdString();
    canvas_item.type = item.category.toStdString();
    canvas_item.category = item.category.toStdString();
    canvas_item.role = item.role.toStdString();
    canvas_item.source_file = item.source_path.toStdString();
    canvas_item.mesh_path = item.mesh_path.toStdString();
    canvas_item.mesh_type = item.mesh_type.toStdString();
    canvas_item.primitive_geometry_type = item.primitive_geometry_type.toStdString();
    canvas_item.x = item.x; canvas_item.y = item.y; canvas_item.z = item.z;
    canvas_item.roll = item.roll; canvas_item.pitch = item.pitch; canvas_item.yaw = item.yaw;
    canvas_item.width = item.sx; canvas_item.depth = item.sy; canvas_item.height = item.sz;
    canvas_item.mesh_scale_x = item.mesh_scale_x;
    canvas_item.mesh_scale_y = item.mesh_scale_y;
    canvas_item.mesh_scale_z = item.mesh_scale_z;
    canvas_item.has_mesh_metadata = item.has_mesh_metadata;
    canvas_item.mesh_available = item.mesh_available;
    canvas_item.mesh_load_warning = item.mesh_load_warning.toStdString();
    canvas_item.provenance = workcell_builder::WorkcellStudioItemProvenance::EditableLayout;
    canvas_item.editable = true;
    canvas_item.locked = false;
    session_items.push_back(canvas_item);
  }
  std::vector<std::string> deleted_item_ids;
  deleted_item_ids.reserve(deleted_layout_item_ids_.size());
  for (const auto & id : deleted_layout_item_ids_) deleted_item_ids.push_back(id.toStdString());
  workcell_builder::merge_dirty_editable_layout_session(*model, session_items, deleted_item_ids);
}

using workcell_builder::resolve_visual_mesh_source_path;
using workcell_builder::workcell_builder_repo_root_from_source;

static QStringList generation_asset_support_preflight(const fs::path & layout_path, bool * severe_failure)
{
  if (severe_failure) *severe_failure = false;
  QStringList warnings;
  if (layout_path.empty() || !fs::exists(layout_path)) {
    warnings << "Asset support preflight: no saved layout found; generation may proceed with defaults.";
    return warnings;
  }
  YAML::Node root;
  try { root = YAML::LoadFile(layout_path.string()); }
  catch (const std::exception & exc) {
    warnings << QString("Asset support preflight warning: malformed saved layout at '%1' (%2); generation proceeds with defaults.")
      .arg(QString::fromStdString(layout_path.string()), QString::fromStdString(exc.what()));
    return warnings;
  }
  YAML::Node placed = workcell_builder::yaml_map_key(root, "items");
  if (!placed || !placed.IsSequence()) placed = workcell_builder::yaml_map_key(root, "placed_assets");
  if (!placed || !placed.IsSequence()) return warnings;
  const QSet<QString> supported_types = {"asset","object","fixture","support_surface","table","conveyor","camera","sensor","safety_zone","bin","target_bin","realsense","pick_zone","place_zone"};
  for (const auto & item : placed) {
    if (!item || !item.IsMap()) {
      warnings << "Asset support preflight warning: placed_assets item is not a map; skipping malformed entry.";
      continue;
    }
    const QString id = QString::fromStdString(workcell_builder::yaml_map_value_or_empty(item, "id"));
    const QString raw_type = QString::fromStdString(workcell_builder::yaml_map_value_or_empty(item, "type"));
    const QString type = raw_type.trimmed().toLower();
    if (!type.isEmpty() && !supported_types.contains(type)) {
      warnings << QString("Asset support preflight: unsupported placed asset id='%1' type='%2'. Expected behavior: generator keeps metadata and may skip geometry/runtime wiring for this item.")
        .arg(id.isEmpty() ? "unknown" : id, raw_type);
    }
  }
  return warnings;
}

static bool is_safe_scene_relative_path(const fs::path & candidate)
{
  if (candidate.empty() || candidate.is_absolute()) return false;
  for (const auto & part : candidate) {
    if (part.string() == "..") return false;
  }
  return true;
}

static fs::path manifest_declared_layout_path(const fs::path & scene_dir)
{
  const fs::path manifest_path = scene_dir / "scene_manifest.yaml";
  if (!fs::exists(manifest_path)) return {};
  try {
    const YAML::Node manifest = YAML::LoadFile(manifest_path.string());
    const YAML::Node files = workcell_builder::yaml_map_key(manifest, "files");
    std::string declared;
    if (files && files.IsMap()) {
      declared = workcell_builder::yaml_map_value_or_empty(files, "layout");
      if (declared.empty()) declared = workcell_builder::yaml_map_value_or_empty(files, "editable_layout");
      if (declared.empty()) declared = workcell_builder::yaml_map_value_or_empty(files, "workcell_studio_layout");
    }
    if (declared.empty()) declared = workcell_builder::yaml_map_value_or_empty(manifest, "layout");
    const fs::path relative(declared);
    if (!is_safe_scene_relative_path(relative)) return {};
    return scene_dir / relative;
  } catch (const YAML::Exception &) {
    return {};
  } catch (const std::exception &) {
    return {};
  }
}

[[maybe_unused]] static fs::path selected_scene_canonical_layout_save_path(const workcell_builder::WorkcellStudioSceneBrowserResult & browser, int selected_scene_index)
{
  if (selected_scene_index < 0 || selected_scene_index >= static_cast<int>(browser.scenes.size())) return {};
  const fs::path scene_dir = browser.scenes[static_cast<size_t>(selected_scene_index)].scene_dir;
  return scene_dir / "layout" / "workcell_studio_layout.yaml";
}

static std::vector<fs::path> selected_scene_layout_import_candidates(const fs::path & scene_dir)
{
  std::vector<fs::path> candidates;
  const fs::path canonical_layout = scene_dir / "layout" / "workcell_studio_layout.yaml";
  const fs::path legacy_environment_layout = scene_dir / "environment_layout.yaml";
  const fs::path manifest_layout = manifest_declared_layout_path(scene_dir);

  auto append_unique = [&candidates](const fs::path & candidate) {
    if (candidate.empty()) return;
    if (std::find(candidates.begin(), candidates.end(), candidate) == candidates.end()) {
      candidates.push_back(candidate);
    }
  };

  append_unique(canonical_layout);
  append_unique(legacy_environment_layout);
  append_unique(manifest_layout);
  return candidates;
}

static fs::path selected_scene_existing_layout_import_path(const workcell_builder::WorkcellStudioSceneBrowserResult & browser, int selected_scene_index)
{
  if (selected_scene_index < 0 || selected_scene_index >= static_cast<int>(browser.scenes.size())) return {};
  const fs::path scene_dir = browser.scenes[static_cast<size_t>(selected_scene_index)].scene_dir;
  for (const auto & candidate : selected_scene_layout_import_candidates(scene_dir)) {
    if (fs::exists(candidate)) return candidate;
  }
  return {};
}

[[maybe_unused]] static YAML::Node minimal_environment_layout(const std::string & scene_name)
{
  YAML::Node root(YAML::NodeType::Map);
  root["schema_version"] = "environment_layout/v1";
  root["scene_name"] = scene_name;
  root["placed_assets"] = YAML::Node(YAML::NodeType::Sequence);
  return root;
}

static YAML::Node ensure_sequence_of_maps(YAML::Node root, const char * key)
{
  if (!root[key] || !root[key].IsSequence()) {
    root[key] = YAML::Node(YAML::NodeType::Sequence);
  }
  return root[key];
}

static YAML::Node ensure_map_node(YAML::Node parent, const char * key)
{
  if (!parent[key] || !parent[key].IsMap()) parent[key] = YAML::Node(YAML::NodeType::Map);
  return parent[key];
}


static YAML::Node normalize_imported_layout_to_canonical_items(const YAML::Node & imported_root, const std::string & scene_name)
{
  YAML::Node root = (imported_root && imported_root.IsMap()) ? YAML::Clone(imported_root) : YAML::Node(YAML::NodeType::Map);
  YAML::Node canonical_items(YAML::NodeType::Sequence);
  QSet<QString> seen_ids;

  auto append_item = [&](const YAML::Node & source) {
    if (!source || !source.IsMap()) return;
    YAML::Node item = YAML::Clone(source);
    const QString id = QString::fromStdString(workcell_builder::yaml_map_value_or_empty(item, "id")).trimmed();
    if (!id.isEmpty()) {
      if (seen_ids.contains(id)) return;
      seen_ids.insert(id);
    }
    if (!item["scene_name"] || !item["scene_name"].IsScalar()) item["scene_name"] = scene_name;
    item["scene_path"] = ".";
    canonical_items.push_back(item);
  };

  const std::array<const char *, 6> legacy_sequence_keys = {
    "items", "assets", "placed_assets", "objects", "zones", "targets"
  };
  for (const char * key : legacy_sequence_keys) {
    const YAML::Node seq = root[key];
    if (!seq || !seq.IsSequence()) continue;
    for (std::size_t i = 0; i < seq.size(); ++i) append_item(seq[i]);
  }
  const YAML::Node camera = root["camera"];
  if (camera && camera.IsMap()) append_item(camera);

  for (const char * key : legacy_sequence_keys) root.remove(key);
  root.remove("camera");
  root["schema_version"] = "workcell_studio_layout/v1";
  root["schema"] = "workcell_studio_layout/v1";
  root["scene_name"] = scene_name;
  root["scene_path"] = ".";
  root["items"] = canonical_items;
  YAML::Node meta = ensure_map_node(root, "metadata");
  meta["canonical_layout_path"] = "layout/workcell_studio_layout.yaml";
  meta["legacy_import_normalized_keys"] = "items,assets,placed_assets,objects,zones,targets,camera";
  return root;
}

static YAML::Node serialized_editable_canvas_item(QGraphicsItem * gi, const YAML::Node & existing)
{
  workcell_builder::LayoutItemSaveState state;
  state.id = gi->data(RoleId).toString().toStdString();
  state.display_name = gi->data(RoleDisplayName).toString().toStdString();
  state.type = gi->data(RoleType).toString().toStdString();
  state.category = gi->data(RoleCategory).toString().toStdString();
  state.role = gi->data(RoleRole).toString().toStdString();
  if (existing && existing.IsMap() && existing["role"] && existing["role"].IsScalar()) {
    // Mount, Mate, Align and undo carry the display-normalised role ("place_target_bin");
    // Save keeps the authored role ("target_bin") unless the user chose another one.
    const QString authored = QString::fromStdString(existing["role"].Scalar());
    const QString category = existing["category"] && existing["category"].IsScalar()
      ? QString::fromStdString(existing["category"].Scalar()) : QString();
    state.role = workcell_builder::semantic_role_to_persist(QString::fromStdString(state.role), authored,
      canonical_scene_hierarchy_role(authored, category, QString())).toStdString();
  }
  state.catalog_asset_id = gi->data(RoleCatalogAssetId).toString().toStdString();
  QString portable_mesh_path = QDir::fromNativeSeparators(gi->data(RoleSource).toString().trimmed());
  const int scenes_marker = portable_mesh_path.indexOf(QStringLiteral("/scenes/"));
  const int assets_marker = scenes_marker >= 0 ? portable_mesh_path.indexOf(QStringLiteral("/assets/"), scenes_marker + 8) : -1;
  if (assets_marker >= 0) portable_mesh_path = portable_mesh_path.mid(assets_marker + 1);
  state.mesh_path = portable_mesh_path.toStdString();
  state.geometry_type = gi->data(RoleGeometryType).toString().toStdString();
  if (!state.geometry_type.empty()) state.mesh_path.clear();
  state.source_package = gi->data(RoleSourcePackage).toString().toStdString();
  state.xyz = {{gi->pos().x() / 100.0, gi->pos().y() / 100.0, gi->data(RolePoseZ).toDouble()}};
  state.rpy = {{gi->data(RoleRoll).toDouble(), gi->data(RolePitch).toDouble(), gi->data(RoleYaw).toDouble()}};
  state.dimensions = {{gi->data(RoleWidth).toDouble(), gi->data(RoleDepth).toDouble(), gi->data(RoleHeight).toDouble()}};
  state.mesh_scale = {{
    gi->data(RoleMeshScaleX).isValid() ? gi->data(RoleMeshScaleX).toDouble() : 1.0,
    gi->data(RoleMeshScaleY).isValid() ? gi->data(RoleMeshScaleY).toDouble() : 1.0,
    gi->data(RoleMeshScaleZ).isValid() ? gi->data(RoleMeshScaleZ).toDouble() : 1.0}};
  auto result = workcell_builder::serialize_layout_item(
    state, existing, gi->data(RoleMetadataExplicitlyEdited).toBool());
  const auto metadata = YAML::Load(gi->data(RoleMountingYaml).toString().toStdString());
  for (const char * key : {"parent_object", "parent_link", "joint_type", "origin", "mounting_anchors", "mate"}) {
    if (metadata && metadata[key]) result[key] = YAML::Clone(metadata[key]);
    else result.remove(key);
  }
  return result;
}

bool MainWindow::read_only_preview_active() const
{
  return scene_preview_widget_ && scene_preview_widget_->property("diagnostic_preview_active").toBool();
}

void MainWindow::save_layout_changes(){
  if (read_only_preview_active()) {
    // Ctrl+S included: a diagnostic preview never writes authored files.
    statusBar()->showMessage(QStringLiteral("Save Layout is disabled: this cell is a read-only diagnostic preview."), 6000);
    append_studio_log(QStringLiteral("Save Layout refused: read-only diagnostic preview."));
    return;
  }
  if (environment_task_editor_ && environment_task_editor_->scene() == selected_scene_path() && environment_task_editor_->dirty()) {
    QString error;
    if (!environment_task_editor_->save(&error)) { append_studio_log("Save blocked: " + error); show_workflow_feedback("error", "Save blocked: " + error); return; }
  }
  if (scene_preview_widget_ && scene_preview_widget_->embedded_web_authoring_active()) {
    scene_preview_widget_->request_authoring_save();
    return;
  }
  save_native_layout_changes(QJsonObject{});
}

bool MainWindow::apply_web_transforms_to_editable_layout_session(
  const QJsonObject & web_patch, QString * error)
{
  struct ValidatedTransform
  {
    QGraphicsItem * canvas{nullptr};
    QString id;
    double x{0.0}, y{0.0}, z{0.0}, roll{0.0}, pitch{0.0}, yaw{0.0};
  };
  QVector<ValidatedTransform> validated;
  QSet<QString> seen_ids;
  const QSet<QString> task_destination_ids = scene_task_destination_ids();
  const QJsonArray edits = web_patch.value(QStringLiteral("edits")).toArray();
  for (const auto & value : edits) {
    const QJsonObject edit = value.toObject();
    const QString id = edit.value(QStringLiteral("item_id")).toString().trimmed();
    if (id.isEmpty() || seen_ids.contains(id) ||
        edit.value(QStringLiteral("operation")).toString() != QStringLiteral("update_transform")) {
      if (error) *error = QStringLiteral(
        "Browser edit '%1' is missing, duplicated, or unsupported. No file was written; the unified authored session remains dirty.")
        .arg(id.isEmpty() ? QStringLiteral("<missing ID>") : id);
      return false;
    }
    seen_ids.insert(id);
    const QJsonObject transform = edit.value(QStringLiteral("new_transform")).toObject();
    const QJsonObject old_transform = edit.value(QStringLiteral("old_transform")).toObject();
    const QJsonObject pose = transform.value(QStringLiteral("pose")).toObject();
    const QJsonObject xyz = pose.value(QStringLiteral("xyz")).toObject();
    const QJsonObject rpy = pose.value(QStringLiteral("rpy")).toObject();
    const QJsonObject scale = transform.value(QStringLiteral("scale")).toObject();
    const QJsonObject old_scale = old_transform.value(QStringLiteral("scale")).toObject();
    const auto finite = [](const QJsonObject & object, const char * key) {
      return object.value(QString::fromUtf8(key)).isDouble() && std::isfinite(object.value(QString::fromUtf8(key)).toDouble());
    };
    if (!finite(xyz, "x") || !finite(xyz, "y") || !finite(xyz, "z") ||
        !finite(rpy, "x") || !finite(rpy, "y") || !finite(rpy, "z") ||
        !finite(scale, "x") || !finite(scale, "y") || !finite(scale, "z") ||
        !finite(old_scale, "x") || !finite(old_scale, "y") || !finite(old_scale, "z")) {
      if (error) *error = QStringLiteral("Browser transform for '%1' is incomplete or non-finite. No file was written; edits remain unsaved.").arg(id);
      return false;
    }
    for (const char * axis : {"x", "y", "z"}) {
      if (std::abs(scale.value(QString::fromUtf8(axis)).toDouble() -
          old_scale.value(QString::fromUtf8(axis)).toDouble()) > 1e-12) {
        if (error) *error = QStringLiteral(
          "Browser scale edit for '%1' is unsupported by the authored layout transaction. No file was written.").arg(id);
        return false;
      }
    }
    auto * canvas = find_canvas_item_by_stable_id(id);
    workcell_builder::WebEditFacts facts;
    facts.item_id = id;
    facts.canvas_found = canvas != nullptr;
    facts.locked = canvas && canvas->data(RoleLocked).toBool();
    facts.source_layer = canvas ? canvas->data(RoleSourceLayer).toString() : QString();
    facts.deleted = deleted_layout_item_ids_.contains(id);
    facts.known_derived = !canvas && task_destination_ids.contains(id);
    QString disposition_reason;
    switch (workcell_builder::classify_web_edit(facts, &disposition_reason)) {
      case workcell_builder::WebEditDisposition::SkipDerived:
        // Positively identified: the scene's task destination zone follows its
        // target bin in the Product View and has no authored layout entry.
        append_studio_log(disposition_reason);
        continue;
      case workcell_builder::WebEditDisposition::Reject:
        if (error) *error = disposition_reason;
        return false;
      case workcell_builder::WebEditDisposition::Persist:
        break;
    }
    validated.push_back({canvas, id, xyz.value("x").toDouble(), xyz.value("y").toDouble(),
      xyz.value("z").toDouble(), rpy.value("x").toDouble(), rpy.value("y").toDouble(),
      rpy.value("z").toDouble()});
  }
  // Validation is deliberately complete before mutating the native session.
  // Browser position/rotation wins; native state supplies metadata and structure.
  for (const auto & update : validated) {
    workcell_builder::set_authored_canvas_position(update.canvas, QPointF(update.x * 100.0, update.y * 100.0));
    update.canvas->setData(RolePoseZ, update.z);
    update.canvas->setData(RoleRoll, update.roll);
    update.canvas->setData(RolePitch, update.pitch);
    update.canvas->setData(RoleYaw, update.yaw);
    // A dirty session is written back onto the canvas before serializing. The
    // browser pose already includes any Inspector edit pushed to it, so it is
    // the newer pending value: a gizmo edit after Inspector Apply must survive.
    for (auto & session_item : editable_layout_session_items_) {
      if (session_item.id != update.id) continue;
      session_item.x = update.x; session_item.y = update.y; session_item.z = update.z;
      session_item.roll = update.roll; session_item.pitch = update.pitch; session_item.yaw = update.yaw;
    }
  }
  // Keep the pending Inspector snapshot intact while saving dirty edits.
  if (!layout_dirty_) capture_active_editable_layout_session();
  append_studio_log(QStringLiteral(
    "Save Layout composition validated: %1 Web3D transform edit(s) merged with native authored metadata/structure by stable canonical ID.")
    .arg(validated.size()));
  return true;
}

bool MainWindow::save_native_layout_changes(const QJsonObject & web_patch, QString * error){
  if (!web_patch.isEmpty() && !apply_web_transforms_to_editable_layout_session(web_patch, error)) return false;
  const auto scene_name_for_save_log = [this]() {
    if (selected_scene_state_.valid && !selected_scene_state_.name.trimmed().isEmpty()) {
      return selected_scene_state_.name.trimmed();
    }
    if (selected_scene_index_ >= 0 && selected_scene_index_ < static_cast<int>(scene_browser_result_.scenes.size())) {
      return QString::fromStdString(scene_browser_result_.scenes[static_cast<size_t>(selected_scene_index_)].scene_name);
    }
    return QStringLiteral("<none>");
  };
  const auto scene_root_for_save_log = [this]() {
    const QString pinned = selected_scene_path().trimmed();
    return pinned.isEmpty() ? QStringLiteral("<none>") : pinned;
  };
  const auto emit_save_layout_failure = [this, scene_name_for_save_log, scene_root_for_save_log](
      const QString & blocker, const QString & target_path = QString(), const QString & exact_message = QString()) {
    if (!exact_message.trimmed().isEmpty()) {
      append_studio_log(exact_message);
    }
    const QString target = target_path.trimmed().isEmpty() ? QStringLiteral("<unknown>") : target_path.trimmed();
    const QString detail = QString("Save Layout failed: action=Save Layout scene=%1 selected_scene_index=%2 scene_root=%3 target=%4 blocker=%5; no file was written.")
      .arg(scene_name_for_save_log())
      .arg(selected_scene_index_)
      .arg(scene_root_for_save_log())
      .arg(target)
      .arg(blocker);
    append_studio_log(detail);
    show_workflow_feedback("error", QStringLiteral("Save failed: %1 No file was written; your edits are still in the editor.").arg(blocker));
  };

  QString selected_preview_id;
  if (!current_selected_scene_item_id_.trimmed().isEmpty()) {
    selected_preview_id = current_selected_scene_item_id_.trimmed();
  } else if (scene_hierarchy_tree_ && scene_hierarchy_tree_->currentItem()) {
    selected_preview_id = scene_hierarchy_tree_->currentItem()->data(0, TreeRoleId).toString();
  } else if (digital_twin_scene_ && !digital_twin_scene_->selectedItems().isEmpty()) {
    selected_preview_id = digital_twin_scene_->selectedItems().front()->data(RoleId).toString();
  }
  const QString stable_selected_id_before_refresh = selected_preview_id.trimmed();
  if (!digital_twin_scene_) {
    emit_save_layout_failure(
      QStringLiteral("Scene3D canvas is not initialized"),
      QString(),
      QStringLiteral("Save Layout failed: Scene3D canvas is not initialized; no file was written."));
    statusBar()->showMessage("Save Layout blocked: Scene3D canvas is not initialized; no file was written.", 6000);
    return false;
  }
  if (selected_scene_index_ < 0 || selected_scene_index_ >= static_cast<int>(scene_browser_result_.scenes.size())) {
    emit_save_layout_failure(
      QStringLiteral("no scene selected"),
      QString(),
      QStringLiteral("Save Layout failed: no scene selected; no file was written."));
    statusBar()->showMessage("Save Layout blocked: no scene selected; no file was written.", 6000);
    return false;
  }
  const fs::path scene_dir = fs::path(selected_scene_path().toStdString());
  const fs::path layout_path = scene_dir / "layout" / "workcell_studio_layout.yaml";
  if (layout_path.empty()) {
    const QString reason = QString("canonical layout path could not be computed for scene_root=%1 selected_scene_index=%2")
      .arg(scene_root_for_save_log())
      .arg(selected_scene_index_);
    emit_save_layout_failure(reason);
    statusBar()->showMessage("Save Layout blocked: canonical layout path could not be computed; no file was written.", 6000);
    return false;
  }
  const std::array<const char *, 1> required_dirs = {"layout"};
  for (const char * dir_name : required_dirs) {
    boost::system::error_code mk_ec;
    fs::create_directories(scene_dir / dir_name, mk_ec);
    if (mk_ec) {
      emit_save_layout_failure(
        QString("cannot create required directory '%1' (%2)")
          .arg(dir_name, QString::fromStdString(mk_ec.message())),
        QString::fromStdString((scene_dir / dir_name).string()));
      QMessageBox::warning(this, "Save Layout", QString("Save Layout blocked: cannot create %1/. No file was written.").arg(dir_name));
      return false;
    }
  }
  const std::string scene_name = (selected_scene_index_ >= 0 && selected_scene_index_ < static_cast<int>(scene_browser_result_.scenes.size())) ?
    scene_browser_result_.scenes[static_cast<size_t>(selected_scene_index_)].scene_name : "unknown";
  YAML::Node root;
  fs::path imported_layout_path;
  bool existing_layout_file = false;
  bool malformed_existing = false;
  if (fs::exists(layout_path)) {
    existing_layout_file = true;
    try {
      root = YAML::LoadFile(layout_path.string());
    } catch (const YAML::Exception &) {
      malformed_existing = true;
    } catch (const std::exception &) {
      malformed_existing = true;
    }
  } else {
    std::vector<fs::path> import_candidates;
    const fs::path manifest_layout = manifest_declared_layout_path(scene_dir);
    if (!manifest_layout.empty() && manifest_layout != layout_path) import_candidates.push_back(manifest_layout);
    import_candidates.push_back(scene_dir / "environment_layout.yaml");

    for (const auto & candidate : import_candidates) {
      if (candidate.empty() || candidate == layout_path || !fs::exists(candidate)) continue;
      try {
        root = normalize_imported_layout_to_canonical_items(YAML::LoadFile(candidate.string()), scene_name);
        imported_layout_path = candidate;
        break;
      } catch (const YAML::Exception & exc) {
        append_studio_log(QString("Save Layout: cannot import malformed legacy layout from %1 (%2).")
          .arg(QString::fromStdString(candidate.string()), QString::fromStdString(exc.what())));
      } catch (const std::exception & exc) {
        append_studio_log(QString("Save Layout: cannot import legacy layout from %1 (%2).")
          .arg(QString::fromStdString(candidate.string()), QString::fromStdString(exc.what())));
      }
    }
  }
  if (malformed_existing) {
    const QString stamp = QDateTime::currentDateTimeUtc().toString("yyyyMMdd_HHmmss_zzz");
    const fs::path backup = layout_path.parent_path() / (layout_path.filename().string() + ".malformed_backup_" + stamp.toStdString());
    boost::system::error_code ec;
    fs::copy_file(layout_path, backup, fs::copy_option::overwrite_if_exists, ec);
    if (ec) {
      emit_save_layout_failure(
        QString("malformed layout YAML at %1 and backup failed (%2)")
          .arg(QString::fromStdString(layout_path.string()), QString::fromStdString(ec.message())),
        QString::fromStdString(layout_path.string()));
      QMessageBox::warning(this, "Save Layout", "Malformed layout YAML backup failed. Not overwriting. No file was written.");
      return false;
    }
    append_studio_log(QString("Malformed layout YAML backed up to %1").arg(QString::fromStdString(backup.string())));
    root = YAML::Node();
  }
  if (!root || !root.IsMap()) {
    root = YAML::Node(YAML::NodeType::Map);
    root["items"] = YAML::Node(YAML::NodeType::Sequence);
  } else {
    root = normalize_imported_layout_to_canonical_items(root, scene_name);
  }
  root["schema_version"] = "workcell_studio_layout/v1";
  root["schema"] = "workcell_studio_layout/v1";
  if (!root["scene_name"] || !root["scene_name"].IsScalar()) root["scene_name"] = scene_name;
  root["scene_path"] = ".";

  const QString backup_stamp = QDateTime::currentDateTimeUtc().toString("yyyyMMdd_HHmmss_zzz");
  const fs::path layout_backup = layout_path.parent_path() /
    (layout_path.filename().string() + "." + backup_stamp.toStdString() + ".bak.yaml");
  if (existing_layout_file) {
    boost::system::error_code ec;
    fs::copy_file(layout_path, layout_backup, fs::copy_option::overwrite_if_exists, ec);
    if (!ec) {
      append_studio_log(QString("Backup before write created: %1").arg(QString::fromStdString(layout_backup.string())));
    } else {
      const QString backup_error = QStringLiteral(
        "Backup before write failed for '%1' (%2). No file was written; the authored session remains dirty.")
        .arg(QString::fromStdString(layout_path.string()), QString::fromStdString(ec.message()));
      if (error) *error = backup_error;
      emit_save_layout_failure(backup_error, QString::fromStdString(layout_path.string()));
      return false;
    }
  }
  std::vector<QGraphicsItem *> editable_canvas_items;
  // Reconcile the pending native authoring-session snapshot back onto the
  // serializer's canvas projection before collecting inputs. Product View may
  // have refreshed a derived visual to its pre-edit pose after Inspector Apply;
  // the dirty session remains the authoritative pending edit.
  if (layout_dirty_) {
    for (const auto & session_item : editable_layout_session_items_) {
      if (auto * canvas = find_canvas_item_by_stable_id(session_item.id)) {
        append_studio_log(QString("Save reconciliation: id=%1 session_xyz=[%2,%3,%4] canvas_before=[%5,%6,%7]")
          .arg(session_item.id).arg(session_item.x,0,'g',17).arg(session_item.y,0,'g',17).arg(session_item.z,0,'g',17)
          .arg(canvas->pos().x()/100.0,0,'g',17).arg(canvas->pos().y()/100.0,0,'g',17).arg(canvas->data(RolePoseZ).toDouble(),0,'g',17));
        workcell_builder::set_authored_canvas_position(canvas, QPointF(session_item.x * 100.0, session_item.y * 100.0));
        canvas->setData(RolePoseZ, session_item.z);
        canvas->setData(RoleRoll, session_item.roll);
        canvas->setData(RolePitch, session_item.pitch);
        canvas->setData(RoleYaw, session_item.yaw);
      }
    }
  }
  for (auto * gi : digital_twin_scene_->items()) {
    const QString item_id = gi->data(RoleId).toString().trimmed();
    if (item_id.isEmpty()) continue;
    if (gi->data(RoleLocked).toBool()) continue;
    const QString source_layer = gi->data(RoleSourceLayer).toString().trimmed();
    if (source_layer != QStringLiteral("editable_layout")) continue;
    const std::string item_id_std = item_id.toStdString();
    if (!workcell_builder::workcell_studio_is_valid_id(item_id_std)) {
      QMessageBox::warning(this, "Save Layout", QString("Invalid ID for YAML/package compatibility: %1. No file was written.").arg(item_id));
      emit_save_layout_failure(
        QString("invalid id '%1' for YAML/package compatibility").arg(item_id),
        QString::fromStdString(layout_path.string()));
      return false;
    }
    editable_canvas_items.push_back(gi);
  }

  fs::path effective_layout_path = layout_path;

  if (effective_layout_path != layout_path && fs::exists(effective_layout_path)) {
    const fs::path effective_layout_backup = effective_layout_path.parent_path() /
      (effective_layout_path.filename().string() + "." + backup_stamp.toStdString() + ".bak.yaml");
    boost::system::error_code ec;
    fs::copy_file(effective_layout_path, effective_layout_backup, fs::copy_option::overwrite_if_exists, ec);
    if (!ec) {
      append_studio_log(QString("Backup before write created: %1").arg(QString::fromStdString(effective_layout_backup.string())));
    } else {
      append_studio_log(QString("Warning: backup before write failed (%1). Continuing save without backup.")
        .arg(QString::fromStdString(ec.message())));
    }
  }

  auto existing_items_by_id = [](const YAML::Node & sequence) {
    YAML::Node out(YAML::NodeType::Map);
    if (!sequence || !sequence.IsSequence()) return out;
    for (std::size_t i = 0; i < sequence.size(); ++i) {
      const YAML::Node existing = sequence[i];
      if (!existing || !existing.IsMap()) continue;
      const std::string existing_id = workcell_builder::yaml_map_value_or_empty(existing, "id");
      if (!existing_id.empty()) out[existing_id] = existing;
    }
    return out;
  };

  const bool saving_workcell_layout = effective_layout_path.filename().string() == "workcell_studio_layout.yaml" ||
    workcell_builder::yaml_map_value_or_empty(root, "schema_version") == "workcell_studio_layout/v1" ||
    (root["items"] && root["items"].IsSequence() && effective_layout_path.parent_path().filename().string() == "layout");
  const bool saving_placed_assets_layout = !saving_workcell_layout && root["placed_assets"] && root["placed_assets"].IsSequence();

  YAML::Node updated_placed(YAML::NodeType::Sequence);
  std::size_t editable_saved_count = 0;
  if (saving_workcell_layout) {
    QMap<QString, QGraphicsItem *> editable_by_id;
    for (auto * gi : editable_canvas_items) editable_by_id.insert(gi->data(RoleId).toString().trimmed(), gi);
    QSet<QString> saved_ids;
    YAML::Node existing_by_id = existing_items_by_id(root["items"]);
    YAML::Node existing_items = root["items"];
    if (existing_items && existing_items.IsSequence()) {
      for (std::size_t i = 0; i < existing_items.size(); ++i) {
        YAML::Node existing_item = existing_items[i];
        if (!existing_item || !existing_item.IsMap()) {
          updated_placed.push_back(YAML::Clone(existing_item));
          continue;
        }
        const QString id = QString::fromStdString(workcell_builder::yaml_map_value_or_empty(existing_item, "id")).trimmed();
        if (!id.isEmpty() && deleted_layout_item_ids_.contains(id)) {
          continue;
        }
        if (!id.isEmpty() && editable_by_id.contains(id)) {
          YAML::Node item = serialized_editable_canvas_item(editable_by_id.value(id), existing_item);
          if (!item["source"]) item["source"] = "layout/workcell_studio_layout.yaml";
          updated_placed.push_back(item);
          saved_ids.insert(id);
          ++editable_saved_count;
          append_studio_log(QString("Inspector transform saved: scene=%1 id=%2 path=%3")
            .arg(QString::fromStdString(scene_name), id, QString::fromStdString(effective_layout_path.string())));
        } else {
          updated_placed.push_back(YAML::Clone(existing_item));
        }
      }
    }
    for (auto * gi : editable_canvas_items) {
      const QString id = gi->data(RoleId).toString().trimmed();
      if (saved_ids.contains(id)) continue;
      YAML::Node item = serialized_editable_canvas_item(gi, existing_by_id[id.toStdString()]);
      if (!item["source"]) item["source"] = "layout/workcell_studio_layout.yaml";
      updated_placed.push_back(item);
      saved_ids.insert(id);
      ++editable_saved_count;
      append_studio_log(QString("Inspector transform saved: scene=%1 id=%2 path=%3")
        .arg(QString::fromStdString(scene_name), id, QString::fromStdString(effective_layout_path.string())));
    }
    root["items"] = updated_placed;
    root["schema_version"] = "workcell_studio_layout/v1";
    root["schema"] = "workcell_studio_layout/v1";
  } else if (saving_placed_assets_layout) {
    const char * item_key = "placed_assets";
    YAML::Node existing_by_id = existing_items_by_id(root[item_key]);
    if (!imported_layout_path.empty() && editable_canvas_items.empty() && root[item_key] && root[item_key].IsSequence()) {
      updated_placed = YAML::Clone(root[item_key]);
    }
    for (auto * gi : editable_canvas_items) {
      const std::string item_id = gi->data(RoleId).toString().toStdString();
      YAML::Node item = serialized_editable_canvas_item(gi, existing_by_id[item_id]);
      updated_placed.push_back(item);
      ++editable_saved_count;
      append_studio_log(QString("Inspector transform saved: scene=%1 id=%2 path=%3")
        .arg(QString::fromStdString(scene_name), gi->data(RoleId).toString(), QString::fromStdString(effective_layout_path.string())));
    }
    root[item_key] = updated_placed;
  } else {
    QMap<QString, QGraphicsItem *> editable_by_id;
    for (auto * gi : editable_canvas_items) editable_by_id.insert(gi->data(RoleId).toString().trimmed(), gi);
    QSet<QString> saved_ids;
    const QStringList legacy_sequence_keys = {"items", "assets", "objects", "zones", "targets"};
    for (const QString & key_q : legacy_sequence_keys) {
      const std::string key = key_q.toStdString();
      YAML::Node seq = root[key];
      if (!seq || !seq.IsSequence()) continue;
      for (std::size_t i = 0; i < seq.size(); ++i) {
        YAML::Node node = seq[i];
        if (!node || !node.IsMap()) continue;
        const QString id = QString::fromStdString(workcell_builder::yaml_map_value_or_empty(node, "id")).trimmed();
        if (id.isEmpty() || !editable_by_id.contains(id)) continue;
        seq[i] = serialized_editable_canvas_item(editable_by_id.value(id), node);
        saved_ids.insert(id);
        updated_placed.push_back(seq[i]);
        ++editable_saved_count;
        append_studio_log(QString("Inspector transform saved: scene=%1 id=%2 path=%3")
          .arg(QString::fromStdString(scene_name), id, QString::fromStdString(effective_layout_path.string())));
      }
    }
    YAML::Node camera = root["camera"];
    if (camera && camera.IsMap()) {
      const QString id = QString::fromStdString(workcell_builder::yaml_map_value_or_empty(camera, "id")).trimmed();
      if (!id.isEmpty() && editable_by_id.contains(id)) {
        root["camera"] = serialized_editable_canvas_item(editable_by_id.value(id), camera);
        saved_ids.insert(id);
        updated_placed.push_back(root["camera"]);
        ++editable_saved_count;
        append_studio_log(QString("Inspector transform saved: scene=%1 id=%2 path=%3")
          .arg(QString::fromStdString(scene_name), id, QString::fromStdString(effective_layout_path.string())));
      }
    }
    YAML::Node placed_assets = ensure_sequence_of_maps(root, "placed_assets");
    YAML::Node existing_by_id = existing_items_by_id(placed_assets);
    for (auto * gi : editable_canvas_items) {
      const QString id = gi->data(RoleId).toString().trimmed();
      if (saved_ids.contains(id)) continue;
      YAML::Node item = serialized_editable_canvas_item(gi, existing_by_id[id.toStdString()]);
      placed_assets.push_back(item);
      updated_placed.push_back(item);
      ++editable_saved_count;
      append_studio_log(QString("Inspector transform saved: scene=%1 id=%2 path=%3")
        .arg(QString::fromStdString(scene_name), id, QString::fromStdString(effective_layout_path.string())));
    }
  }

  YAML::Emitter emitter;
  emitter << root;
  try {
    const YAML::Node staged = YAML::Load(std::string(emitter.c_str(), emitter.size()));
    if (!staged || !staged.IsMap()) throw std::runtime_error("serialized root is not a map");
  } catch (const std::exception & exc) {
    if (error) *error = QStringLiteral(
      "Serialized authored transaction failed YAML validation before write: %1. No file was written.")
      .arg(QString::fromStdString(exc.what()));
    emit_save_layout_failure(error ? *error : QStringLiteral("staged YAML validation failed"),
      QString::fromStdString(effective_layout_path.string()));
    return false;
  }
  // Write through the formatting-preserving authored writer (scripts/authored_yaml.py):
  // the document is the yaml-cpp result, but unchanged sections keep their text and
  // numbers keep their shortest exact spelling (no explicit !!str tags, no 17-digit
  // rewrites of untouched values). The direct yaml-cpp write remains the fallback.
  const QString layout_target = QString::fromStdString(effective_layout_path.string());
  bool preserved_write = false;
  {
    const QString repo_root = resolve_workcell_studio_repo_root(fs::path(selected_scene_state_.path.toStdString()));
    const QString writer = repo_root.isEmpty() ? QString() : QDir(repo_root).filePath("scripts/authored_yaml.py");
    QTemporaryFile staged(QFileInfo(layout_target).dir().filePath(QStringLiteral(".layout_staged_XXXXXX.yaml")));
    if (!writer.isEmpty() && QFileInfo::exists(writer) && staged.open() &&
        staged.write(QByteArray(emitter.c_str(), static_cast<int>(emitter.size()))) >= 0 && staged.flush()) {
      staged.close();
      QProcess process;
      process.start(QStringLiteral("python3"), {writer, QStringLiteral("rewrite"), layout_target, staged.fileName()});
      preserved_write = process.waitForFinished(20000) && process.exitStatus() == QProcess::NormalExit && process.exitCode() == 0;
      if (!preserved_write) {
        append_studio_log(QStringLiteral("Save Layout: formatting-preserving write unavailable (%1); writing the yaml-cpp document directly.")
          .arg(QString::fromUtf8(process.readAllStandardError()).trimmed().right(300)));
      }
    }
  }
  QSaveFile out(QString::fromStdString(effective_layout_path.string()));
  if (!preserved_write && (!out.open(QIODevice::WriteOnly) ||
      out.write(QByteArray(emitter.c_str(), static_cast<int>(emitter.size()))) < 0 || !out.commit())) {
    if (error) *error = QStringLiteral("Could not atomically write canonical editable layout '%1': %2. Dirty state was retained.")
      .arg(QString::fromStdString(effective_layout_path.string()), out.errorString());
    emit_save_layout_failure(error ? *error : QStringLiteral("atomic layout write failed"),
      QString::fromStdString(effective_layout_path.string()));
    return false;
  }
  if (saving_workcell_layout) {
    try {
      const YAML::Node persisted_root = YAML::LoadFile(effective_layout_path.string());
      const YAML::Node persisted_items = persisted_root["items"];
      if (!persisted_items || !persisted_items.IsSequence()) {
        throw std::runtime_error("persisted items sequence is missing");
      }
      QMap<QString, YAML::Node> persisted_by_id;
      for (std::size_t index = 0; index < persisted_items.size(); ++index) {
        const YAML::Node item = persisted_items[index];
        if (!item || !item.IsMap()) continue;
        const QString id = QString::fromStdString(workcell_builder::yaml_map_value_or_empty(item, "id")).trimmed();
        if (!id.isEmpty()) persisted_by_id.insert(id, item);
      }
      const auto close_enough = [](double left, double right) {
        return std::isfinite(left) && std::isfinite(right) && std::abs(left - right) <= 1e-10;
      };
      const auto pose_value = [](const YAML::Node & pose, const char * sequence_key,
          const char * scalar_key, std::size_t index, double * output) {
        if (!pose || !pose.IsMap() || !output) return false;
        const YAML::Node sequence = pose[sequence_key];
        try {
          if (sequence && sequence.IsSequence() && sequence.size() == 3) {
            *output = sequence[index].as<double>();
            return std::isfinite(*output);
          }
          const YAML::Node scalar = pose[scalar_key];
          if (scalar && scalar.IsScalar()) {
            *output = scalar.as<double>();
            return std::isfinite(*output);
          }
        } catch (const std::exception &) {
          return false;
        }
        return false;
      };
      for (auto * canvas : editable_canvas_items) {
        const QString id = canvas->data(RoleId).toString().trimmed();
        if (!persisted_by_id.contains(id)) {
          throw std::runtime_error(QStringLiteral("stable ID missing after write: %1").arg(id).toStdString());
        }
        const YAML::Node item = persisted_by_id.value(id);
        const YAML::Node pose = item["pose"];
        double x = 0.0, y = 0.0, z = 0.0, roll = 0.0, pitch = 0.0, yaw = 0.0;
        if (!pose_value(pose, "xyz", "x", 0, &x) ||
            !pose_value(pose, "xyz", "y", 1, &y) ||
            !pose_value(pose, "xyz", "z", 2, &z) ||
            !pose_value(pose, "rpy", "roll", 0, &roll) ||
            !pose_value(pose, "rpy", "pitch", 1, &pitch) ||
            !pose_value(pose, "rpy", "yaw", 2, &yaw) ||
            !close_enough(x, canvas->pos().x() / 100.0) ||
            !close_enough(y, canvas->pos().y() / 100.0) ||
            !close_enough(z, canvas->data(RolePoseZ).toDouble()) ||
            !close_enough(roll, canvas->data(RoleRoll).toDouble()) ||
            !close_enough(pitch, canvas->data(RolePitch).toDouble()) ||
            !close_enough(yaw, canvas->data(RoleYaw).toDouble())) {
          throw std::runtime_error(QStringLiteral("transform mismatch after write: %1").arg(id).toStdString());
        }
        if (canvas->data(RoleMetadataExplicitlyEdited).toBool()) {
          const QString persisted_name = QString::fromStdString(
            workcell_builder::yaml_map_value_or_empty(item, "display_name")).trimmed();
          const QString persisted_role = QString::fromStdString(
            workcell_builder::yaml_map_value_or_empty(item, "role")).trimmed();
          const QString persisted_category = QString::fromStdString(
            workcell_builder::yaml_map_value_or_empty(item, "category")).trimmed();
          if (persisted_name != canvas->data(RoleDisplayName).toString().trimmed() ||
              workcell_builder::semantic_role_actually_changed(canvas->data(RoleRole).toString(), persisted_role,
                canonical_scene_hierarchy_role(persisted_role, persisted_category, QString()))) {
            throw std::runtime_error(QStringLiteral("metadata mismatch after write: %1").arg(id).toStdString());
          }
        }
      }
      // Verify every dirty session transform against disk truth, including
      // semantic records whose preview may have been refreshed independently.
      if (layout_dirty_) {
        for (const auto & expected : editable_layout_session_items_) {
          if (deleted_layout_item_ids_.contains(expected.id)) continue;
          if (!persisted_by_id.contains(expected.id))
            throw std::runtime_error(QString("Persistence verification failed for %1: authored ID missing").arg(expected.id).toStdString());
          const YAML::Node pose = persisted_by_id.value(expected.id)["pose"];
          double x=0,y=0,z=0,roll=0,pitch=0,yaw=0;
          if (!pose_value(pose,"xyz","x",0,&x) || !pose_value(pose,"xyz","y",1,&y) || !pose_value(pose,"xyz","z",2,&z) ||
              !pose_value(pose,"rpy","roll",0,&roll) || !pose_value(pose,"rpy","pitch",1,&pitch) || !pose_value(pose,"rpy","yaw",2,&yaw) ||
              !close_enough(x,expected.x) || !close_enough(y,expected.y) || !close_enough(z,expected.z) ||
              !close_enough(roll,expected.roll) || !close_enough(pitch,expected.pitch) || !close_enough(yaw,expected.yaw)) {
            throw std::runtime_error((QString("Persistence verification failed for %1: expected xyz=[%2,%3,%4] actual xyz=[%5,%6,%7]")
              .arg(expected.id).arg(expected.x,0,'g',17).arg(expected.y,0,'g',17).arg(expected.z,0,'g',17)
              .arg(x,0,'g',17).arg(y,0,'g',17).arg(z,0,'g',17)).toStdString());
          }
        }
      }
      append_studio_log(QStringLiteral(
        "Save Layout persistence verified: %1 editable item(s), stable IDs, metadata, and transforms match the atomic YAML write.")
        .arg(editable_canvas_items.size()));
    } catch (const std::exception & exc) {
      if (error) *error = QStringLiteral(
        "Authored YAML was written atomically but persistence verification failed: %1. Dirty state was retained; backup: %2")
        .arg(QString::fromStdString(exc.what()), QString::fromStdString(layout_backup.string()));
      emit_save_layout_failure(error ? *error : QStringLiteral("post-write persistence verification failed"),
        QString::fromStdString(effective_layout_path.string()));
      return false;
    }
  }
  if (saving_workcell_layout) {
    append_studio_log(QStringLiteral(
      "Save Layout persisted authored YAML only; generated collision/scene artifacts remain stale until explicit Generate/Validate."));
  }
  if (!save_environment_task_editor(error) || !save_authored_environment_from_layout(error)) {
    // The authored YAML was already written atomically above. A rejected
    // projection must not leave it ahead of environment.yaml (every later Save
    // of the scene would then fail the same way): roll it back to the
    // pre-save backup so nothing on disk changed and the edits stay in the editor.
    QString rollback_note = QStringLiteral(" Nothing was written; your edits are still in the editor.");
    if (existing_layout_file) {
      boost::system::error_code rollback_ec;
      fs::copy_file(layout_backup, effective_layout_path, fs::copy_option::overwrite_if_exists, rollback_ec);
      if (rollback_ec) {
        rollback_note = QStringLiteral(" The authored layout file could NOT be restored (%1); restore it from %2 before saving again.")
          .arg(QString::fromStdString(rollback_ec.message()), QString::fromStdString(layout_backup.string()));
      } else {
        append_studio_log(QStringLiteral("Save Layout rolled back %1 to %2 after the projection failure.")
          .arg(QString::fromStdString(effective_layout_path.string()), QString::fromStdString(layout_backup.string())));
        rollback_note = QStringLiteral(" The authored layout file was restored from its backup, so nothing on disk changed; your edits are still in the editor.");
      }
    }
    if (error) *error += rollback_note;
    emit_save_layout_failure(error ? *error : QStringLiteral("Authored environment save failed"), QString::fromStdString(effective_layout_path.string()));
    return false;
  }
  // Projection can move target-local destination regions with their physical
  // target. Rebase the retained editor from the committed layout before the
  // next Save; otherwise its old world pose looks like an independent zone
  // edit and is converted into an unintended target-local offset.
  QVector<ScenePreviewWidget::PreviewItem> projected_destinations;
  try {
    const auto committed = YAML::LoadFile(effective_layout_path.string());
    for (const auto & item : committed["items"]) {
      if (!item["target_ref"] || !item["placement_local"]) continue;
      const QString id = QString::fromStdString(item["id"].as<std::string>());
      for (const auto & existing : all_scene_preview_items_) {
        if (existing.id != id) continue;
        auto projected = existing;
        const auto xyz = item["pose"]["xyz"], rpy = item["pose"]["rpy"];
        projected.x = xyz[0].as<double>(); projected.y = xyz[1].as<double>(); projected.z = xyz[2].as<double>();
        projected.roll = rpy[0].as<double>(); projected.pitch = rpy[1].as<double>(); projected.yaw = rpy[2].as<double>();
        projected.sx = item["dimensions"][0].as<double>();
        projected.sy = item["dimensions"][1].as<double>();
        projected.sz = item["dimensions"][2].as<double>();
        projected_destinations.push_back(projected);
        break;
      }
    }
  } catch (const std::exception & exc) {
    const QString message = QStringLiteral("Physical layout was saved, but the committed destination projection could not be read: %1. Reopen the scene before saving again.")
      .arg(QString::fromUtf8(exc.what()));
    if (error) *error = message;
    append_studio_log(message);
    show_workflow_feedback("error", message);
    return false;
  }
  for (const auto & projected : projected_destinations) {
    for (auto & existing : all_scene_preview_items_) {
      if (existing.id == projected.id) { existing = projected; break; }
    }
    if (auto * canvas = find_canvas_item_by_stable_id(projected.id)) {
      workcell_builder::set_authored_canvas_position(canvas, QPointF(projected.x * 100., projected.y * 100.));
      canvas->setData(RolePoseZ, projected.z);
      canvas->setData(RoleRoll, projected.roll); canvas->setData(RolePitch, projected.pitch); canvas->setData(RoleYaw, projected.yaw);
      canvas->setData(RoleWidth, projected.sx); canvas->setData(RoleDepth, projected.sy); canvas->setData(RoleHeight, projected.sz);
    }
    // Web3D already carries/rebases target-local dependents. A bridge command
    // here could overwrite a newer browser edit made during the save request.
    if (scene_preview_widget_ && !scene_preview_widget_->embedded_web_authoring_active()) {
      scene_preview_widget_->set_authoring_item_pose(
        projected.id, projected.x, projected.y, projected.z, projected.roll, projected.pitch, projected.yaw);
    }
  }
  deleted_layout_item_ids_.clear();
  for (auto * canvas : editable_canvas_items) {
    canvas->setData(RoleMetadataExplicitlyEdited, false);
  }
  layout_dirty_ = false;
  schedule_operator_preview_update();
  if (save_layout_button_) {
    save_layout_button_->setProperty("layoutDirty", false);
    setWindowModified(false);
    save_layout_button_->style()->unpolish(save_layout_button_);
    save_layout_button_->style()->polish(save_layout_button_);
  }
  layout_saved_ = true;
  validation_stale_ = true;
  launch_artifacts_ready_ = false;
  if (layout_state_label_) layout_state_label_->setText("Unsaved Layout Edits: none");
  if (editable_saved_count == 0) {
    const QString guidance = "Use Create editable layout from preview or add an item to persist editable objects.";
    append_studio_log(QString("Save Layout: no editable items; saved canonical layout metadata to %1. %2")
      .arg(QString::fromStdString(effective_layout_path.string()), guidance));
    QMessageBox::information(this, "Save Layout",
      QString("Save Layout: no editable items; saved canonical layout metadata to %1.\n%2")
        .arg(QString::fromStdString(effective_layout_path.string()), guidance));
  } else {
    append_studio_log(QString("Saved scene layout metadata to %1").arg(QString::fromStdString(effective_layout_path.string())));
  }
  show_workflow_feedback(editable_saved_count == 0 ? "warning" : "success",
    editable_saved_count == 0
      ? QStringLiteral("Saved layout metadata only: no editable items yet. Add an item or create an editable layout from the preview.")
      : QStringLiteral("Saved %1 editable item(s) to %2. Generated outputs are now stale: run Generate, then Validate.")
          .arg(QString::number(static_cast<int>(editable_saved_count)), QFileInfo(QString::fromStdString(effective_layout_path.string())).fileName()));

  append_studio_log(QString("Save Layout: serialized %1 editable layout item(s) to canonical layout only; no task/generated/plan_preview directories or runtime/ROS artifacts were bootstrapped.")
    .arg(static_cast<int>(editable_saved_count)));
  append_studio_log(QString("Save Layout: live authored session retained without Product View regeneration (selection id='%1').")
    .arg(stable_selected_id_before_refresh.isEmpty() ? "<none>" : stable_selected_id_before_refresh));
  workcell_builder::invalidate_workcell_studio_scene_metadata_snapshot(scene_dir, "save_layout");
  refresh_scene_hierarchy_tree_from_current_items();
  capture_active_editable_layout_session();
  populate_scene_files_tab();
  if (!stable_selected_id_before_refresh.isEmpty()) {
    apply_scene_selection(stable_selected_id_before_refresh, QStringLiteral("unknown"), false, false);
  } else {
    append_studio_log("Save Layout: no selected stable item id to reselect.");
  }
  refresh_scene_browser_ui();
  refresh_scene_workflow_rail();
  refresh_scene_builder_view_chips();
  return true;
}

void MainWindow::create_starter_layout_from_preview()
{
  const QString action_title = QStringLiteral("Create editable layout from preview");
  const QString canonical_layout_path = QStringLiteral("layout/workcell_studio_layout.yaml");
  if (!has_selected_scene()) {
    const QString message = QStringLiteral("Create editable layout from preview blocked: no scene selected. Select a scene before writing %1.")
      .arg(canonical_layout_path);
    append_studio_log(message);
    QMessageBox::information(this, action_title, message);
    return;
  }

  const auto & s = scene_browser_result_.scenes[static_cast<size_t>(selected_scene_index_)];
  const std::vector<fs::path> yaml_candidates = {
    s.scene_dir / "layout" / "workcell_studio_layout.yaml",
    s.scene_dir / "environment_layout.yaml",
    s.scene_dir / "environment.yaml",
    s.scene_dir / "cell_definition.yaml",
    s.scene_dir / "scene_manifest.yaml"
  };
  QStringList malformed_yaml_details;
  for (const auto & candidate : yaml_candidates) {
    if (!fs::exists(candidate)) continue;
    try {
      YAML::LoadFile(candidate.string());
    } catch (const YAML::Exception & exc) {
      malformed_yaml_details.push_back(QStringLiteral("%1 (%2)")
        .arg(QString::fromStdString(candidate.string()), QString::fromStdString(exc.what())));
    } catch (const std::exception & exc) {
      malformed_yaml_details.push_back(QStringLiteral("%1 (%2)")
        .arg(QString::fromStdString(candidate.string()), QString::fromStdString(exc.what())));
    }
  }
  if (!malformed_yaml_details.isEmpty()) {
    const QString message = QStringLiteral("Create editable layout from preview blocked: malformed YAML in preview/candidate scene files for '%1'. Target remains %2. Fix these files before conversion:\n- %3")
      .arg(QString::fromStdString(s.scene_name), canonical_layout_path, malformed_yaml_details.join("\n- "));
    append_studio_log(message);
    QMessageBox::warning(this, action_title, message);
    return;
  }

  workcell_builder::WorkcellStudioCanvasModel preview_model;
  workcell_builder::WorkcellStudioEditableLayoutBootstrapResult bootstrap_result;
  try {
    preview_model = workcell_builder::build_workcell_studio_canvas_model(s.scene_dir, s.scene_name);
    bootstrap_result = workcell_builder::bootstrap_editable_layout_from_scene_sources(
      s.scene_dir, s.scene_name, preview_model);
  } catch (const YAML::Exception & exc) {
    const QString message = QStringLiteral("Create editable layout from preview blocked: malformed YAML while reading preview/candidate scene files for '%1'. Target remains %2. Details: %3")
      .arg(QString::fromStdString(s.scene_name), canonical_layout_path, QString::fromStdString(exc.what()));
    append_studio_log(message);
    QMessageBox::warning(this, action_title, message);
    return;
  } catch (const std::exception & exc) {
    const QString message = QStringLiteral("Create editable layout from preview blocked while reading preview/candidate scene files for '%1'. Target remains %2. Details: %3")
      .arg(QString::fromStdString(s.scene_name), canonical_layout_path, QString::fromStdString(exc.what()));
    append_studio_log(message);
    QMessageBox::warning(this, action_title, message);
    return;
  }

  const auto skipped_preview_items = bootstrap_result.skipped_locked_items +
    bootstrap_result.skipped_static_fallback_items +
    bootstrap_result.skipped_unsafe_or_missing_metadata_items;
  const auto bootstrap_counts_message = [&bootstrap_result, skipped_preview_items, &canonical_layout_path]() {
    const auto count_text = [](std::size_t count) { return QString::fromStdString(std::to_string(count)); };
    QStringList blockers;
    for (const auto & blocker : bootstrap_result.blockers) {
      blockers.push_back(QString::fromStdString(blocker));
    }
    const QString blocker_text = blockers.isEmpty() ? QStringLiteral("none reported") : blockers.join("\n- ");
    return QString("No preview items available to convert. "
                   "Generate Scene Package first, fix the listed blockers, or add layout items manually.\n\n"
                   "target: %1\n"
                   "source used: %2\n"
                   "editable items created: %3\n"
                   "skipped locked/helper/unsupported preview items: %4\n"
                   "skipped locked items: %5\n"
                   "skipped static fallback items: %6\n"
                   "skipped unsafe/missing metadata items: %7\n"
                   "blockers:\n- %8")
      .arg(canonical_layout_path)
      .arg(bootstrap_result.source_used.empty() ? QStringLiteral("<none>") : QString::fromStdString(bootstrap_result.source_used))
      .arg(count_text(bootstrap_result.editable_items_created))
      .arg(count_text(skipped_preview_items))
      .arg(count_text(bootstrap_result.skipped_locked_items))
      .arg(count_text(bootstrap_result.skipped_static_fallback_items))
      .arg(count_text(bootstrap_result.skipped_unsafe_or_missing_metadata_items))
      .arg(blocker_text);
  };
  if (bootstrap_result.editable_items_created == 0) {
    const QString message = bootstrap_counts_message();
    append_studio_log(message);
    const QString status_text = QStringLiteral("No preview items available to convert.");
    append_studio_log(status_text);
    QMessageBox::warning(this, action_title, message);
    return;
  }
  const fs::path layout_dir = bootstrap_result.expected_output_dir;
  const fs::path layout_file = bootstrap_result.expected_output_file;
  boost::system::error_code ec;
  fs::create_directories(layout_dir, ec);
  if (ec) {
    const QString message = QStringLiteral("Create editable layout from preview failed: cannot create layout directory for %1 at %2 (%3).")
      .arg(canonical_layout_path, QString::fromStdString(layout_dir.string()), QString::fromStdString(ec.message()));
    append_studio_log(message);
    QMessageBox::warning(this, action_title, message);
    return;
  }
  if (fs::exists(layout_file)) {
    const auto response = QMessageBox::question(this, QStringLiteral("Overwrite Editable Layout"),
      QStringLiteral("%1 already exists. Overwrite it with editable layout items converted from preview/candidate scene data?")
        .arg(canonical_layout_path));
    if (response != QMessageBox::Yes) {
      append_studio_log(QStringLiteral("Create editable layout from preview cancelled by user. Target: %1 (%2).")
        .arg(canonical_layout_path, QString::fromStdString(layout_file.string())));
      return;
    }
    const QString stamp = QDateTime::currentDateTimeUtc().toString("yyyyMMdd_HHmmss_zzz");
    const fs::path backup = layout_dir / ("workcell_studio_layout." + stamp.toStdString() + ".bak.yaml");
    fs::copy_file(layout_file, backup, fs::copy_option::overwrite_if_exists, ec);
    if (ec) {
      const QString message = QStringLiteral("Create editable layout from preview failed: backup before overwrite failed for %1 at %2 (%3).")
        .arg(canonical_layout_path, QString::fromStdString(layout_file.string()), QString::fromStdString(ec.message()));
      append_studio_log(message);
      QMessageBox::warning(this, action_title, message);
      return;
    }
    append_studio_log(QStringLiteral("Create editable layout from preview: backup created at %1 before writing %2 (%3).")
      .arg(QString::fromStdString(backup.string()), canonical_layout_path, QString::fromStdString(layout_file.string())));
  }
  const YAML::Node layout = bootstrap_result.layout;
  std::ofstream out(layout_file.string());
  if (!out.good()) {
    const QString message = QStringLiteral("Create editable layout from preview failed: unable to open %1 for write at %2.")
      .arg(canonical_layout_path, QString::fromStdString(layout_file.string()));
    append_studio_log(message);
    QMessageBox::warning(this, action_title, message);
    return;
  }
  out << layout;
  out.close();
  if (!out.good()) {
    const QString message = QStringLiteral("Create editable layout from preview failed: write error while saving %1 at %2.")
      .arg(canonical_layout_path, QString::fromStdString(layout_file.string()));
    append_studio_log(message);
    QMessageBox::warning(this, action_title, message);
    return;
  }

  const int generated_count = static_cast<int>(bootstrap_result.editable_items_created);
  append_studio_log(QStringLiteral("Create editable layout from preview detail: source=%1 target=%2 absolute_target=%3 editable=%4 skipped_locked_helper_unsupported=%5 skipped_locked=%6 skipped_static_fallback=%7 skipped_unsafe_metadata=%8")
    .arg(QString::fromStdString(bootstrap_result.source_used))
    .arg(canonical_layout_path)
    .arg(QString::fromStdString(layout_file.string()))
    .arg(generated_count)
    .arg(static_cast<int>(skipped_preview_items))
    .arg(static_cast<int>(bootstrap_result.skipped_locked_items))
    .arg(static_cast<int>(bootstrap_result.skipped_static_fallback_items))
    .arg(static_cast<int>(bootstrap_result.skipped_unsafe_or_missing_metadata_items)));
  if (skipped_preview_items > 0) {
    append_studio_log(QStringLiteral("Skipped %1 locked/helper/unsupported preview items.")
      .arg(static_cast<int>(skipped_preview_items)));
  }
  append_studio_log(QStringLiteral("Create editable layout from preview: wrote editable layout to canonical target %1 (%2), then refreshes Scene3D/2D/hierarchy/inspector. Subsequent move/edit operations remain dirty until Save Layout serializes %1 again.")
    .arg(canonical_layout_path, QString::fromStdString(layout_file.string())));
  mark_layout_dirty("Created editable layout from preview");
  append_studio_log(QStringLiteral("Create editable layout from preview: marked layout dirty after preview conversion so Save Layout can re-serialize %1.")
    .arg(canonical_layout_path));
  append_studio_log(QStringLiteral("Created %1 editable layout items from preview.").arg(generated_count));
  refresh_scene_builder_left_explorer();
  refresh_scene_browser_ui();
  refresh_scene_builder_selected_scene_ui();
  refresh_canvas_generated_parity_ui();
  refresh_scene_workflow_rail();
}

void MainWindow::revert_layout_changes()
{
  refresh_environment_task_editor();
  rebuild_digital_twin_canvas();
  layout_dirty_ = false;
  schedule_operator_preview_update();
  if (save_layout_button_) {
    save_layout_button_->setProperty("layoutDirty", false);
    setWindowModified(false);
    save_layout_button_->style()->unpolish(save_layout_button_);
    save_layout_button_->style()->polish(save_layout_button_);
  }
  validation_stale_ = true;
  launch_artifacts_ready_ = false;
  if (layout_state_label_) layout_state_label_->setText("Unsaved Layout Edits: none");
  append_studio_log("Revert Layout requested");
}

void MainWindow::on_canvas_selection_changed()
{
  if (!digital_twin_scene_ || selection_update_guard_) return;
  if (digital_twin_scene_->selectedItems().isEmpty()) {
    if (current_selected_scene_item_id_.isEmpty()) {
      sync_selected_item_state();
      refresh_selected_scene_item_labels(selected_item_state_);
    }
    return;
  }
  auto * sel = digital_twin_scene_->selectedItems().front();
  const QString selected_id = sel->data(RoleId).toString().trimmed();
  const QString selected_role = sel->data(RoleRole).toString().trimmed();
  apply_scene_selection(selected_id, selected_role, false, false);
}
void MainWindow::on_canvas_item_moved(QGraphicsItem * item, const QPointF &, const QPointF & position, const QString & reason)
{
  if (!item || mounting_update_guard_) return;
  bool mounted_graph = false;
  for (const auto & p : all_scene_preview_items_) mounted_graph = mounted_graph || p.mounting_yaml.contains("parent_object");
  if (mounted_graph) {
    commit_mounting_request({{"id", item->data(RoleId).toString()}, {"world_pose", QJsonObject{
      {"xyz", QJsonArray{position.x()/100., position.y()/100., item->data(RolePoseZ).toDouble()}},
      {"rpy", QJsonArray{item->data(RoleRoll).toDouble(), item->data(RolePitch).toDouble(), item->data(RoleYaw).toDouble()}}}}});
    return;
  }
  select_canvas_item(item); mark_layout_dirty(reason);
}
bool MainWindow::parse_transform_clipboard_text(
  const QString & text, double * x, double * y, double * z, double * r, double * p, double * yaw, QString * error)
{
  return workcell_builder::parse_transform_clipboard_text(text, x, y, z, r, p, yaw, error);
}

void MainWindow::refresh_selection_transform_editor_from_item(QGraphicsItem * item)
{
  if (!item) return;
  SelectedSceneItemState state;
  state.valid = true;
  state.id = item->data(RoleId).toString().trimmed();
  state.display_name = item->data(RoleDisplayName).toString().trimmed();
  state.role = item->data(RoleRole).toString().trimmed();
  state.category = item->data(RoleCategory).toString().trimmed();
  state.type = item->data(RoleType).toString().trimmed();
  state.source_path = item->data(RoleSource).toString().trimmed();
  state.role_or_category = state.role;
  if (state.role_or_category.isEmpty()) state.role_or_category = state.category;
  if (state.role_or_category.isEmpty()) state.role_or_category = state.type;
  state.source_layer = item->data(RoleSourceLayer).toString().trimmed();
  state.editable = !item->data(RoleLocked).toBool();
  state.locked = item->data(RoleLocked).toBool();
  state.linked_to_editable_layout_state = state.editable && state.source_layer.compare(QStringLiteral("editable_layout"), Qt::CaseInsensitive) == 0;
  state.pose_available = true;
  state.pose_x = item->pos().x() / 100.0;
  state.pose_y = item->pos().y() / 100.0;
  state.pose_z = item->data(RolePoseZ).toDouble();
  state.roll = item->data(RoleRoll).toDouble();
  state.pitch = item->data(RolePitch).toDouble();
  state.yaw = item->data(RoleYaw).toDouble();
  state.dim_x = item->data(RoleWidth).toDouble();
  state.dim_y = item->data(RoleDepth).toDouble();
  state.dim_z = item->data(RoleHeight).toDouble();
  selected_item_state_ = state;
  refresh_selection_transform_editor_from_state(state);
}

QString MainWindow::mount_relation_text_for(const QString & id) const
{
  for (const auto & p : all_scene_preview_items_) {
    if (p.id != id) continue;
    const auto relation = workcell_builder::parse_mount_relation(p.mounting_yaml);
    QString parent_name;
    for (const auto & parent : all_scene_preview_items_) if (parent.id == relation.parent_id) parent_name = parent.display_name;
    QStringList children;
    for (const auto & child : all_scene_preview_items_) {
      const auto child_relation = workcell_builder::parse_mount_relation(child.mounting_yaml);
      if (child_relation.mounted && child_relation.parent_id == id) children << child.display_name;
    }
    QString text = workcell_builder::mount_relation_summary(relation, parent_name);
    if (!children.isEmpty()) text += QStringLiteral("\nCarries: ") + children.join(QStringLiteral(", "));
    return text;
  }
  return QString();
}

void MainWindow::refresh_mount_relation_context()
{
  if (!inspector_mount_relation_label_) return;
  const QString text = mount_relation_text_for(current_selected_scene_item_id_.trimmed());
  inspector_mount_relation_label_->setText(text);
  inspector_mount_relation_label_->setVisible(!text.isEmpty());
}

void MainWindow::refresh_selection_transform_editor_from_state(const SelectedSceneItemState & state)
{
  refresh_mount_relation_context();
  if (!state.valid || !state.pose_available) {
    inspector_update_guard_ = true;
    for (auto * sb : {inspector_x_, inspector_y_, inspector_z_, inspector_roll_, inspector_pitch_, inspector_yaw_, inspector_dim_x_, inspector_dim_y_, inspector_dim_z_}) {
      if (sb) { sb->clear(); sb->setEnabled(false); sb->setReadOnly(true); }
    }
    if (inspector_display_name_) { inspector_display_name_->clear(); inspector_display_name_->setPlaceholderText("Display name"); inspector_display_name_->setEnabled(false); }
    if (inspector_semantic_role_) { inspector_semantic_role_->setCurrentIndex(0); inspector_semantic_role_->setEnabled(false); }
    for (auto * le : {inspector_role_, inspector_category_, inspector_type_}) {
      if (le) { le->clear(); le->setEnabled(false); le->setReadOnly(true); }
    }
    if (inspector_apply_button_) inspector_apply_button_->setEnabled(false);
    if (inspector_revert_button_) inspector_revert_button_->setEnabled(false);
    if (inspector_live_update_box_) inspector_live_update_box_->setEnabled(false);
    inspector_update_guard_ = false;
    refresh_robot_base_pose_inspector();
    return;
  }
  const bool locked = state.locked || !state.editable || !state.linked_to_editable_layout_state;
  const bool editable_dimensions = workcell_builder::layout_item_dimensions_editable(
    state.type.toStdString(), state.category.toStdString(),
    (state.visual_uri.isEmpty() ? state.source_path : state.visual_uri).toStdString());
  if (inspector_dimensions_controls_) inspector_dimensions_controls_->setVisible(editable_dimensions);
  if (inspector_dimensions_label_) inspector_dimensions_label_->setVisible(editable_dimensions);
  inspector_update_guard_ = true;
  if (inspector_x_) inspector_x_->setValue(state.pose_x);
  if (inspector_y_) inspector_y_->setValue(state.pose_y);
  if (inspector_z_) inspector_z_->setValue(state.pose_z);
  if (inspector_roll_) inspector_roll_->setValue(qRadiansToDegrees(state.roll));
  if (inspector_pitch_) inspector_pitch_->setValue(qRadiansToDegrees(state.pitch));
  if (inspector_yaw_) inspector_yaw_->setValue(qRadiansToDegrees(state.yaw));
  if (inspector_dim_x_) inspector_dim_x_->setValue(state.dim_x);
  if (inspector_dim_y_) inspector_dim_y_->setValue(state.dim_y);
  if (inspector_dim_z_) inspector_dim_z_->setValue(state.dim_z);
  if (inspector_display_name_) {
    inspector_display_name_->setText(state.display_name);
    inspector_display_name_->setPlaceholderText(state.id.isEmpty() ? QStringLiteral("Display name") : state.id);
  }
  if (inspector_semantic_role_) {
    int role_index = inspector_semantic_role_->findData(state.role);
    if (role_index < 0) {
      inspector_semantic_role_->addItem(QString("Existing role: %1").arg(state.role), state.role);
      role_index = inspector_semantic_role_->count() - 1;
    }
    inspector_semantic_role_->setCurrentIndex(role_index);
  }
  if (inspector_role_) inspector_role_->setText(state.role);
  if (inspector_category_) inspector_category_->setText(state.category);
  if (inspector_type_) inspector_type_->setText(state.type);
  for (auto * sb : {inspector_x_, inspector_y_, inspector_z_, inspector_roll_, inspector_pitch_, inspector_yaw_}) {
    if (sb) { sb->setEnabled(true); sb->setReadOnly(locked); }
  }
  for (auto * sb : {inspector_dim_x_, inspector_dim_y_, inspector_dim_z_}) {
    if (sb) { sb->setEnabled(editable_dimensions); sb->setReadOnly(locked || !editable_dimensions); }
  }
  if (inspector_apply_button_) inspector_apply_button_->setEnabled(!locked);
  if (inspector_revert_button_) inspector_revert_button_->setEnabled(!locked);
  if (inspector_live_update_box_) inspector_live_update_box_->setEnabled(!locked);
  if (inspector_display_name_) { inspector_display_name_->setEnabled(true); inspector_display_name_->setReadOnly(locked); }
  if (inspector_semantic_role_) inspector_semantic_role_->setEnabled(!locked);
  for (auto * le : {inspector_role_, inspector_category_, inspector_type_}) {
    if (le) { le->setEnabled(true); le->setReadOnly(true); }
  }
  inspector_update_guard_ = false;
  refresh_robot_base_pose_inspector();
  refresh_delete_selected_action();
}

QGraphicsItem * MainWindow::find_authoring_robot_base_item() const
{
  if (!digital_twin_scene_) return nullptr;
  for (auto * item : digital_twin_scene_->items()) {
    if (item->data(RoleType).toString() == "robot_base" && !item->data(RoleLocked).toBool()) return item;
  }
  return nullptr;
}

void MainWindow::refresh_robot_base_pose_inspector()
{
  if (!robot_pose_source_label_ || !robot_base_apply_button_) return;
  QGraphicsItem * selected = (digital_twin_scene_ && !digital_twin_scene_->selectedItems().isEmpty()) ? digital_twin_scene_->selectedItems().front() : nullptr;
  const bool selected_generated = selected && selected->data(RoleLocked).toBool() && selected->data(RoleType).toString() == "robot_base";
  QGraphicsItem * authoring_robot = find_authoring_robot_base_item();
  robot_base_pose_source_ = authoring_robot ? "cell_definition" : "blocked";
  if (authoring_robot && authoring_robot->data(RoleSource).toString().contains("environment.yaml")) robot_base_pose_source_ = "environment.yaml";
  robot_pose_source_label_->setText(QString("robot_pose_source: %1").arg(robot_base_pose_source_));
  const bool editable = (authoring_robot != nullptr) && !selected_generated;
  if (selected_generated && robot_pose_message_label_) robot_pose_message_label_->setText("Edit robot base via authoring model");
  else if (robot_pose_message_label_) robot_pose_message_label_->setText(editable ? "Robot base pose edits target authoring model." : "Robot base authoring pose unavailable.");
  robot_base_update_guard_ = true;
  if (authoring_robot) {
    robot_base_x_->setValue(authoring_robot->pos().x() / 100.0);
    robot_base_y_->setValue(authoring_robot->pos().y() / 100.0);
    robot_base_z_->setValue(authoring_robot->data(RolePoseZ).toDouble());
    robot_base_roll_->setValue(authoring_robot->data(RoleRoll).toDouble());
    robot_base_pitch_->setValue(authoring_robot->data(RolePitch).toDouble());
    robot_base_yaw_->setValue(authoring_robot->data(RoleYaw).toDouble());
    if (!robot_base_snapshot_valid_) {
      robot_base_snapshot_x_ = robot_base_x_->value(); robot_base_snapshot_y_ = robot_base_y_->value(); robot_base_snapshot_z_ = robot_base_z_->value();
      robot_base_snapshot_roll_ = robot_base_roll_->value(); robot_base_snapshot_pitch_ = robot_base_pitch_->value(); robot_base_snapshot_yaw_ = robot_base_yaw_->value();
      robot_base_snapshot_valid_ = true;
    }
  }
  robot_base_update_guard_ = false;
  for (auto * sb : {robot_base_x_, robot_base_y_, robot_base_z_, robot_base_roll_, robot_base_pitch_, robot_base_yaw_}) sb->setReadOnly(!editable);
  robot_base_apply_button_->setEnabled(editable);
  robot_base_reset_button_->setEnabled(editable && robot_base_snapshot_valid_);
}

void MainWindow::apply_robot_base_pose_from_inspector()
{
  if (robot_base_update_guard_) return;
  auto * authoring_robot = find_authoring_robot_base_item();
  if (!authoring_robot) { append_studio_log("robot_base_apply blocked: authoring robot base not available"); return; }
  authoring_robot->setPos(robot_base_x_->value() * 100.0, robot_base_y_->value() * 100.0);
  authoring_robot->setData(RolePoseZ, robot_base_z_->value());
  authoring_robot->setData(RoleRoll, robot_base_roll_->value());
  authoring_robot->setData(RolePitch, robot_base_pitch_->value());
  authoring_robot->setData(RoleYaw, robot_base_yaw_->value());
  append_studio_log(QString("robot_pose_source diagnostic: %1").arg(robot_base_pose_source_));
  append_studio_log(QString("robot_base_pose applied: x=%1 y=%2 z=%3 roll=%4 pitch=%5 yaw=%6")
    .arg(robot_base_x_->value()).arg(robot_base_y_->value()).arg(robot_base_z_->value())
    .arg(robot_base_roll_->value()).arg(robot_base_pitch_->value()).arg(robot_base_yaw_->value()));
  mark_layout_dirty("Robot Base Pose Apply");
  rebuild_digital_twin_canvas();
}

void MainWindow::reset_robot_base_pose_from_snapshot()
{
  if (!robot_base_snapshot_valid_) return;
  robot_base_x_->setValue(robot_base_snapshot_x_);
  robot_base_y_->setValue(robot_base_snapshot_y_);
  robot_base_z_->setValue(robot_base_snapshot_z_);
  robot_base_roll_->setValue(robot_base_snapshot_roll_);
  robot_base_pitch_->setValue(robot_base_snapshot_pitch_);
  robot_base_yaw_->setValue(robot_base_snapshot_yaw_);
  append_studio_log("robot_base_pose reset: restored from persisted authoring source snapshot");
  apply_robot_base_pose_from_inspector();
}

bool MainWindow::mounted_pose_unchanged(const QString & id, double x, double y, double z,
  double roll, double pitch, double yaw) const
{
  const auto angle_equal = [](double a, double b) { return std::abs(std::atan2(std::sin(a - b), std::cos(a - b))) <= 1e-9; };
  for (const auto & p : all_scene_preview_items_) {
    if (p.id != id) continue;
    return std::abs(p.x - x) <= 1e-9 && std::abs(p.y - y) <= 1e-9 && std::abs(p.z - z) <= 1e-9 &&
      angle_equal(p.roll, roll) && angle_equal(p.pitch, pitch) && angle_equal(p.yaw, yaw);
  }
  return false;
}

QJsonArray MainWindow::mounting_items() const
{
  QJsonArray rows;
  for (const auto & p : all_scene_preview_items_) {
    if (!p.editable || p.locked || p.source_layer != QStringLiteral("editable_layout") || deleted_layout_item_ids_.contains(p.id)) continue;
    QJsonObject row{{"id", p.id}, {"role", p.role}, {"category", p.category}, {"mounting_yaml", p.mounting_yaml},
      {"pose_xyz", QJsonArray{p.x, p.y, p.z}}, {"pose_rpy", QJsonArray{p.roll, p.pitch, p.yaw}}};
    // Reviewed catalog datums apply only to the calibrated mesh they were measured on.
    if (!p.catalog_asset_id.trimmed().isEmpty()) {
      QJsonObject mesh{{"scale", QJsonArray{p.mesh_scale_x, p.mesh_scale_y, p.mesh_scale_z}},
        {"rpy", QJsonArray{p.mesh_r, p.mesh_p, p.mesh_y}}};
      if (p.has_origin_offset) mesh.insert("origin_offset", QJsonArray{p.origin_offset_x, p.origin_offset_y, p.origin_offset_z});
      row.insert("catalog_asset_id", p.catalog_asset_id.trimmed());
      row.insert("mesh", mesh);
    }
    rows.append(row);
  }
  return rows;
}

QJsonObject MainWindow::run_mounting_request(QJsonObject request)
{
  request.insert("items", mounting_items());
  request.insert("scene_dir", selected_scene_state_.path);  // saved mesh calibration for reviewed datums
  const QString root = resolve_workcell_studio_repo_root(fs::path(selected_scene_state_.path.toStdString()));
  QProcess process;
  process.start("python3", {QDir(root).filePath("scripts/asset_mounting.py")});
  if (!process.waitForStarted(3000)) return {{"ok", false}, {"error", "Could not start asset mounting resolver; check Python installation."}};
  process.write(QJsonDocument(request).toJson(QJsonDocument::Compact));
  process.closeWriteChannel();
  if (!process.waitForFinished(5000)) {
    process.kill(); process.waitForFinished(1000);
    return {{"ok", false}, {"error", "Asset mounting resolver timed out; edits were not applied."}};
  }
  const auto response = QJsonDocument::fromJson(process.readAllStandardOutput()).object();
  if (response.isEmpty()) return {{"ok", false}, {"error", QString::fromUtf8(process.readAllStandardError())}};
  return response;
}

void MainWindow::apply_mounting_snapshot(const QVector<ScenePreviewWidget::PreviewItem> & snapshot)
{
  const QScopedValueRollback<bool> updating(mounting_update_guard_, true);
  for (const auto & p : snapshot) {
    for (auto & existing : all_scene_preview_items_) if (existing.id == p.id) { existing = p; break; }
    if (auto * canvas = find_canvas_item_by_stable_id(p.id)) {
      workcell_builder::set_authored_canvas_position(canvas, QPointF(p.x * 100., p.y * 100.));
      canvas->setData(RolePoseZ, p.z); canvas->setData(RoleRoll, p.roll);
      canvas->setData(RolePitch, p.pitch); canvas->setData(RoleYaw, p.yaw);
      canvas->setData(RoleMountingYaml, p.mounting_yaml);
      canvas->setData(RoleDisplayName, p.display_name); canvas->setData(RoleRole, p.role);
      canvas->setData(RoleWidth, p.sx); canvas->setData(RoleDepth, p.sy); canvas->setData(RoleHeight, p.sz);
      canvas->setData(RoleMetadataExplicitlyEdited, true);
    }
    if (scene_preview_widget_ && scene_preview_widget_->embedded_web_authoring_active()) {
      pending_native_web_pose_signatures_.insert(authored_pose_signature(p.id, p.x, p.y, p.z, p.roll, p.pitch, p.yaw));
      scene_preview_widget_->set_authoring_item_pose(p.id, p.x, p.y, p.z, p.roll, p.pitch, p.yaw);
    }
  }
  // Selection state is also a projection; refresh it before capturing the session.
  if (auto * selected = find_canvas_item_by_stable_id(current_selected_scene_item_id_)) {
    refresh_selection_transform_editor_from_item(selected);
  }
  refresh_scene_hierarchy_tree_from_current_items();
  capture_active_editable_layout_session();
  if (scene_preview_widget_ && !scene_preview_widget_->embedded_web_authoring_active()) apply_scene3d_preview_layer_filters(false);
  notify_mate_scene_changed();
}

bool MainWindow::commit_mounting_request(QJsonObject request)
{
  if (!ensure_live_authoring_mutation_available(QStringLiteral("Asset mounting"))) return false;
  const auto response = run_mounting_request(request);
  if (!response.value("ok").toBool()) {
    QMessageBox::warning(this, "Asset mounting", response.value("error").toString());
    return false;
  }
  QVector<ScenePreviewWidget::PreviewItem> before, after;
  // A single edit returns the rows; a multi-object arrangement returns {rows, report}.
  const QJsonValue result = response.value("result");
  const QJsonArray result_rows = result.isArray() ? result.toArray() : result.toObject().value("rows").toArray();
  for (const auto & value : result_rows) {
    const auto row = value.toObject();
    for (const auto & existing : all_scene_preview_items_) if (existing.id == row.value("id").toString()) {
      before.push_back(existing);
      auto p = existing;
      const auto xyz = row.value("pose_xyz").toArray(), rpy = row.value("pose_rpy").toArray();
      p.x = xyz[0].toDouble(); p.y = xyz[1].toDouble(); p.z = xyz[2].toDouble();
      p.roll = rpy[0].toDouble(); p.pitch = rpy[1].toDouble(); p.yaw = rpy[2].toDouble();
      p.mounting_yaml = row.value("mounting_yaml").toString();
      if (p.id == request.value("id").toString() && request.value("inspector_edit").toBool()) {
        if (inspector_display_name_ && !inspector_display_name_->text().trimmed().isEmpty()) p.display_name = inspector_display_name_->text().trimmed();
        if (inspector_semantic_role_ && !inspector_semantic_role_->currentData().toString().isEmpty()) p.role = inspector_semantic_role_->currentData().toString();
        if (inspector_dim_x_->isEnabled() && !inspector_dim_x_->isReadOnly()) {
          p.sx = inspector_dim_x_->value(); p.sy = inspector_dim_y_->value(); p.sz = inspector_dim_z_->value();
        }
      }
      after.push_back(p); break;
    }
  }
  bool changed = false;
  for (int k = 0; k < before.size() && !changed; ++k) {
    const auto & a = before[k]; const auto & b = after[k];
    changed = std::abs(a.x - b.x) > 1e-12 || std::abs(a.y - b.y) > 1e-12 || std::abs(a.z - b.z) > 1e-12 ||
      std::abs(a.roll - b.roll) > 1e-12 || std::abs(a.pitch - b.pitch) > 1e-12 || std::abs(a.yaw - b.yaw) > 1e-12 ||
      a.display_name != b.display_name || a.role != b.role || a.sx != b.sx || a.sy != b.sy || a.sz != b.sz ||
      !workcell_builder::same_mounting_metadata(a.mounting_yaml, b.mounting_yaml);
  }
  if (!changed) {
    append_studio_log(QStringLiteral("Asset mounting: %1 already has this relation and pose; nothing changed.").arg(request.value("id").toString()));
    return true;
  }
  // One command for every moved part: an arrangement undoes and redoes as one step.
  const QString command_target = request.contains("id") ? request.value("id").toString()
    : QStringLiteral("arrange:%1").arg(request.value("op").toString());
  CanvasEditCommand command{"mounting", command_target, {}, {}, false, false, before};
  command.after_items = after;
  apply_mounting_snapshot(after);
  undo_stack_.push_back(command); redo_stack_.clear();
  mark_layout_dirty("Asset mounting / hierarchical transform");
  scene_preview_widget_->set_native_authoring_history_available(true, false);
  return true;
}

void MainWindow::edit_selected_mounting()
{
  const auto target = resolve_selected_editable_layout_target();
  if (!target.ok) { QMessageBox::information(this, "Mount To", target.blocker); return; }
  const auto response = run_mounting_request({{"operation", "anchors"}});
  if (!response.value("ok").toBool()) { QMessageBox::warning(this, "Mount To", response.value("error").toString()); return; }
  const auto named = response.value("result").toObject();
  QDialog dialog(this); dialog.setWindowTitle("Mount asset — " + target.state.display_name);
  dialog.setObjectName("assetMountingDialog");
  auto * form = new QFormLayout(&dialog);
  auto * intro = new QLabel("Attach this asset to a parent. Choose a datum on each: the child datum is aligned to the "
    "parent datum. A plane's normal points outward (+Z).", &dialog);
  intro->setWordWrap(true); form->addRow(intro);
  auto * parent = new QComboBox(&dialog); parent->setObjectName("mountTo"); parent->addItem("World", "world");
  for (const auto & p : all_scene_preview_items_) if (named.contains(p.id) && p.id != target.state.id && !p.semantic_task_zone_helper)
    parent->addItem(p.display_name + " [" + p.id + "]", p.id);
  auto * anchor = new QComboBox(&dialog); anchor->setObjectName("mountAnchor");
  auto * child_datum = new QComboBox(&dialog); child_datum->setObjectName("mountChildDatum");
  auto * alignment = new QComboBox(&dialog); alignment->setObjectName("mountAlignment");
  alignment->addItem("Coincident — datum frames line up", "coincident");
  alignment->addItem("Flush — plane faces touch, normals opposed", "flush");
  // Datum lists: origin first, then the asset's own and reviewed catalog datums.
  const auto add_datums = [](QComboBox * combo, const QJsonObject & datums) {
    const QSignalBlocker blocker(combo);
    combo->clear();
    QStringList names = datums.keys();
    names.removeAll(QStringLiteral("origin")); if (datums.contains(QStringLiteral("origin"))) names.prepend(QStringLiteral("origin"));
    for (const auto & name : names) {
      const auto datum = datums.value(name).toObject();
      combo->addItem(workcell_builder::datum_choice_text(name, datum.value("datum_type").toString(), datum.value("label").toString()), name);
      combo->setItemData(combo->count() - 1, datum.contains("catalog_asset_id")
        ? QString("Reviewed datum from the asset catalog (%1); it is copied into this cell when used.").arg(datum.value("catalog_asset_id").toString())
        : QString("Datum defined on this asset."), Qt::ToolTipRole);
    }
  };
  const auto fill_anchors = [parent, anchor, named, add_datums]() {
    const auto id = parent->currentData().toString();
    if (id == "world") { const QSignalBlocker blocker(anchor); anchor->clear(); anchor->addItem("world", "world"); }
    else add_datums(anchor, named.value(id).toObject());
  };
  add_datums(child_datum, named.value(target.state.id).toObject());
  form->addRow("Mount To", parent); form->addRow("Parent datum", anchor);
  form->addRow("Child datum", child_datum); form->addRow("Alignment", alignment);
  auto * relative = new QCheckBox("Move the asset: align the datums with this offset", &dialog); relative->setObjectName("applyRelativePose");
  form->addRow(relative);
  std::array<QDoubleSpinBox *, 6> values;
  const std::array<const char *, 6> keys{{"x", "y", "z", "roll", "pitch", "yaw"}};
  const std::array<const char *, 6> labels{{"Offset X", "Offset Y", "Offset Z (along normal)", "Offset roll", "Offset pitch", "Offset yaw (about normal)"}};
  const auto relation = [this, &target]() {
    for (const auto & p : all_scene_preview_items_) if (p.id == target.state.id) return workcell_builder::parse_mount_relation(p.mounting_yaml);
    return workcell_builder::MountRelation{};
  }();
  if (relation.mounted) parent->setCurrentIndex(qMax(0, parent->findData(relation.parent_id)));
  fill_anchors();
  if (relation.mounted) {
    anchor->setCurrentIndex(qMax(0, anchor->findData(relation.parent_datum)));
    child_datum->setCurrentIndex(qMax(0, child_datum->findData(relation.child_datum)));
    alignment->setCurrentIndex(qMax(0, alignment->findData(relation.alignment)));
  }
  for (int k = 0; k < 6; ++k) {
    values[k] = new QDoubleSpinBox(&dialog); values[k]->setRange(k < 3 ? -1000. : -360., k < 3 ? 1000. : 360.); values[k]->setDecimals(k < 3 ? 4 : 3);
    values[k]->setSingleStep(k < 3 ? 0.01 : 1.); values[k]->setSuffix(k < 3 ? " m" : "°"); values[k]->setKeyboardTracking(false);
    values[k]->setObjectName(QString("relative_%1").arg(keys[k]));
    values[k]->setValue(k < 3 ? relation.offset[k] : qRadiansToDegrees(relation.offset[k])); values[k]->setEnabled(false);
    connect(relative, &QCheckBox::toggled, values[k], &QWidget::setEnabled);
    form->addRow(labels[k], values[k]);
  }
  auto * preview = new QLabel(&dialog); preview->setObjectName("mountPreview"); preview->setWordWrap(true);
  preview->setTextInteractionFlags(Qt::TextSelectableByMouse);
  form->addRow("Preview", preview);
  auto * note = new QLabel("Unticked, the asset keeps its world pose and the offset is measured from where it is now. "
    "Detach keeps the world pose and removes the mate. Children and linked destination zones follow.", &dialog);
  note->setWordWrap(true); form->addRow(note);
  auto * buttons = new QDialogButtonBox(QDialogButtonBox::Apply | QDialogButtonBox::Cancel, &dialog);
  auto * detach = buttons->addButton("Detach", QDialogButtonBox::ActionRole); detach->setObjectName("detachAsset");
  detach->setEnabled(relation.mounted);
  detach->setAutoDefault(false); buttons->button(QDialogButtonBox::Cancel)->setAutoDefault(false);
  buttons->button(QDialogButtonBox::Apply)->setDefault(true);  // Return applies; it never detaches
  form->addRow(buttons);
  const auto build_request = [target, parent, anchor, child_datum, alignment, relative, values]() {
    const QString parent_id = parent->currentData().toString();
    QJsonObject request{{"id", target.state.id}, {"parent_object", parent_id}, {"parent_link", anchor->currentData().toString()}};
    if (parent_id != "world") {
      request.insert("child_datum", child_datum->currentData().toString());
      request.insert("alignment", alignment->currentData().toString());
    }
    if (relative->isChecked()) request.insert("relative_pose", QJsonObject{
      {"xyz", QJsonArray{values[0]->value(), values[1]->value(), values[2]->value()}},
      {"rpy", QJsonArray{qDegreesToRadians(values[3]->value()), qDegreesToRadians(values[4]->value()), qDegreesToRadians(values[5]->value())}}});
    return request;
  };
  // A dry run through the same resolver; nothing is applied until Apply.
  const auto refresh_preview = [this, &target, parent, child_datum, alignment, preview, buttons, build_request]() {
    const bool world = parent->currentData().toString() == "world";
    child_datum->setEnabled(!world); alignment->setEnabled(!world);
    const auto result = run_mounting_request(build_request());
    auto * apply = buttons->button(QDialogButtonBox::Apply);
    if (!result.value("ok").toBool()) {
      preview->setStyleSheet(QStringLiteral("color:%1;").arg(workcell_builder::studioTokens().danger));
      preview->setText("Cannot apply: " + result.value("error").toString());
      apply->setEnabled(false);
      return;
    }
    QStringList followers; QString line;
    for (const auto & value : result.value("result").toArray()) {
      const auto row = value.toObject();
      const auto xyz = row.value("pose_xyz").toArray(), rpy = row.value("pose_rpy").toArray();
      for (const auto & p : all_scene_preview_items_) if (p.id == row.value("id").toString()) {
        const double moved = std::hypot(xyz[0].toDouble() - p.x, xyz[1].toDouble() - p.y, xyz[2].toDouble() - p.z);
        const double turned = std::max({std::abs(rpy[0].toDouble() - p.roll), std::abs(rpy[1].toDouble() - p.pitch), std::abs(rpy[2].toDouble() - p.yaw)});
        if (p.id == target.state.id) {
          line = QString("%1 at X %2 · Y %3 · Z %4 m, roll %5° · pitch %6° · yaw %7° (moves %8 mm)")
            .arg(p.display_name).arg(xyz[0].toDouble(), 0, 'f', 4).arg(xyz[1].toDouble(), 0, 'f', 4).arg(xyz[2].toDouble(), 0, 'f', 4)
            .arg(qRadiansToDegrees(rpy[0].toDouble()), 0, 'f', 1).arg(qRadiansToDegrees(rpy[1].toDouble()), 0, 'f', 1)
            .arg(qRadiansToDegrees(rpy[2].toDouble()), 0, 'f', 1).arg(moved * 1000., 0, 'f', 1);
          const auto resulting = workcell_builder::parse_mount_relation(row.value("mounting_yaml").toString());
          if (resulting.mounted) line += "\n" + workcell_builder::mount_offset_text(resulting);
        } else if (moved > 1e-9 || turned > 1e-9) {
          followers << p.display_name;
        }
        if ((moved > 1e-9 || turned > 1e-9)) for (const auto & zone : all_scene_preview_items_)
          if (zone.target_ref == p.id) followers << zone.display_name + " (destination zone, keeps its target-local placement)";
      }
    }
    preview->setStyleSheet(QString());
    preview->setText(line + (followers.isEmpty() ? QString() : "\nFollows: " + followers.join(", ")));
    apply->setEnabled(true);
  };
  connect(parent, qOverload<int>(&QComboBox::currentIndexChanged), &dialog, [fill_anchors, refresh_preview](int){ fill_anchors(); refresh_preview(); });
  for (auto * combo : {anchor, child_datum, alignment})
    connect(combo, qOverload<int>(&QComboBox::currentIndexChanged), &dialog, [refresh_preview](int){ refresh_preview(); });
  connect(relative, &QCheckBox::toggled, &dialog, [refresh_preview](bool){ refresh_preview(); });
  for (auto * value : values) connect(value, qOverload<double>(&QDoubleSpinBox::valueChanged), &dialog, [refresh_preview](double){ refresh_preview(); });
  refresh_preview();
  connect(buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);
  connect(detach, &QPushButton::clicked, &dialog, [this, &dialog, target]() {
    if (commit_mounting_request({{"id", target.state.id}, {"parent_object", "world"}, {"parent_link", "world"}})) dialog.accept();
  });
  connect(buttons->button(QDialogButtonBox::Apply), &QPushButton::clicked, &dialog, [this, &dialog, build_request]() {
    if (commit_mounting_request(build_request())) dialog.accept();
  });
  dialog.exec();
}

namespace
{

workcell_builder::MateVec3 mate_vec3(const QVariant & value)
{
  const auto list = value.toList();
  const double nan = std::numeric_limits<double>::quiet_NaN();
  if (list.size() != 3) return {nan, nan, nan};
  workcell_builder::MateVec3 out{};
  for (int k = 0; k < 3; ++k) {
    bool ok = false;
    out[k] = list[k].toDouble(&ok);
    if (!ok) out[k] = nan;
  }
  return out;
}

workcell_builder::MateRawPick mate_raw_pick(const QVariantMap & map, const QString & backend)
{
  workcell_builder::MateRawPick pick;
  pick.backend = backend;
  pick.asset_id = map.value(QStringLiteral("asset_id")).toString();
  pick.geometry = map.value(QStringLiteral("geometry")).toString() == QStringLiteral("datum_marker")
    ? workcell_builder::MatePickGeometry::DatumMarker : workcell_builder::MatePickGeometry::Surface;
  pick.datum_name = map.value(QStringLiteral("datum_name")).toString();
  pick.point_world = mate_vec3(map.value(QStringLiteral("point_world")));
  pick.normal_world = mate_vec3(map.value(QStringLiteral("normal_world")));
  pick.ray_direction_world = mate_vec3(map.value(QStringLiteral("ray_direction_world")));
  const auto pose = map.value(QStringLiteral("object_pose_world")).toList();
  if (pose.size() == 6) {
    pick.has_object_pose = true;
    for (int k = 0; k < 6; ++k) pick.object_pose_world[k] = pose[k].toDouble();
  }
  pick.geometry_source = map.value(QStringLiteral("geometry_source")).toString();
  pick.triangle_index = map.value(QStringLiteral("triangle_index"), -1).toInt();
  return pick;
}

}  // namespace

bool MainWindow::mate_active() const
{
  return mate_controller_ && mate_controller_->active();
}

QString MainWindow::mate_backend_note() const
{
  if (!scene_preview_widget_) {
    return QStringLiteral("No 3D view is available. Choose the parts in the Scene Hierarchy and their datums from the lists.");
  }
  if (scene_preview_widget_->embedded_web_authoring_active()) {
    if (mate_web_supported_) return QString();
    return QStringLiteral("The loaded Product View cannot pick faces yet (reload the cell). Choose the parts in the Scene "
      "Hierarchy and their datums from the lists.");
  }
  return QStringLiteral("Face picking is not available in the native Scene3D fallback view: its picking only knows "
    "bounding boxes, not faces. Click a part in the 3D view or the Scene Hierarchy, then choose its datum from the list.");
}

void MainWindow::begin_visual_mate()
{
  if (!mate_controller_ || !mate_panel_) return;
  if (mate_active()) return;
  const auto stop = [this](const QString & message) {
    if (scene_builder_mate_button_) { const QSignalBlocker blocker(scene_builder_mate_button_); scene_builder_mate_button_->setChecked(false); }
    append_studio_log(message);
    QMessageBox::information(this, QStringLiteral("Mate"), message);
  };
  if (!has_selected_scene()) { stop(QStringLiteral("Open a cell before using Mate.")); return; }
  mate_scene_path_ = selected_scene_state_.path;
  mate_last_pick_evidence_ = {};
  QString error;
  if (!mate_controller_->begin(current_selected_scene_item_id_, &error)) { stop(error); return; }
  mate_controller_->set_backend_note(mate_backend_note());
  apply_scene_builder_panel_visibility(true, true);
  if (scene_builder_inspector_tabs_) scene_builder_inspector_tabs_->hide();
  mate_panel_->show();
  append_studio_log(QStringLiteral("Mate tool started for %1 (%2).").arg(selected_scene_state_.name,
    mate_backend_note().isEmpty() ? QStringLiteral("face picking in Web3D") : QStringLiteral("hierarchy and datum lists")));
  push_mate_overlay();
}

void MainWindow::end_visual_mate(bool applied, const QString & message)
{
  if (mate_panel_) mate_panel_->hide();
  if (scene_builder_inspector_tabs_) scene_builder_inspector_tabs_->show();
  if (scene_builder_mate_button_) { const QSignalBlocker blocker(scene_builder_mate_button_); scene_builder_mate_button_->setChecked(false); }
  if (scene_preview_widget_ && scene_preview_widget_->embedded_web_authoring_active()) scene_preview_widget_->clear_mate_overlay();
  append_studio_log(QStringLiteral("Mate: %1").arg(message));
  if (applied && !mate_last_pick_evidence_.value("child").toString().isEmpty()) {
    apply_scene_selection(mate_last_pick_evidence_.value("child").toString(), QString(), false, false);
  }
  refresh_selected_item_card();
}

bool MainWindow::leave_cell_session_for(int scene_index)
{
  if (scene_index == selected_scene_index_) return true;
  if (layout_dirty_) {
    QMessageBox box(QMessageBox::Warning, QStringLiteral("Unsaved layout edits"),
      QStringLiteral("%1 has unsaved layout edits. Opening another cell discards them; Undo cannot bring them back.")
        .arg(selected_scene_state_.name.isEmpty() ? QStringLiteral("This cell") : selected_scene_state_.name),
      QMessageBox::NoButton, this);
    box.setObjectName(QStringLiteral("unsavedLayoutSwitchDialog"));
    box.setInformativeText(QStringLiteral("To keep them, choose Stay and use Save Layout (Ctrl+S) first."));
    auto * discard = box.addButton(QStringLiteral("Discard edits and open"), QMessageBox::DestructiveRole);
    box.setDefaultButton(box.addButton(QStringLiteral("Stay"), QMessageBox::RejectRole));
    box.exec();
    if (box.clickedButton() != discard) return false;
    append_studio_log(QStringLiteral("Unsaved layout edits in %1 were discarded on opening another cell.").arg(selected_scene_state_.name));
  }
  // Undo/redo, deletions and the selection belong to the cell they were made in. Many
  // cells share IDs (target_bin_default ...): replaying them in another cell would
  // move the wrong parts there.
  if (arrange_active()) arrange_controller_->cancel(QStringLiteral("Arrangement cancelled: another cell was opened. Nothing was applied."));
  undo_stack_.clear();
  redo_stack_.clear();
  deleted_layout_item_ids_.clear();
  selection_set_.clear();
  layout_dirty_ = false;
  validation_stale_ = false;  // in-session edits since the last validation belong to the old cell
  launch_artifacts_ready_ = false;  // so does the last Generate result
  setWindowModified(false);
  if (save_layout_button_) {
    save_layout_button_->setProperty("layoutDirty", false);
    save_layout_button_->setEnabled(false);
    save_layout_button_->style()->unpolish(save_layout_button_);
    save_layout_button_->style()->polish(save_layout_button_);
  }
  if (scene_preview_widget_) scene_preview_widget_->set_native_authoring_history_available(false, false);
  return true;
}

void MainWindow::cancel_mate_for_other_cell(int scene_index)
{
  // Mate belongs to the cell it started in; Apply must never commit into another one.
  if (arrange_active() && scene_index != selected_scene_index_) {
    arrange_controller_->cancel(QStringLiteral("Arrangement cancelled: another cell was opened. Nothing was applied."));
  }
  if (mate_active() && scene_index != selected_scene_index_) {
    mate_controller_->cancel(QStringLiteral("Mate cancelled: another cell was opened. Nothing was applied."));
  }
}

void MainWindow::push_mate_overlay()
{
  if (!mate_controller_) return;
  const bool active = mate_controller_->active();
  if (scene_builder_mate_button_) { const QSignalBlocker blocker(scene_builder_mate_button_); scene_builder_mate_button_->setChecked(active); }
  if (!active) return;
  if (mate_scene_path_ != selected_scene_state_.path) {
    mate_controller_->cancel(QStringLiteral("Mate cancelled: another cell was opened. Nothing was applied."));
    return;
  }
  const auto & child = mate_controller_->child();
  const auto & parent = mate_controller_->parent();
  if (child) mate_last_pick_evidence_.insert("child", child->asset_id);
  // Hierarchy and selection card follow the part of the current step.
  QString focus = mate_controller_->pending_asset();
  if (focus.isEmpty()) focus = parent ? parent->asset_id : (child ? child->asset_id : QString());
  if (!focus.isEmpty() && focus != current_selected_scene_item_id_) {
    const QScopedValueRollback<bool> passthrough(mate_selection_passthrough_, true);
    apply_scene_selection(focus, QString(), false, false);
  }
  if (scene_preview_widget_ && scene_preview_widget_->embedded_web_authoring_active()) {
    scene_preview_widget_->set_mate_overlay(mate_controller_->overlay());
    mate_overlay_sent_ms_ = QDateTime::currentMSecsSinceEpoch();
  }
}

void MainWindow::handle_embedded_mate_state(const QVariantMap & mate)
{
  const bool supported = !mate.isEmpty();
  if (supported != mate_web_supported_) {
    mate_web_supported_ = supported;
    if (mate_active()) mate_controller_->set_backend_note(mate_backend_note());
  }
  if (!supported) return;
  const qint64 pick_seq = mate.value(QStringLiteral("seq")).toLongLong();
  const qint64 hover_seq = mate.value(QStringLiteral("hoverSeq")).toLongLong();
  const qint64 cancel_seq = mate.value(QStringLiteral("cancelSeq")).toLongLong();
  if (!mate_active()) {
    // Ignore anything the viewer recorded outside a mate operation.
    mate_seen_pick_seq_ = pick_seq; mate_seen_hover_seq_ = hover_seq; mate_seen_cancel_seq_ = cancel_seq;
    if (mate.value(QStringLiteral("active")).toBool() && scene_preview_widget_) scene_preview_widget_->clear_mate_overlay();
    return;
  }
  // A reloaded viewer counts from zero again: rebase so its next click and Esc are not ignored.
  const bool viewer_active = mate.value(QStringLiteral("active")).toBool();
  if (workcell_builder::mate_viewer_counters_rebase({mate_seen_pick_seq_, mate_seen_hover_seq_, mate_seen_cancel_seq_},
        {pick_seq, hover_seq, cancel_seq}, viewer_active)) {
    mate_seen_pick_seq_ = pick_seq; mate_seen_hover_seq_ = hover_seq; mate_seen_cancel_seq_ = cancel_seq;
  }
  if (!viewer_active) {
    if (QDateTime::currentMSecsSinceEpoch() - mate_overlay_sent_ms_ > 1000) push_mate_overlay();  // the viewer reloaded its scene; restore the overlay
    return;
  }
  if (cancel_seq > mate_seen_cancel_seq_) {
    mate_seen_cancel_seq_ = cancel_seq;
    mate_controller_->cancel();
    return;
  }
  if (pick_seq > mate_seen_pick_seq_) {
    mate_seen_pick_seq_ = pick_seq;
    const auto resolution = mate_controller_->pick(mate_raw_pick(mate.value(QStringLiteral("pick")).toMap(), QStringLiteral("embedded_web3d")));
    append_studio_log(QStringLiteral("Mate pick (%1): %2").arg(resolution.reason_code, resolution.reason));
  }
  if (hover_seq > mate_seen_hover_seq_ && scene_preview_widget_ && mate_active()) {
    mate_seen_hover_seq_ = hover_seq;
    const auto hover = mate.value(QStringLiteral("hover")).toMap();
    QJsonObject result{{"seq", hover_seq}};
    if (!hover.isEmpty()) {
      const auto r = mate_controller_->hover(mate_raw_pick(hover, QStringLiteral("embedded_web3d")));
      result = QJsonObject{{"seq", hover_seq}, {"asset_id", r.asset_id}, {"asset_label", mate_controller_->display_name(r.asset_id)},
        {"datum", r.datum_name}, {"valid", r.valid}, {"label", r.datum_label},
        {"reason", workcell_builder::MateToolController::short_reason(r)}, {"reason_code", r.reason_code}};
    }
    scene_preview_widget_->set_mate_hover_resolution(result);
  }
}

void MainWindow::notify_mate_scene_changed()
{
  if (!mate_active() || mate_scene_change_pending_) return;
  mate_scene_change_pending_ = true;
  QTimer::singleShot(0, this, [this]() {
    mate_scene_change_pending_ = false;
    if (mate_active()) mate_controller_->scene_changed();
  });
}

namespace
{

const ScenePreviewWidget::PreviewItem * align_find_item(const QVector<ScenePreviewWidget::PreviewItem> & items, const QString & id)
{
  for (const auto & p : items) if (p.id == id) return &p;
  return nullptr;
}

bool align_is_zone(const ScenePreviewWidget::PreviewItem & p)
{
  return p.semantic_task_zone_helper || p.category.toLower() == QStringLiteral("zone") || p.role.toLower().contains(QStringLiteral("zone"));
}

QString align_name(const ScenePreviewWidget::PreviewItem & p)
{
  return p.display_name.trimmed().isEmpty() ? p.id : p.display_name.trimmed();
}

}  // namespace

QString MainWindow::align_moving_blocker(const QString & id) const
{
  const auto * item = align_find_item(all_scene_preview_items_, id);
  if (!item || deleted_layout_item_ids_.contains(id)) return QStringLiteral("%1 is no longer in this cell.").arg(id);
  const QString name = align_name(*item);
  if (align_is_zone(*item)) {
    return QStringLiteral("%1 is a task zone: zones are task semantics and follow their target. Select the physical part "
      "instead.").arg(name);
  }
  if (item->robot_candidate) {
    return QStringLiteral("%1 belongs to the generated robot or tool model and is locked here. Select a placed asset "
      "such as a bin, fixture or table.").arg(name);
  }
  if (item->source_layer != QStringLiteral("editable_layout")) {
    return QStringLiteral("%1 is not an authored physical part (source: %2). Select a placed asset such as a bin, fixture "
      "or table.").arg(name, item->source_layer.isEmpty() ? QStringLiteral("unknown") : item->source_layer);
  }
  if (item->locked || !item->editable) {
    return QStringLiteral("%1 is locked%2. Unlock it before moving it.")
      .arg(name, item->lock_reason.trimmed().isEmpty() ? QString() : QStringLiteral(" (%1)").arg(item->lock_reason.trimmed()));
  }
  return QString();
}

QString MainWindow::align_reference_blocker(const QString & id, QJsonObject * world) const
{
  const auto * item = align_find_item(all_scene_preview_items_, id);
  if (!item || deleted_layout_item_ids_.contains(id)) return QStringLiteral("%1 is no longer in this cell.").arg(id);
  const QString name = align_name(*item);
  if (align_is_zone(*item)) return QStringLiteral("%1 is a task zone, not a physical part. Choose a physical reference.").arg(name);
  if (item->robot_candidate) {
    return QStringLiteral("%1 belongs to the generated robot or tool model; its geometry is not an authored part. "
      "Choose the table, a bin or another placed asset as the reference.").arg(name);
  }
  if (item->source_layer != QStringLiteral("editable_layout")) {
    return QStringLiteral("%1 is not an authored physical part (source: %2). Choose the table, a bin or another placed "
      "asset as the reference.").arg(name, item->source_layer.isEmpty() ? QStringLiteral("unknown") : item->source_layer);
  }
  // A locked reference is not an editable resolver row: report its authored world pose.
  if (world && (item->locked || !item->editable)) {
    *world = QJsonObject{{"xyz", QJsonArray{item->x, item->y, item->z}}, {"rpy", QJsonArray{item->roll, item->pitch, item->yaw}}};
  }
  return QString();
}

bool MainWindow::arrange_active() const
{
  return arrange_controller_ && arrange_controller_->active();
}

void MainWindow::toggle_scene_selection(const QString & id)
{
  const QString part = id.trimmed();
  if (part.isEmpty() || mate_active()) return;
  const auto * item = align_find_item(all_scene_preview_items_, part);
  if (!item || deleted_layout_item_ids_.contains(part)) return;
  if (item->semantic_task_zone_helper || item->source_layer == QStringLiteral("overlay")) {
    statusBar()->showMessage(QStringLiteral("%1 is a task helper, not a part; it cannot join a multi-selection.")
      .arg(align_name(*item)), 5000);
    return;
  }
  if (selection_set_.isEmpty()) { apply_scene_selection(part, QString(), false, false); return; }
  selection_set_.toggle(part);
  hierarchy_range_anchor_ = part;
  if (selection_set_.isEmpty()) { apply_scene_selection(QString(), QString(), true, false); return; }
  // The Inspector shows the reference; the other members stay selected around it.
  const QScopedValueRollback<bool> keep(selection_set_passthrough_, true);
  apply_scene_selection(selection_set_.primary(), QString(), false, false);
}

void MainWindow::extend_scene_selection_to(const QString & id)
{
  if (!scene_hierarchy_tree_) return;
  QStringList ordered;
  for (QTreeWidgetItemIterator it(scene_hierarchy_tree_); *it; ++it) {
    const QString row = (*it)->data(0, TreeRoleId).toString().trimmed();
    if (!row.isEmpty() && !ordered.contains(row)) ordered << row;
  }
  const int from = ordered.indexOf(hierarchy_range_anchor_.isEmpty() ? id : hierarchy_range_anchor_);
  const int to = ordered.indexOf(id);
  if (from < 0 || to < 0) { apply_scene_selection(id, QString(), false, true); return; }
  if (selection_set_.isEmpty()) selection_set_.select_only(ordered.at(from));
  selection_set_.extend(ordered.mid(std::min(from, to), std::abs(to - from) + 1));
  const QScopedValueRollback<bool> keep(selection_set_passthrough_, true);
  apply_scene_selection(selection_set_.primary(), QString(), false, false);
}

void MainWindow::set_selection_reference(const QString & id)
{
  if (!selection_set_.set_reference(id)) return;
  const QScopedValueRollback<bool> keep(selection_set_passthrough_, true);
  apply_scene_selection(id, QString(), false, false);
  append_studio_log(QStringLiteral("Selection reference: %1").arg(id));
}

void MainWindow::sync_selection_set_views()
{
  const QStringList members = selection_set_.members();
  const QString reference = selection_set_.reference();
  const auto name_of = [this](const QString & id) {
    const auto * item = align_find_item(all_scene_preview_items_, id);
    return item ? align_name(*item) : id;
  };
  if (scene_hierarchy_tree_ && members.size() >= 2) {
    const QSignalBlocker blocker(scene_hierarchy_tree_);
    const QScopedValueRollback<bool> guard(selection_update_guard_, true);
    for (QTreeWidgetItemIterator it(scene_hierarchy_tree_); *it; ++it) {
      const QString row = (*it)->data(0, TreeRoleId).toString().trimmed();
      (*it)->setSelected(!row.isEmpty() && members.contains(row));
    }
  }
  QList<QPair<QString, QString>> named;
  for (const auto & id : members) named.append({id, name_of(id)});
  if (arrange_toolbar_) arrange_toolbar_->set_selection(named, reference);
  if (scene_preview_widget_) scene_preview_widget_->set_selection_set(members.size() >= 2 ? members : QStringList(), reference);
  if (inspector_multi_selection_label_) {
    if (members.size() >= 2) {
      QStringList others;
      for (const auto & id : selection_set_.others()) {
        others << (align_moving_blocker(id).isEmpty() ? name_of(id).toHtmlEscaped()
                                                      : QStringLiteral("%1 (locked)").arg(name_of(id).toHtmlEscaped()));
      }
      inspector_multi_selection_label_->setText(QStringLiteral(
        "<b>%1 parts selected</b> — reference <b>%2</b> (stays put; shown below).<br/>Also selected: %3<br/>"
        "<i>Arrange them with the toolbar above the 3D view. Ctrl+click adds or removes parts.</i>")
        .arg(members.size()).arg(name_of(reference).toHtmlEscaped(), others.join(QStringLiteral(", "))));
    }
    inspector_multi_selection_label_->setVisible(members.size() >= 2);
  }
  if (inspector_transform_title_) {
    inspector_transform_title_->setText(members.size() >= 2
      ? QStringLiteral("<b>Transform — %1 only</b><br/>Edits the reference; move all selected parts with Move / rotate… "
          "on the arrangement toolbar. Metres and degrees.").arg(name_of(reference).toHtmlEscaped())
      : QStringLiteral("<b>Transform</b><br/>Position in metres; rotation in degrees."));
  }
  refresh_delete_selected_action();
  refresh_duplicate_selected_action();
  if (arrange_active()) arrange_controller_->scene_changed();
}

void MainWindow::push_arrange_overlay()
{
  if (!scene_preview_widget_) return;
  if (arrange_active()) scene_preview_widget_->set_arrange_preview(arrange_controller_->overlay());
  else scene_preview_widget_->clear_arrange_preview();
}

QString MainWindow::arrange_extra_availability(const QString & tool) const
{
  if (tool == QStringLiteral("group")) {
    return QStringLiteral("Groups are not part of the scene contract yet. Use Fixed mount to keep parts together "
      "(they follow the reference), or Detach to separate them.");
  }
  if (selection_set_.size() != 2) {
    return QStringLiteral("Verified-face mating works on exactly two parts: the reference and the part to seat on it.");
  }
  const QString moving = selection_set_.others().value(0), reference = selection_set_.reference();
  if (const QString blocker = align_moving_blocker(moving); !blocker.isEmpty()) return blocker;
  QJsonObject world;
  if (const QString blocker = align_reference_blocker(reference, &world); !blocker.isEmpty()) return blocker;
  if (!world.isEmpty()) return QStringLiteral("The reference is locked; Mate seats a part on an editable part only.");
  if (tool != QStringLiteral("concentric")) return QString();
  // Concentric needs verified axis datums on both parts (reviewed datums, never mesh triangles).
  auto * self = const_cast<MainWindow *>(this);
  const QString key = QString::fromLatin1(QCryptographicHash::hash(
    QJsonDocument(self->mounting_items()).toJson(QJsonDocument::Compact) + (moving + "|" + reference).toUtf8(),
    QCryptographicHash::Sha1).toHex());
  if (concentric_availability_cache_.contains(key)) return concentric_availability_cache_.value(key);
  const auto response = self->run_mounting_request({{"operation", "datum_frames"}});
  QString reason;
  if (!response.value("ok").toBool()) {
    reason = QStringLiteral("Datums could not be read: %1").arg(response.value("error").toString());
  } else {
    const auto frames = response.value("result").toObject();
    for (const auto & id : {moving, reference}) {
      bool has_axis = false;
      const auto datums = frames.value(id).toObject().value("datums").toObject();
      for (const auto & datum : datums) has_axis = has_axis || datum.toObject().value("datum_type").toString() == QStringLiteral("axis");
      if (!has_axis) {
        reason = QStringLiteral("%1 has no verified cylindrical axis datum; concentric mating needs one on both parts.")
          .arg(align_name(*align_find_item(all_scene_preview_items_, id)));
        break;
      }
    }
  }
  concentric_availability_cache_.insert(key, reason);
  return reason;
}

void MainWindow::arrange_mate_handoff(const QString & kind)
{
  if (selection_set_.size() != 2) return;
  const QString moving = selection_set_.others().value(0), reference = selection_set_.reference();
  if (arrange_active()) arrange_controller_->cancel(QStringLiteral("Switched to Mate; nothing changed."));
  apply_scene_selection(moving, QString(), false, false);
  begin_visual_mate();
  if (!mate_active()) return;
  if (kind == QStringLiteral("concentric") || kind == QStringLiteral("coincident")) mate_controller_->set_alignment(QStringLiteral("coincident"));
  append_studio_log(QStringLiteral("Mate (%1) started from the arrangement toolbar: pick the %2 of %3, then of %4.")
    .arg(kind, kind == QStringLiteral("concentric") ? QStringLiteral("axis datum") : QStringLiteral("face or datum"),
      moving, reference));
}

void MainWindow::apply_selection_transform_from_editor() { apply_inspector_pose_to_item(); }

void MainWindow::apply_inspector_pose_to_item()
{
  if (inspector_update_guard_) return;

  const auto target = resolve_selected_editable_layout_target();
  if (!target.ok) {
    append_studio_log(QString("Inspector transform edit blocked: %1").arg(target.blocker));
    return;
  }
  if (!ensure_live_authoring_mutation_available(QStringLiteral("Inspector edit"))) return;
  // Fields the user did not touch keep the item's exact value, not the rounded display.
  const double applied_x = workcell_builder::inspector_applied_value(inspector_x_, target.state.pose_x);
  const double applied_y = workcell_builder::inspector_applied_value(inspector_y_, target.state.pose_y);
  const double applied_z = workcell_builder::inspector_applied_value(inspector_z_, target.state.pose_z);
  const auto applied_angle = [](const QDoubleSpinBox * spin, double exact_radians) {
    return workcell_builder::inspector_field_changed(spin, qRadiansToDegrees(exact_radians)) ? qDegreesToRadians(spin->value()) : exact_radians;
  };
  const double updated_roll = applied_angle(inspector_roll_, target.state.roll);
  const double updated_pitch = applied_angle(inspector_pitch_, target.state.pitch);
  const double updated_yaw = applied_angle(inspector_yaw_, target.state.yaw);

  bool mounted_graph = false;
  for (const auto & row : mounting_items()) {
    const auto meta = YAML::Load(row.toObject().value("mounting_yaml").toString().toStdString());
    mounted_graph = mounted_graph || (meta && meta["parent_object"] && meta["parent_object"].as<std::string>() != "world");
  }
  if (mounted_graph) {
    commit_mounting_request(QJsonObject{{"id", target.state.id}, {"inspector_edit", true}, {"world_pose", QJsonObject{
      {"xyz", QJsonArray{applied_x, applied_y, applied_z}},
      {"rpy", QJsonArray{updated_roll, updated_pitch, updated_yaw}}}}});
    return;
  }
  QGraphicsItem * i = target.fallback_item;
  const QString item_id = target.state.id.trimmed();
  const QPointF old(target.state.pose_x * 100.0, target.state.pose_y * 100.0);
  const QPointF updated(applied_x * 100.0, applied_y * 100.0);
  ScenePreviewWidget::PreviewItem before_item;
  for (const auto & preview_item : all_scene_preview_items_) {
    if (preview_item.id.trimmed() == item_id) { before_item = preview_item; break; }
  }

  QString updated_display_name;
  QString updated_semantic_role = target.state.role;
  bool metadata_changed = false;
  if (i) {
    workcell_builder::set_authored_canvas_position(i, updated);
    i->setData(RolePoseZ, applied_z);
    i->setData(RoleRoll, updated_roll);
    i->setData(RolePitch, updated_pitch);
    i->setData(RoleYaw, updated_yaw);
    if (inspector_dim_x_->isEnabled() && !inspector_dim_x_->isReadOnly()) {
      i->setData(RoleWidth, inspector_dim_x_->value());
      i->setData(RoleDepth, inspector_dim_y_->value());
      i->setData(RoleHeight, inspector_dim_z_->value());
    }
    if (inspector_display_name_) {
      updated_display_name = inspector_display_name_->text().trimmed();
      if (!updated_display_name.isEmpty()) {
        metadata_changed = updated_display_name != i->data(RoleDisplayName).toString().trimmed();
        if (metadata_changed) {
          i->setData(RoleDisplayName, updated_display_name);
        }
      }
    }
    if (inspector_semantic_role_) {
      const QString chosen_role = inspector_semantic_role_->currentData().toString().trimmed();
      const QString authored_role = i->data(RoleRole).toString().trimmed();
      // Apply used to treat the displayed alias ("place_target_bin" for an
      // authored "target_bin") as a user edit and rewrote the authored role.
      if (workcell_builder::semantic_role_actually_changed(chosen_role, authored_role,
            canonical_scene_hierarchy_role(authored_role, i->data(RoleCategory).toString(), QString()))) {
        updated_semantic_role = chosen_role;
        i->setData(RoleRole, updated_semantic_role);
        metadata_changed = true;
      }
    }
    if (metadata_changed) i->setData(RoleMetadataExplicitlyEdited, true);
  }

  SelectedSceneItemState refreshed_state = target.state;
  refreshed_state.pose_available = true;
  refreshed_state.pose_x = applied_x;
  refreshed_state.pose_y = applied_y;
  refreshed_state.pose_z = applied_z;
  refreshed_state.roll = updated_roll;
  refreshed_state.pitch = updated_pitch;
  refreshed_state.yaw = updated_yaw;
  if (inspector_dim_x_->isEnabled() && !inspector_dim_x_->isReadOnly()) {
    refreshed_state.dim_x = inspector_dim_x_->value();
    refreshed_state.dim_y = inspector_dim_y_->value();
    refreshed_state.dim_z = inspector_dim_z_->value();
  }
  if (!updated_display_name.isEmpty()) refreshed_state.display_name = updated_display_name;
  refreshed_state.role = updated_semantic_role;
  refreshed_state.category = target.state.category;
  refreshed_state.type = target.state.type;
  refreshed_state.role_or_category = updated_semantic_role.isEmpty() ? target.state.role_or_category : updated_semantic_role;
  refreshed_state.editable = true;
  refreshed_state.locked = false;
  refreshed_state.linked_to_editable_layout_state = true;
  selected_item_state_ = refreshed_state;

  const QString selected_scene_name_for_log = selected_scene_state_.valid ? selected_scene_state_.name : QStringLiteral("unknown");
  append_studio_log(QString("Inspector transform edited: scene=%1 id=%2 source=%3 xyz=[%4,%5,%6] rpy=[%7,%8,%9] dirty=true")
    .arg(selected_scene_name_for_log, item_id, target.source_path)
    .arg(applied_x, 0, 'g', 17)
    .arg(applied_y, 0, 'g', 17)
    .arg(applied_z, 0, 'g', 17)
    .arg(updated_roll, 0, 'g', 17)
    .arg(updated_pitch, 0, 'g', 17)
    .arg(updated_yaw, 0, 'g', 17));
  if (metadata_changed) {
    append_studio_log(QString("Inspector metadata edited: scene=%1 id=%2 display_name=%3 semantic_role=%4 dirty=true")
      .arg(selected_scene_name_for_log, item_id, updated_display_name, updated_semantic_role));
  }
  append_studio_log(QString("item updated: %1 source=%2 editable=true locked=false fallback_view_refreshed=%3")
    .arg(item_id, target.source_path, i ? QStringLiteral("true") : QStringLiteral("false")));
  for (auto & p : all_scene_preview_items_) {
    if (p.id != item_id) continue;
    p.x = refreshed_state.pose_x;
    p.y = refreshed_state.pose_y;
    p.z = refreshed_state.pose_z;
    p.roll = refreshed_state.roll;
    p.pitch = refreshed_state.pitch;
    p.yaw = refreshed_state.yaw;
    p.sx = refreshed_state.dim_x;
    p.sy = refreshed_state.dim_y;
    p.sz = refreshed_state.dim_z;
    if (!refreshed_state.display_name.isEmpty()) p.display_name = refreshed_state.display_name;
    p.role = refreshed_state.role;
    break;
  }
  ScenePreviewWidget::PreviewItem after_item = before_item;
  for (const auto & preview_item : all_scene_preview_items_) {
    if (preview_item.id.trimmed() == item_id) { after_item = preview_item; break; }
  }
  undo_stack_.push_back({"pose_edit", item_id, old, updated, false, false, {}, before_item, after_item});
  redo_stack_.clear();
  scene_preview_widget_->set_native_authoring_history_available(true, false);
  mark_layout_dirty(metadata_changed ? "Inspector Metadata/Transform Edit" : "Inspector Pose/Dimensions Edit");
  // Refresh the native authoring snapshot after applying the new values so
  // Save Layout serializes the Inspector result rather than the pre-edit
  // session snapshot.
  capture_active_editable_layout_session();
  for (auto & session_item : editable_layout_session_items_) {
    if (session_item.id.trimmed() != item_id) continue;
    session_item.x = refreshed_state.pose_x;
    session_item.y = refreshed_state.pose_y;
    session_item.z = refreshed_state.pose_z;
    session_item.roll = refreshed_state.roll;
    session_item.pitch = refreshed_state.pitch;
    session_item.yaw = refreshed_state.yaw;
    session_item.sx = refreshed_state.dim_x;
    session_item.sy = refreshed_state.dim_y;
    session_item.sz = refreshed_state.dim_z;
  }
  if (item_id == QStringLiteral("place_zone_default")) {
    bool found = false;
    for (const auto & session_item : editable_layout_session_items_)
      found = found || session_item.id.trimmed() == item_id;
    if (!found) {
      ScenePreviewWidget::PreviewItem session_item;
      session_item.id = item_id; session_item.category = "zone"; session_item.role = "place_zone";
      session_item.display_name = "Place Free Region"; session_item.source_path = "environment.yaml";
      session_item.x = refreshed_state.pose_x; session_item.y = refreshed_state.pose_y; session_item.z = refreshed_state.pose_z;
      session_item.roll = refreshed_state.roll; session_item.pitch = refreshed_state.pitch; session_item.yaw = refreshed_state.yaw;
      session_item.sx = refreshed_state.dim_x; session_item.sy = refreshed_state.dim_y; session_item.sz = refreshed_state.dim_z;
      session_item.source_layer = "editable_layout"; session_item.editable = true; session_item.locked = false;
      editable_layout_session_items_.push_back(session_item);
    }
  }
  if (metadata_changed) {
    refresh_scene_hierarchy_tree_from_current_items();
    if (scene_preview_widget_) {
      scene_preview_widget_->set_authoring_item_metadata(
        item_id, refreshed_state.display_name, refreshed_state.role);
    }
  }
  if (scene_preview_widget_ &&
      scene_preview_widget_->embedded_web_authoring_active()) {
    pending_native_web_pose_signatures_.insert(authored_pose_signature(
      item_id, refreshed_state.pose_x, refreshed_state.pose_y, refreshed_state.pose_z,
      refreshed_state.roll, refreshed_state.pitch, refreshed_state.yaw));
    scene_preview_widget_->set_authoring_item_pose(
      item_id,
      refreshed_state.pose_x,
      refreshed_state.pose_y,
      refreshed_state.pose_z,
      refreshed_state.roll,
      refreshed_state.pitch,
      refreshed_state.yaw);
  } else {
    apply_scene3d_preview_layer_filters(false);
  }

  refresh_selection_transform_editor_from_state(refreshed_state);
  refresh_selected_scene_item_labels(refreshed_state);
  refresh_selected_item_card();
  if (scene_preview_widget_) scene_preview_widget_->update();
}

void MainWindow::revert_selection_transform_editor()
{
  const auto state = current_selected_scene_item();
  if (!state.valid) return;
  if (auto * item = find_canvas_item_by_stable_id(state.id)) {
    refresh_selection_transform_editor_from_item(item);
  } else {
    refresh_selection_transform_editor_from_state(state);
  }
}

void MainWindow::copy_selection_transform_to_clipboard()
{
  const QString text = QString("x=%1 y=%2 z=%3 r=%4 p=%5 yaw=%6")
    .arg(inspector_x_->value(), 0, 'g', 17).arg(inspector_y_->value(), 0, 'g', 17).arg(inspector_z_->value(), 0, 'g', 17)
    .arg(inspector_roll_->value(), 0, 'g', 17).arg(inspector_pitch_->value(), 0, 'g', 17).arg(inspector_yaw_->value(), 0, 'g', 17);
  QApplication::clipboard()->setText(text);
}

void MainWindow::paste_selection_transform_from_clipboard()
{
  double x = 0.0, y = 0.0, z = 0.0, r = 0.0, p = 0.0, yaw = 0.0;
  QString error;
  if (!parse_transform_clipboard_text(QApplication::clipboard()->text(), &x, &y, &z, &r, &p, &yaw, &error)) {
    QMessageBox::warning(this, "Paste Transform", "Invalid transform text.\n" + error);
    return;
  }
  inspector_update_guard_ = true;
  inspector_x_->setValue(x); inspector_y_->setValue(y); inspector_z_->setValue(z);
  inspector_roll_->setValue(qRadiansToDegrees(r)); inspector_pitch_->setValue(qRadiansToDegrees(p)); inspector_yaw_->setValue(qRadiansToDegrees(yaw));
  inspector_update_guard_ = false;
  apply_selection_transform_from_editor();
}
void MainWindow::undo_layout_edit(){
  if (!ensure_live_authoring_mutation_available(QStringLiteral("Undo"))) return;
  if (undo_stack_.empty() && scene_preview_widget_ &&
      scene_preview_widget_->embedded_web_authoring_active()) {
    scene_preview_widget_->undo_authoring_edit();
    return;
  }
  if(undo_stack_.empty() || !digital_twin_scene_) return;
  auto c=undo_stack_.back(); undo_stack_.pop_back();
  const auto apply_snapshot = [this](const ScenePreviewWidget::PreviewItem & snapshot) {
    if (snapshot.id.trimmed().isEmpty()) return;
    for (auto & preview : all_scene_preview_items_) {
      if (preview.id.trimmed() == snapshot.id.trimmed()) { preview = snapshot; break; }
    }
    if (auto * canvas = find_canvas_item_by_stable_id(snapshot.id)) {
      canvas->setPos(snapshot.x * 100.0, snapshot.y * 100.0);
      canvas->setData(RolePoseZ, snapshot.z); canvas->setData(RoleRoll, snapshot.roll);
      canvas->setData(RolePitch, snapshot.pitch); canvas->setData(RoleYaw, snapshot.yaw);
      canvas->setData(RoleWidth, snapshot.sx); canvas->setData(RoleDepth, snapshot.sy); canvas->setData(RoleHeight, snapshot.sz);
      canvas->setData(RoleDisplayName, snapshot.display_name); canvas->setData(RoleRole, snapshot.role);
      canvas->setData(RoleMetadataExplicitlyEdited, true);
    }
    if (scene_preview_widget_ && scene_preview_widget_->embedded_web_authoring_active()) {
      pending_native_web_pose_signatures_.insert(authored_pose_signature(
        snapshot.id, snapshot.x, snapshot.y, snapshot.z,
        snapshot.roll, snapshot.pitch, snapshot.yaw));
      scene_preview_widget_->set_authoring_item_metadata(snapshot.id, snapshot.display_name, snapshot.role);
      scene_preview_widget_->set_authoring_item_pose(snapshot.id, snapshot.x, snapshot.y, snapshot.z,
        snapshot.roll, snapshot.pitch, snapshot.yaw);
    }
  };
  if (c.kind == QStringLiteral("mounting")) {
    apply_mounting_snapshot(c.preview_items);
  } else if (c.kind == QStringLiteral("delete")) {
    deleted_layout_item_ids_.remove(c.item_id);
    for (const auto & p : c.preview_items) {
      bool exists = false;
      for (const auto & existing : all_scene_preview_items_) if (existing.id == p.id) { exists = true; break; }
      if (!exists) all_scene_preview_items_.push_back(p);
    }
    if (scene_preview_widget_ && scene_preview_widget_->embedded_web_authoring_active() &&
        !c.preview_items.isEmpty()) {
      scene_preview_widget_->add_authoring_item(c.preview_items.front());
      scene_preview_widget_->select_preview_item(c.item_id);
    } else {
      apply_scene3d_preview_layer_filters(false);
    }
    current_selected_scene_item_id_ = c.item_id;
    selected_item_state_ = current_selected_scene_item();
    refresh_selected_scene_item_labels(selected_item_state_);
    append_studio_log(QString("Restored %1").arg(selected_item_state_.display_name.isEmpty() ? c.item_id : selected_item_state_.display_name));
  } else if (c.kind == QStringLiteral("duplicate") || c.kind == QStringLiteral("add")) {
    for (int i = all_scene_preview_items_.size() - 1; i >= 0; --i) if (all_scene_preview_items_[i].id == c.item_id) all_scene_preview_items_.removeAt(i);
    remove_session_item(editable_layout_session_items_, c.item_id);
    for (auto * item : digital_twin_scene_->items()) if (item->data(RoleId).toString() == c.item_id) { delete item; break; }
    current_selected_scene_item_id_.clear(); selected_item_state_ = {};
    if (scene_preview_widget_ && scene_preview_widget_->embedded_web_authoring_active())
      scene_preview_widget_->remove_authoring_item(c.item_id);
    else apply_scene3d_preview_layer_filters(false);
    refresh_selected_scene_item_labels(selected_item_state_);
    if (!c.preview_items.isEmpty()) {
      append_studio_log(c.kind == QStringLiteral("duplicate")
        ? QString("Removed duplicate %1").arg(c.preview_items.front().display_name)
        : QString("Removed %1").arg(c.preview_items.front().display_name));
    }
  } else if (!c.before_item.id.trimmed().isEmpty()) {
    apply_snapshot(c.before_item);
  } else {
    for(auto *i:digital_twin_scene_->items()) if(i->data(RoleId).toString()==c.item_id){ i->setPos(c.old_pos); break;}
  }
  redo_stack_.push_back(c);
  scene_preview_widget_->set_native_authoring_history_available(!undo_stack_.empty(), true);
  mark_layout_dirty("Undo"); refresh_scene_hierarchy_tree_from_current_items(); refresh_minimap_card(); refresh_delete_selected_action(); refresh_duplicate_selected_action();
}
void MainWindow::redo_layout_edit(){
  if (!ensure_live_authoring_mutation_available(QStringLiteral("Redo"))) return;
  if (redo_stack_.empty() && scene_preview_widget_ &&
      scene_preview_widget_->embedded_web_authoring_active()) {
    scene_preview_widget_->redo_authoring_edit();
    return;
  }
  if(redo_stack_.empty() || !digital_twin_scene_) return;
  auto c=redo_stack_.back(); redo_stack_.pop_back();
  const auto apply_snapshot = [this](const ScenePreviewWidget::PreviewItem & snapshot) {
    if (snapshot.id.trimmed().isEmpty()) return;
    for (auto & preview : all_scene_preview_items_) {
      if (preview.id.trimmed() == snapshot.id.trimmed()) { preview = snapshot; break; }
    }
    if (auto * canvas = find_canvas_item_by_stable_id(snapshot.id)) {
      canvas->setPos(snapshot.x * 100.0, snapshot.y * 100.0);
      canvas->setData(RolePoseZ, snapshot.z); canvas->setData(RoleRoll, snapshot.roll);
      canvas->setData(RolePitch, snapshot.pitch); canvas->setData(RoleYaw, snapshot.yaw);
      canvas->setData(RoleWidth, snapshot.sx); canvas->setData(RoleDepth, snapshot.sy); canvas->setData(RoleHeight, snapshot.sz);
      canvas->setData(RoleDisplayName, snapshot.display_name); canvas->setData(RoleRole, snapshot.role);
      canvas->setData(RoleMetadataExplicitlyEdited, true);
    }
    if (scene_preview_widget_ && scene_preview_widget_->embedded_web_authoring_active()) {
      pending_native_web_pose_signatures_.insert(authored_pose_signature(
        snapshot.id, snapshot.x, snapshot.y, snapshot.z,
        snapshot.roll, snapshot.pitch, snapshot.yaw));
      scene_preview_widget_->set_authoring_item_metadata(snapshot.id, snapshot.display_name, snapshot.role);
      scene_preview_widget_->set_authoring_item_pose(snapshot.id, snapshot.x, snapshot.y, snapshot.z,
        snapshot.roll, snapshot.pitch, snapshot.yaw);
    }
  };
  if (c.kind == QStringLiteral("mounting")) {
    apply_mounting_snapshot(c.after_items);
  } else if (c.kind == QStringLiteral("delete")) {
    deleted_layout_item_ids_.insert(c.item_id);
    for (int i = all_scene_preview_items_.size() - 1; i >= 0; --i) if (all_scene_preview_items_[i].id == c.item_id) all_scene_preview_items_.removeAt(i);
    if (digital_twin_scene_) for (auto * item : digital_twin_scene_->items()) if (item->data(RoleId).toString() == c.item_id) { delete item; break; }
    current_selected_scene_item_id_.clear(); selected_item_state_ = {};
    if (scene_preview_widget_ && scene_preview_widget_->embedded_web_authoring_active())
      scene_preview_widget_->remove_authoring_item(c.item_id);
    else apply_scene3d_preview_layer_filters(false);
    refresh_selected_scene_item_labels(selected_item_state_);
  } else if ((c.kind == QStringLiteral("duplicate") || c.kind == QStringLiteral("add")) && !c.preview_items.isEmpty()) {
    const auto p = c.preview_items.front();
    bool exists = false;
    for (const auto & existing : all_scene_preview_items_) if (existing.id == p.id) { exists = true; break; }
    if (!exists) all_scene_preview_items_.push_back(p);
    upsert_session_item(editable_layout_session_items_, p);
    if (!find_canvas_item_by_stable_id(p.id)) {
      auto * item = new DraggableCanvasItem(QRectF(0, 0, qMax(10.0, p.sx * 35.0), qMax(10.0, p.sy * 35.0)));
      item->setPos(p.x * 100.0, p.y * 100.0);
      item->setData(RoleId, p.id); item->setData(RoleDisplayName, p.display_name); item->setData(RoleCategory, p.category); item->setData(RoleRole, p.role);
      item->setData(RoleSource, p.source_path); item->setData(RoleSourcePackage, QStringLiteral("asset_folder")); item->setData(RoleSourceLayer, QStringLiteral("editable_layout")); item->setData(RoleLocked, false);
      item->setData(RolePoseZ, p.z); item->setData(RoleRoll, p.roll); item->setData(RolePitch, p.pitch); item->setData(RoleYaw, p.yaw);
      item->setData(RoleWidth, p.sx); item->setData(RoleDepth, p.sy); item->setData(RoleHeight, p.sz);
      item->setData(RoleCatalogAssetId, p.catalog_asset_id); item->setData(RoleGeometryType, p.primitive_geometry_type);
      item->setFlags(QGraphicsItem::ItemIsSelectable | QGraphicsItem::ItemSendsGeometryChanges | QGraphicsItem::ItemIsMovable);
      item->position_filter = [this](const QPointF & pos){ return snap_canvas_position(pos); };
      digital_twin_scene_->addItem(item);
    }
    if (scene_preview_widget_ && scene_preview_widget_->embedded_web_authoring_active())
      scene_preview_widget_->add_authoring_item(p);
    else apply_scene3d_preview_layer_filters(false);
    apply_scene_selection(p.id, p.role, false, false);
  } else if (!c.after_item.id.trimmed().isEmpty()) {
    apply_snapshot(c.after_item);
  } else {
    for(auto *i:digital_twin_scene_->items()) if(i->data(RoleId).toString()==c.item_id){ i->setPos(c.new_pos); break;}
  }
  undo_stack_.push_back(c);
  scene_preview_widget_->set_native_authoring_history_available(true, !redo_stack_.empty());
  mark_layout_dirty("Redo"); refresh_scene_hierarchy_tree_from_current_items(); refresh_minimap_card(); refresh_delete_selected_action(); refresh_duplicate_selected_action();
}
bool MainWindow::selected_item_can_be_duplicated() const
{
  if (!selected_scene_state_.valid || place_asset_armed_) return false;
  if (scene_preview_widget_ && !scene_preview_widget_->embedded_web_authoring_active()) return false;
  return resolve_selected_editable_layout_target().ok;
}

void MainWindow::refresh_duplicate_selected_action()
{
  const bool can_duplicate = selection_set_.size() < 2 && selected_item_can_be_duplicated();
  if (auto * action = scene_builder_action(QStringLiteral("layout.duplicate"))) action->setEnabled(can_duplicate);
  if (scene_duplicate_context_button_) {
    scene_duplicate_context_button_->setVisible(true);
    scene_duplicate_context_button_->setEnabled(can_duplicate);
  }
}

void MainWindow::duplicate_selected_item()
{
  if (selection_set_.size() >= 2) {
    const QString message = QStringLiteral("%1 parts are selected. Duplicate copies one part at a time: select only the "
      "part to copy.").arg(selection_set_.size());
    append_studio_log(QStringLiteral("Duplicate refused: %1").arg(message));
    statusBar()->showMessage(message, 6000);
    return;
  }
  const auto target = resolve_selected_editable_layout_target();
  if (!target.ok || place_asset_armed_) {
    append_studio_log("Selected item cannot be duplicated");
    statusBar()->showMessage("Selected item cannot be duplicated", 4000);
    refresh_duplicate_selected_action();
    return;
  }
  if (!ensure_live_authoring_mutation_available(QStringLiteral("Duplicate"))) return;

  ScenePreviewWidget::PreviewItem copy;
  bool found_preview = false;
  for (const auto & p : all_scene_preview_items_) {
    if (p.id.trimmed() == target.state.id.trimmed()) { copy = p; found_preview = true; break; }
  }
  if (!found_preview) {
    append_studio_log(QString("Selected item cannot be duplicated: no authored-object record for %1").arg(target.state.id));
    statusBar()->showMessage("Selected item cannot be duplicated", 4000);
    return;
  }

  std::set<std::string> reserved_ids;
  QSet<QString> reserved_names;
  for (const auto & p : all_scene_preview_items_) {
    const QString id = p.id.trimmed();
    if (!id.isEmpty()) reserved_ids.insert(id.toStdString());
    if (!p.display_name.trimmed().isEmpty()) reserved_names.insert(p.display_name.trimmed().toLower());
  }
  auto normalize_id = [](QString text) {
    text = text.trimmed().toLower();
    QString out;
    for (const QChar ch : text) out += (ch.isLetterOrNumber() ? ch : QChar('_'));
    while (out.contains("__")) out.replace("__", "_");
    out = out.trimmed();
    while (out.startsWith('_')) out.remove(0, 1);
    while (out.endsWith('_')) out.chop(1);
    if (out.isEmpty() || !out.front().isLetter()) out.prepend("object_");
    return out.left(58);
  };
  QString base_id = normalize_id(target.state.id);
  if (base_id.endsWith("_copy")) base_id.chop(5);
  const QString copy_base = base_id + QStringLiteral("_copy");
  QString new_id = copy_base;
  for (int n = 2; reserved_ids.count(new_id.toStdString()) > 0 && n < 1000; ++n) new_id = QStringLiteral("%1_%2").arg(copy_base).arg(n);
  if (!workcell_builder::workcell_studio_is_valid_id(new_id.toStdString()) || reserved_ids.count(new_id.toStdString()) > 0) {
    append_studio_log(QString("Selected item cannot be duplicated: failed to generate a valid unique id from %1").arg(target.state.id));
    statusBar()->showMessage("Selected item cannot be duplicated", 4000);
    return;
  }

  QString base_name = target.state.display_name.trimmed().isEmpty() ? target.state.id.trimmed() : target.state.display_name.trimmed();
  QRegularExpression copy_suffix(QStringLiteral("\\s+copy(?:\\s+\\d+)?$"), QRegularExpression::CaseInsensitiveOption);
  base_name.replace(copy_suffix, QString());
  QString new_name = base_name + QStringLiteral(" copy");
  for (int n = 2; reserved_names.contains(new_name.toLower()) && n < 1000; ++n) new_name = QStringLiteral("%1 copy %2").arg(base_name).arg(n);

  copy.id = new_id;
  copy.display_name = new_name;
  if (!copy.mounting_yaml.isEmpty()) {
    auto metadata = YAML::Load(copy.mounting_yaml.toStdString());
    for (const char * key : {"parent_object", "parent_link", "joint_type", "origin", "mate"}) metadata.remove(key);
    YAML::Emitter emitter; emitter << metadata; copy.mounting_yaml = QString::fromUtf8(emitter.c_str());
  }
  copy.x += 0.10;
  copy.y += 0.10;
  copy.editable = true;
  copy.locked = false;
  copy.linked_to_editable_layout_state = true;
  copy.source_layer = QStringLiteral("editable_layout");
  copy.selectable = true;
  copy.status = QStringLiteral("ready");

  auto * item = new DraggableCanvasItem(QRectF(0, 0, qMax(10.0, copy.sx * 35.0), qMax(10.0, copy.sy * 35.0)));
  item->setPos(copy.x * 100.0, copy.y * 100.0);
  item->setData(RoleMountingYaml, copy.mounting_yaml);
  item->setData(RoleId, copy.id); item->setData(RoleDisplayName, copy.display_name);
  item->setData(RoleType, target.state.type); item->setData(RoleCategory, copy.category); item->setData(RoleRole, copy.role);
  item->setData(RoleSource, copy.source_path); item->setData(RoleSourcePackage, QStringLiteral("asset_folder"));
  item->setData(RoleGeometryType, copy.primitive_geometry_type);
  item->setData(RolePoseZ, copy.z); item->setData(RoleRoll, copy.roll); item->setData(RolePitch, copy.pitch); item->setData(RoleYaw, copy.yaw);
  item->setData(RoleWidth, copy.sx); item->setData(RoleDepth, copy.sy); item->setData(RoleHeight, copy.sz);
  item->setData(RoleCatalogAssetId, copy.catalog_asset_id);
  item->setData(RoleMeshScaleX, copy.mesh_scale_x); item->setData(RoleMeshScaleY, copy.mesh_scale_y); item->setData(RoleMeshScaleZ, copy.mesh_scale_z);
  item->setData(RoleImported, copy.mesh_type.compare(QStringLiteral("stl"), Qt::CaseInsensitive) == 0);
  item->setData(RoleGeneratedPlaceholder, false); item->setData(RoleSourceLayer, QStringLiteral("editable_layout")); item->setData(RoleLocked, false);
  item->setFlags(QGraphicsItem::ItemIsSelectable | QGraphicsItem::ItemSendsGeometryChanges | QGraphicsItem::ItemIsMovable);
  item->position_filter = [this](const QPointF & p){ return snap_canvas_position(p); };
  digital_twin_scene_->addItem(item);
  all_scene_preview_items_.push_back(copy);
  CanvasEditCommand command{
    "duplicate", new_id,
    QPointF(copy.x * 100.0, copy.y * 100.0),
    QPointF(copy.x * 100.0, copy.y * 100.0),
    true, false, {copy}};
  undo_stack_.push_back(command); redo_stack_.clear();
  scene_preview_widget_->set_native_authoring_history_available(true, false);
  if (scene_preview_widget_ && scene_preview_widget_->embedded_web_authoring_active()) {
    scene_preview_widget_->duplicate_authoring_item(target.state.id, copy);
  } else {
    apply_scene3d_preview_layer_filters(false);
  }
  upsert_session_item(editable_layout_session_items_, copy);
  apply_scene_selection(new_id, copy.role, false, false);
  refresh_scene_hierarchy_tree_from_current_items();
  refresh_minimap_card();
  mark_layout_dirty("Duplicate Selected");
  append_studio_log(QString("Duplicated %1 as %2").arg(base_name, new_name));
  refresh_duplicate_selected_action(); refresh_delete_selected_action();
}
bool MainWindow::selected_item_can_be_deleted() const
{
  if (!selected_scene_state_.valid || place_asset_armed_) return false;
  if (scene_preview_widget_ && !scene_preview_widget_->embedded_web_authoring_active()) return false;
  return resolve_selected_editable_layout_target().ok;
}

void MainWindow::refresh_delete_selected_action()
{
  if (auto * action = scene_builder_action(QStringLiteral("layout.remove"))) {
    const bool multi = selection_set_.size() >= 2;
    action->setEnabled(!multi && selected_item_can_be_deleted());
    action->setToolTip(multi ? QStringLiteral("Delete removes one part at a time; %1 parts are selected.").arg(selection_set_.size())
                             : QStringLiteral("Delete the selected part (undoable)."));
  }
}

void MainWindow::delete_selected_item(){
  if (selection_set_.size() >= 2) {
    const QString message = QStringLiteral("%1 parts are selected. Delete removes one part at a time: click the part to "
      "delete (or Ctrl+click to leave only it selected), then Delete.").arg(selection_set_.size());
    append_studio_log(QStringLiteral("Delete refused: %1").arg(message));
    statusBar()->showMessage(message, 6000);
    return;
  }
  const auto target = resolve_selected_editable_layout_target();
  if(!target.ok || place_asset_armed_) {
    append_studio_log("Selected item cannot be deleted");
    statusBar()->showMessage("Selected item cannot be deleted", 4000);
    refresh_delete_selected_action();
    return;
  }
  if (!ensure_live_authoring_mutation_available(QStringLiteral("Delete"))) return;
  const QString id = target.state.id.trimmed();
  for (const auto & p : all_scene_preview_items_) {
    const auto meta = YAML::Load(p.mounting_yaml.toStdString());
    if (meta && meta["parent_object"] && meta["parent_object"].as<std::string>() == id.toStdString()) {
      QMessageBox::warning(this, "Remove asset", "Detach or reparent the mounted children before removing their parent.");
      return;
    }
  }
  QVector<ScenePreviewWidget::PreviewItem> deleted_preview_items;
  for (const auto & p : all_scene_preview_items_) if (p.id == id) deleted_preview_items.push_back(p);
  if (deleted_preview_items.isEmpty()) {
    append_studio_log("Selected item cannot be deleted");
    statusBar()->showMessage("Selected item cannot be deleted", 4000);
    refresh_delete_selected_action();
    return;
  }
  const QPointF item_position = target.fallback_item ? target.fallback_item->pos() : QPointF();
  CanvasEditCommand command{
    "delete", id, item_position, item_position, false, true, deleted_preview_items};
  deleted_layout_item_ids_.insert(id);
  for (int i = all_scene_preview_items_.size() - 1; i >= 0; --i) if (all_scene_preview_items_[i].id == id) all_scene_preview_items_.removeAt(i);
  if (target.fallback_item) delete target.fallback_item;
  if (digital_twin_scene_) digital_twin_scene_->clearSelection();
  if (scene_hierarchy_tree_) scene_hierarchy_tree_->clearSelection();
  current_selected_scene_item_id_.clear(); selected_item_state_ = {};
  undo_stack_.push_back(command); redo_stack_.clear();
  scene_preview_widget_->set_native_authoring_history_available(true, false);
  if (scene_preview_widget_ && scene_preview_widget_->embedded_web_authoring_active())
    scene_preview_widget_->remove_authoring_item(id);
  else apply_scene3d_preview_layer_filters(false);
  refresh_scene_hierarchy_tree_from_current_items();
  refresh_selected_scene_item_labels(selected_item_state_);
  refresh_minimap_card();
  mark_layout_dirty("Delete Selected");
  append_studio_log(QString("Deleted %1").arg(target.state.display_name.isEmpty() ? id : target.state.display_name));
  refresh_delete_selected_action();
  refresh_duplicate_selected_action();
}

double MainWindow::current_nudge_step_m(Qt::KeyboardModifiers modifiers) const
{
  double step = (snap_to_grid_box_ && snap_to_grid_box_->isChecked()) ? snap_step_m_ : 0.01;
  if (modifiers & Qt::ShiftModifier) step *= 5.0;
  if (modifiers & Qt::ControlModifier) step *= 0.2;
  return std::max(0.001, step);
}

void MainWindow::rebuild_canvas_inspector()
{
  if (!digital_twin_scene_ || selection_update_guard_) return;
  if (digital_twin_scene_->selectedItems().isEmpty()) {
    refresh_selected_scene_item_labels(current_selected_scene_item());
    return;
  }

  auto * item = digital_twin_scene_->selectedItems().front();
  if (!item) {
    refresh_selected_scene_item_labels(current_selected_scene_item());
    return;
  }

  select_canvas_item(item);
  if (scene_preview_widget_) scene_preview_widget_->select_preview_item(item->data(RoleId).toString().trimmed());
}

void MainWindow::keyPressEvent(QKeyEvent * event)
{
  if (!digital_twin_scene_ || digital_twin_scene_->selectedItems().isEmpty()) { QMainWindow::keyPressEvent(event); return; }
  if (selection_set_.size() >= 2) {
    // Arrow keys would move only the reference: multi-part moves use the arrangement toolbar (Move / rotate…).
    statusBar()->showMessage(QStringLiteral("Several parts are selected: use Move / rotate… on the arrangement toolbar."), 4000);
    QMainWindow::keyPressEvent(event);
    return;
  }
  auto * item = digital_twin_scene_->selectedItems().front();
  if (!item || item->data(RoleLocked).toBool()) { QMainWindow::keyPressEvent(event); return; }
  const double step_m = current_nudge_step_m(event->modifiers());
  const double step_px = step_m * 100.0;
  QPointF delta; double dz = 0.0;
  switch (event->key()) {
    case Qt::Key_Left: delta.rx() -= step_px; break;
    case Qt::Key_Right: delta.rx() += step_px; break;
    case Qt::Key_Up: delta.ry() -= step_px; break;
    case Qt::Key_Down: delta.ry() += step_px; break;
    case Qt::Key_PageUp: dz += step_m; break;
    case Qt::Key_PageDown: dz -= step_m; break;
    default: QMainWindow::keyPressEvent(event); return;
  }
  const QPointF old_pos = item->pos();
  bool mounted_graph = false;
  for (const auto & p : all_scene_preview_items_) mounted_graph = mounted_graph || p.mounting_yaml.contains("parent_object");
  if (mounted_graph) {
    const auto updated = snap_canvas_position(old_pos + delta);
    commit_mounting_request({{"id", item->data(RoleId).toString()}, {"world_pose", QJsonObject{
      {"xyz", QJsonArray{updated.x()/100., updated.y()/100., item->data(RolePoseZ).toDouble()+dz}},
      {"rpy", QJsonArray{item->data(RoleRoll).toDouble(), item->data(RolePitch).toDouble(), item->data(RoleYaw).toDouble()}}}}});
    event->accept(); return;
  }
  item->setPos(snap_canvas_position(old_pos + delta));
  item->setData(RolePoseZ, item->data(RolePoseZ).toDouble() + dz);
  if (snap_step_label_) snap_step_label_->setText(QString("Nudge step: %1 m").arg(step_m, 0, 'f', 3));
  undo_stack_.push_back({"nudge", item->data(RoleId).toString(), old_pos, item->pos(), false, false, {}});
  redo_stack_.clear();
  scene_preview_widget_->set_native_authoring_history_available(true, false);
  mark_layout_dirty("Nudge Move");
  rebuild_canvas_inspector();
  event->accept();
}


void MainWindow::add_asset_to_canvas_from_catalog(const QString & category, const QString & display_name, const QString & source_path)
{
  armed_asset_category_ = category;
  armed_asset_display_name_ = display_name;
  armed_asset_source_path_ = source_path;
  reset_armed_asset_transform_to_defaults();
  armed_asset_use_clicked_xy_ = true;
  // Compatibility-only placeholder path. Catalog-backed placement always arms by asset_id.
  place_asset_armed_ = true;
  armed_asset_id_.clear();
  armed_asset_default_xy_px_ = compute_default_canvas_pose(category, display_name);
  set_canvas_interaction_mode(CanvasInteractionMode::Place);
}

QPointF MainWindow::compute_default_canvas_pose(const QString & category, const QString & display_name) const
{
  auto anchor_pos = [this](const QString & needle)->QPointF {
      if (!digital_twin_scene_) return QPointF(0.0, 0.0);
      for (auto * gi : digital_twin_scene_->items()) {
        const QString tag = gi->data(RoleCategory).toString().toLower() + "|" + gi->data(RoleRole).toString().toLower() + "|" + gi->data(RoleId).toString().toLower();
        if (tag.contains(needle)) return gi->pos();
      }
      return QPointF(0.0, 0.0);
    };
  const QString lower = (category + " " + display_name).toLower();
  const QPointF table = anchor_pos("table");
  const QPointF conveyor = anchor_pos("conveyor");
  const QPointF pick = anchor_pos("pick");
  const QPointF place = anchor_pos("place");
  if (lower.contains("table")) return table;
  if (lower.contains("conveyor")) return table + QPointF(-120.0, 25.0);
  if (lower.contains("bin") || lower.contains("place target") || lower.contains("place_target")) return table + QPointF(95.0, -20.0);
  if (lower.contains("pick zone") || lower.contains("pick_zone")) return (conveyor != QPointF(0.0, 0.0)) ? conveyor + QPointF(65.0, -10.0) : table + QPointF(-40.0, 10.0);
  if (lower.contains("place zone") || lower.contains("place_zone")) return (place != QPointF(0.0, 0.0)) ? place + QPointF(30.0, 0.0) : table + QPointF(115.0, 15.0);
  if (lower.contains("camera")) return table + QPointF(-20.0, -135.0);
  if (lower.contains("object")) return (pick != QPointF(0.0, 0.0)) ? pick + QPointF(10.0, 10.0) : table + QPointF(-20.0, 10.0);
  return default_xy_for_category(category);
}

double MainWindow::default_asset_pose_z(const QString & category, const QString & display_name) const
{
  const QString lower = (category + " " + display_name).toLower();
  return lower.contains("camera") ? 1.2 : 0.0;
}

void MainWindow::clear_armed_asset_placement()
{
  place_asset_armed_ = false;
  armed_asset_id_.clear();
  armed_asset_category_.clear();
  armed_asset_display_name_.clear();
  armed_asset_source_path_.clear();
  armed_asset_use_clicked_xy_ = true;
  armed_asset_default_xy_px_ = QPointF(0.0, 0.0);
  armed_asset_transform_valid_ = true;
  armed_asset_transform_error_.clear();
  armed_asset_x_m_ = 0.0;
  armed_asset_y_m_ = 0.0;
  armed_asset_z_m_ = 0.0;
  armed_asset_roll_rad_ = 0.0;
  armed_asset_pitch_rad_ = 0.0;
  armed_asset_yaw_rad_ = 0.0;
  if (scene_preview_widget_) scene_preview_widget_->cancel_embedded_asset_placement();
}

void MainWindow::reset_armed_asset_transform_to_defaults()
{
  armed_asset_default_xy_px_ = compute_default_canvas_pose(armed_asset_category_, armed_asset_display_name_);
  armed_asset_x_m_ = armed_asset_default_xy_px_.x() / 100.0;
  armed_asset_y_m_ = armed_asset_default_xy_px_.y() / 100.0;
  armed_asset_z_m_ = default_asset_pose_z(armed_asset_category_, armed_asset_display_name_);
  armed_asset_roll_rad_ = 0.0;
  armed_asset_pitch_rad_ = 0.0;
  armed_asset_yaw_rad_ = 0.0;
}

bool MainWindow::validate_armed_asset_transform(QString * error_message)
{
  if (!std::isfinite(armed_asset_x_m_) || !std::isfinite(armed_asset_y_m_) || !std::isfinite(armed_asset_z_m_) ||
    !std::isfinite(armed_asset_roll_rad_) || !std::isfinite(armed_asset_pitch_rad_) || !std::isfinite(armed_asset_yaw_rad_))
  {
    if (error_message) *error_message = "All transform values must be numeric (x,y,z,roll,pitch,yaw).";
    return false;
  }
  if (error_message) error_message->clear();
  return true;
}

void MainWindow::update_arm_transform_validation_ui() {}

bool MainWindow::place_catalog_asset_at_world_position(
  const QString & requested_asset_id, double world_x_m, double world_y_m, double world_z_m,
  bool configure_transform)
{
  const QString asset_id = requested_asset_id.trimmed();
  if (asset_id.isEmpty()) {
    append_studio_log(QStringLiteral("Cannot place asset: empty catalog asset_id."));
    return false;
  }
  if (!std::isfinite(world_x_m) || !std::isfinite(world_y_m) || !std::isfinite(world_z_m)) {
    append_studio_log(QStringLiteral("Cannot place asset '%1': authored world position is not finite.").arg(asset_id));
    return false;
  }
  const auto match = std::find_if(asset_catalog_entries_.cbegin(), asset_catalog_entries_.cend(),
    [&asset_id](const AssetCatalogEntry & entry) { return entry.asset_id == asset_id; });
  if (match == asset_catalog_entries_.cend()) {
    append_studio_log(QStringLiteral("Cannot place asset '%1': stale catalog identity is no longer available.").arg(asset_id));
    return false;
  }
  if (!match->disabled_reason.trimmed().isEmpty() || !match->editable) {
    const QString reason = !match->disabled_reason.trimmed().isEmpty()
      ? match->disabled_reason.trimmed() : QStringLiteral("catalog entry is non-editable");
    append_studio_log(QStringLiteral("Cannot place asset '%1': %2").arg(asset_id, reason));
    return false;
  }

  if (!arm_place_asset_mode(asset_id)) return false;
  reset_armed_asset_transform_to_defaults();
  armed_asset_use_clicked_xy_ = true;
  armed_asset_x_m_ = world_x_m;
  armed_asset_y_m_ = world_y_m;
  armed_asset_z_m_ = world_z_m;
  if (configure_transform &&
      !configure_asset_placement_transform(match->category, match->display_name)) return false;
  // The dialog initializes defaults; a clicked request still owns XYZ unless
  // the operator explicitly chose configured coordinates.
  if (!configure_transform) {
    armed_asset_x_m_ = world_x_m;
    armed_asset_y_m_ = world_y_m;
    armed_asset_z_m_ = world_z_m;
  }
  const int item_count_before = digital_twin_scene_ ? digital_twin_scene_->items().size() : 0;
  commit_armed_asset_placement(QPointF(world_x_m * 100.0, world_y_m * 100.0));
  const bool committed = digital_twin_scene_ && digital_twin_scene_->items().size() == item_count_before + 1;
  if (committed) refresh_scene_builder_left_explorer();
  return committed;
}

bool MainWindow::configure_asset_placement_transform(const QString & category, const QString & display_name)
{
  armed_asset_category_ = category;
  armed_asset_display_name_ = display_name;
  reset_armed_asset_transform_to_defaults();
  QDialog dialog(this);
  dialog.setWindowTitle("Place Asset Transform");
  auto * layout = new QVBoxLayout(&dialog);
  auto * help = new QLabel("Enter placement transform before placing. XYZ in metres, RPY in radians.", &dialog);
  help->setWordWrap(true);
  layout->addWidget(help);
  auto * grid = new QGridLayout();
  auto mk = [&](const QString & label, double value, const QString & units, int row) {
      auto * l = new QLabel(label, &dialog);
      auto * e = new QLineEdit(QString::number(value, 'f', 3), &dialog);
      auto * u = new QLabel(units, &dialog);
      grid->addWidget(l, row, 0);
      grid->addWidget(e, row, 1);
      grid->addWidget(u, row, 2);
      return e;
    };
  QLineEdit * x_edit = mk("X", armed_asset_x_m_, "m", 0);
  QLineEdit * y_edit = mk("Y", armed_asset_y_m_, "m", 1);
  QLineEdit * z_edit = mk("Z", armed_asset_z_m_, "m", 2);
  QLineEdit * r_edit = mk("Roll", armed_asset_roll_rad_, "rad", 3);
  QLineEdit * p_edit = mk("Pitch", armed_asset_pitch_rad_, "rad", 4);
  QLineEdit * yaw_edit = mk("Yaw", armed_asset_yaw_rad_, "rad", 5);
  layout->addLayout(grid);
  auto * use_clicked = new QCheckBox("Use clicked position for XY", &dialog);
  use_clicked->setChecked(true);
  layout->addWidget(use_clicked);
  auto * error_label = new QLabel(&dialog);
  error_label->setStyleSheet("color:#b00020;");
  layout->addWidget(error_label);
  auto * buttons = new QDialogButtonBox(QDialogButtonBox::Ok | QDialogButtonBox::Cancel, &dialog);
  auto * defaults_btn = buttons->addButton("Use defaults", QDialogButtonBox::ResetRole);
  layout->addWidget(buttons);
  QObject::connect(defaults_btn, &QPushButton::clicked, &dialog, [&]() {
    reset_armed_asset_transform_to_defaults();
    x_edit->setText(QString::number(armed_asset_x_m_, 'f', 3));
    y_edit->setText(QString::number(armed_asset_y_m_, 'f', 3));
    z_edit->setText(QString::number(armed_asset_z_m_, 'f', 3));
    r_edit->setText(QString::number(armed_asset_roll_rad_, 'f', 3));
    p_edit->setText(QString::number(armed_asset_pitch_rad_, 'f', 3));
    yaw_edit->setText(QString::number(armed_asset_yaw_rad_, 'f', 3));
    error_label->clear();
  });
  QObject::connect(buttons, &QDialogButtonBox::accepted, &dialog, [&]() {
    bool okx, oky, okz, okr, okp, okyaw;
    const double x = x_edit->text().trimmed().toDouble(&okx);
    const double y = y_edit->text().trimmed().toDouble(&oky);
    const double z = z_edit->text().trimmed().toDouble(&okz);
    const double r = r_edit->text().trimmed().toDouble(&okr);
    const double p = p_edit->text().trimmed().toDouble(&okp);
    const double yw = yaw_edit->text().trimmed().toDouble(&okyaw);
    const bool ok = okx && oky && okz && okr && okp && okyaw;
    for (auto * edit : {x_edit, y_edit, z_edit, r_edit, p_edit, yaw_edit}) edit->setStyleSheet(ok ? "" : "border:1px solid #b00020;");
    if (!ok) { error_label->setText("Invalid transform: enter numeric x,y,z,roll,pitch,yaw values."); return; }
    armed_asset_x_m_ = x; armed_asset_y_m_ = y; armed_asset_z_m_ = z; armed_asset_roll_rad_ = r; armed_asset_pitch_rad_ = p; armed_asset_yaw_rad_ = yw;
    armed_asset_use_clicked_xy_ = use_clicked->isChecked();
    dialog.accept();
  });
  QObject::connect(buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);
  return dialog.exec() == QDialog::Accepted;
}

bool MainWindow::arm_place_asset_mode(const QString & requested_asset_id)
{
  const QString asset_id = requested_asset_id.trimmed();
  const auto match = std::find_if(asset_catalog_entries_.cbegin(), asset_catalog_entries_.cend(),
    [&asset_id](const AssetCatalogEntry & entry) { return entry.asset_id == asset_id; });
  if (asset_id.isEmpty() || match == asset_catalog_entries_.cend()) {
    append_studio_log(QStringLiteral("Cannot arm asset placement: catalog asset_id '%1' is unavailable.").arg(asset_id));
    return false;
  }
  if (!digital_twin_scene_) { rebuild_digital_twin_canvas(); }
  if (!digital_twin_scene_) return false;
  place_asset_armed_ = true;
  armed_asset_id_ = match->asset_id;
  armed_asset_category_ = match->category;
  armed_asset_display_name_ = match->display_name;
  armed_asset_source_path_ = match->source_path;
  armed_asset_scale_ = match->scale;
  reset_armed_asset_transform_to_defaults();
  armed_asset_use_clicked_xy_ = true;
  set_canvas_interaction_mode(CanvasInteractionMode::Place);
  if (scene_preview_widget_ &&
      scene_preview_widget_->active_product_view_backend() == ScenePreviewWidget::ProductViewBackend::EmbeddedWeb3D) {
    // A URDF primitive is drawn as its real-size solid, so a click places it on a surface.
    QJsonObject primitive_geometry;
    if (const auto primitive = first_urdf_visual_primitive(match->source_path)) {
      primitive_geometry.insert(QStringLiteral("geometry_type"), primitive->type);
      const QJsonArray size{primitive->sx, primitive->sy, primitive->sz};
      if (primitive->type == QStringLiteral("box"))
        primitive_geometry.insert(QStringLiteral("dimensions"), size);
      else
        primitive_geometry.insert(QStringLiteral("primitive"), QJsonObject{
          {QStringLiteral("radius"), primitive->radius}, {QStringLiteral("length"), primitive->length},
          {QStringLiteral("dimensions"), size}});
    }
    scene_preview_widget_->arm_embedded_asset_placement(
      match->asset_id, match->source_path, match->scale,
      place_mode_persistent_box_ && place_mode_persistent_box_->isChecked(), primitive_geometry);
  }
  append_studio_log(QString("Place Asset Mode armed: %1 (%2) asset_id=%3. Click canvas to commit. Use clicked XY: %4 | xyzrpy=[%5, %6, %7, %8, %9, %10].")
    .arg(match->display_name, match->category, armed_asset_id_)
    .arg(armed_asset_use_clicked_xy_ ? "on" : "off")
    .arg(armed_asset_x_m_, 0, 'f', 3).arg(armed_asset_y_m_, 0, 'f', 3).arg(armed_asset_z_m_, 0, 'f', 3)
    .arg(armed_asset_roll_rad_, 0, 'f', 3).arg(armed_asset_pitch_rad_, 0, 'f', 3).arg(armed_asset_yaw_rad_, 0, 'f', 3));
  return true;
}

void MainWindow::commit_armed_asset_placement(
  const QPointF & canvas_pos_px, bool preserve_placement_session, bool use_configured_persistence)
{
  if (!digital_twin_scene_ || !place_asset_armed_) return;
  if (!ensure_live_authoring_mutation_available(QStringLiteral("Asset placement"))) return;
  const QString category = armed_asset_category_;
  const QString display_name = armed_asset_display_name_;
  const QString source_path = armed_asset_source_path_;
  const QString asset_id = armed_asset_id_;
  std::set<std::string> reserved_ids;
  for (auto * gi : digital_twin_scene_->items()) {
    const QString existing_id = gi->data(RoleId).toString().trimmed();
    if (!existing_id.isEmpty()) reserved_ids.insert(existing_id.toStdString());
  }
  const fs::path layout_path = selected_scene_existing_layout_import_path(scene_browser_result_, selected_scene_index_);
  if (!layout_path.empty()) {
    const auto layout_ids = workcell_builder::workcell_studio_collect_layout_ids(layout_path);
    reserved_ids.insert(layout_ids.begin(), layout_ids.end());
  }
  const QString new_id = QString::fromStdString(
    workcell_builder::workcell_studio_next_id(category.toStdString(), reserved_ids));
  const QString role_type = QString::fromStdString(
    workcell_builder::workcell_studio_id_prefix_for_type(category.toStdString()));

  auto * item = new DraggableCanvasItem(QRectF(0, 0, 35.0, 35.0));
  QString validation_error;
  if (!validate_armed_asset_transform(&validation_error)) {
    append_studio_log(QString("Add Asset validation failed: %1 (%2) %3")
      .arg(display_name, category, validation_error));
    statusBar()->showMessage("Add Asset blocked: invalid transform input.", 4000);
    return;
  }
  QPointF placement(armed_asset_x_m_ * 100.0, armed_asset_y_m_ * 100.0);
  if (armed_asset_use_clicked_xy_) {
    placement = snap_canvas_position(canvas_pos_px);
    if (qAbs(placement.x()) < 0.1 && qAbs(placement.y()) < 0.1) {
      placement = armed_asset_default_xy_px_;
    }
  }
  if (digital_twin_scene_->items().isEmpty()) {
    placement = QPointF(0.0, 0.0);
    QMessageBox::warning(this, "Default placement", "No robot/table found; placing asset at canvas center.");
  }
  item->setPos(placement);
  // A URDF primitive is centred on its link origin: rest it on the surface.
  const auto primitive = first_urdf_visual_primitive(source_path);
  const double placed_z = armed_asset_z_m_ + (primitive ? primitive->sz / 2.0 : 0.0);
  // The primitive is authored as geometry_type + dimensions, never as a mesh path.
  const QString placed_source = primitive ? QString() : source_path;
  item->setData(RoleId, new_id);
  item->setData(RoleDisplayName, display_name);
  item->setData(RoleType, role_type);
  item->setData(RoleCategory, category);
  item->setData(RoleRole, "asset");
  item->setData(RoleSource, placed_source);
  item->setData(RoleSourcePackage, "asset_folder");
  item->setData(RoleGeometryType, primitive ? primitive->type : QString());
  item->setData(RolePoseZ, placed_z);
  item->setData(RoleRoll, armed_asset_roll_rad_); item->setData(RolePitch, armed_asset_pitch_rad_); item->setData(RoleYaw, armed_asset_yaw_rad_);
  item->setData(RoleWidth, primitive ? primitive->sx : 1.0); item->setData(RoleDepth, primitive ? primitive->sy : 1.0);
  item->setData(RoleHeight, primitive ? primitive->sz : 1.0);
  item->setData(RoleCatalogAssetId, asset_id);
  item->setData(RoleMeshScaleX, armed_asset_scale_); item->setData(RoleMeshScaleY, armed_asset_scale_); item->setData(RoleMeshScaleZ, armed_asset_scale_);
  item->setData(RoleImported, !primitive && (
    source_path.endsWith(".stl", Qt::CaseInsensitive) ||
    source_path.endsWith(".obj", Qt::CaseInsensitive) ||
    source_path.endsWith(".dae", Qt::CaseInsensitive) ||
    source_path.endsWith(".urdf", Qt::CaseInsensitive)));
  item->setData(RoleGeneratedPlaceholder, category.contains("placeholder", Qt::CaseInsensitive));
  item->setData(RoleSourceLayer, QStringLiteral("editable_layout"));
  item->setData(RoleLocked, false);
  QStringList warnings;
  if (source_path.trimmed().isEmpty()) warnings << "missing dimensions/source metadata";
  if (QLineF(item->pos(), QPointF(-20.0, -220.0)).length() < 80.0) warnings << "too close to robot base";
  for (auto *existing : digital_twin_scene_->items()) {
    if (existing == item || existing->data(RoleRole).toString() != "asset") continue;
    if (QLineF(existing->pos(), item->pos()).length() < 40.0) { warnings << "overlap"; break; }
  }
  if (item->pos().x() < -260.0 || item->pos().x() > 260.0 || item->pos().y() < -260.0 || item->pos().y() > 260.0) warnings << "outside workspace";
  if (item->data(RolePoseZ).toDouble() < 0.0) warnings << "below floor/table";
  item->setData(RoleWarning, warnings.join(", "));
  item->setFlags(QGraphicsItem::ItemIsSelectable | QGraphicsItem::ItemSendsGeometryChanges | QGraphicsItem::ItemIsMovable);
  item->position_filter = [this](const QPointF & p){ return snap_canvas_position(p); };
  digital_twin_scene_->addItem(item);
  ScenePreviewWidget::PreviewItem preview_item;
  preview_item.id = new_id;
  preview_item.display_name = display_name;
  preview_item.category = category;
  preview_item.catalog_asset_id = asset_id;
  preview_item.role = canonical_scene_hierarchy_role(
    QStringLiteral("asset"), category, display_name);
  preview_item.status = QStringLiteral("ready");
  preview_item.source_path = placed_source;
  preview_item.mesh_path = placed_source;
  preview_item.mesh_type = QFileInfo(placed_source).suffix().toLower();
  preview_item.source_layer = QStringLiteral("editable_layout");
  preview_item.active_visual_source = QStringLiteral("mesh_preview");
  preview_item.linked_to_editable_layout_state = true;
  preview_item.editable = true;
  preview_item.locked = false;
  preview_item.selectable = true;
  preview_item.metadata_complete = true;
  preview_item.x = item->pos().x() / 100.0;
  preview_item.y = item->pos().y() / 100.0;
  preview_item.z = placed_z;
  preview_item.roll = armed_asset_roll_rad_;
  preview_item.pitch = armed_asset_pitch_rad_;
  preview_item.yaw = armed_asset_yaw_rad_;
  preview_item.sx = primitive ? primitive->sx : 1.0;
  preview_item.sy = primitive ? primitive->sy : 1.0;
  preview_item.sz = primitive ? primitive->sz : 1.0;
  if (primitive) {
    preview_item.primitive_geometry_type = primitive->type;
    preview_item.primitive_radius = primitive->radius;
    preview_item.primitive_length = primitive->length;
  }
  preview_item.mesh_scale_x = armed_asset_scale_;
  preview_item.mesh_scale_y = armed_asset_scale_;
  preview_item.mesh_scale_z = armed_asset_scale_;
  preview_item.has_mesh_metadata = !primitive;
  preview_item.mesh_available = !primitive && QFileInfo(source_path).isFile();
  if (!primitive && !preview_item.mesh_available) {
    preview_item.mesh_load_warning = QStringLiteral("mesh file not found: %1").arg(source_path);
    append_studio_log(QStringLiteral("Asset Browser warning: mesh failed availability check for %1; item remains editable but fallback boxes are not enabled for this asset.").arg(source_path));
  }
  for (int i = 0; i < all_scene_preview_items_.size(); ++i) {
    if (all_scene_preview_items_[i].id == new_id) { all_scene_preview_items_.removeAt(i); break; }
  }
  all_scene_preview_items_.push_back(preview_item);
  upsert_session_item(editable_layout_session_items_, preview_item);
  if (scene_preview_widget_ && scene_preview_widget_->embedded_web_authoring_active())
    scene_preview_widget_->add_authoring_item(preview_item);
  else apply_scene3d_preview_layer_filters(false);
  refresh_scene_hierarchy_tree_from_current_items();
  mark_layout_dirty("Place Asset Mode: Add to 3D Canvas");
  append_studio_log(QStringLiteral("Asset placement: scene=%1 instance_id=%2 catalog_asset=%3 hierarchy_updated=true layout_dirty=true persisted=false")
    .arg(selected_scene_name().trimmed(), new_id, asset_id));
  digital_twin_scene_->clearSelection();
  item->setSelected(true);
  select_canvas_item(item);
  undo_stack_.push_back({"add", new_id, item->pos(), item->pos(), true, false, {preview_item}});
  redo_stack_.clear();
  scene_preview_widget_->set_native_authoring_history_available(true, false);
  set_canvas_interaction_mode(CanvasInteractionMode::Place);
  append_studio_log(QString("Add to Canvas success: %1 (%2) asset_id=%3 layout_id=%4 from %5 | xyzrpy=[%6, %7, %8, %9, %10, %11] use_clicked_xy=%12")
    .arg(display_name, category, asset_id, new_id, source_path)
    .arg(item->pos().x() / 100.0, 0, 'f', 3).arg(item->pos().y() / 100.0, 0, 'f', 3).arg(armed_asset_z_m_, 0, 'f', 3)
    .arg(armed_asset_roll_rad_, 0, 'f', 3).arg(armed_asset_pitch_rad_, 0, 'f', 3).arg(armed_asset_yaw_rad_, 0, 'f', 3)
    .arg(armed_asset_use_clicked_xy_ ? "true" : "false"));
  append_studio_log("ghost placement preview committed");
  record_recent_asset(asset_id);
  if (scene_preview_widget_) scene_preview_widget_->select_preview_item(new_id);
  if (scene_builder_inspector_tabs_) scene_builder_inspector_tabs_->setCurrentIndex(0);
  refresh_diagnostics_quick_status();
  const bool persist = preserve_placement_session ||
    (use_configured_persistence && place_mode_persistent_box_ && place_mode_persistent_box_->isChecked());
  place_asset_armed_ = persist;
  if (!persist) {
    set_canvas_interaction_mode(CanvasInteractionMode::Select);
  }
}


void MainWindow::validate_asset_catalog_selection()
{
  if (!add_to_canvas_button_) return;
  bool can_add = false;
  QString disabled_reason;
  if (!digital_twin_scene_) {
    disabled_reason = "Open an editable scene before adding catalog assets.";
  } else if (asset_catalog_tree_) {
    auto * item = asset_catalog_tree_->currentItem();
    if (item && !item->isHidden()) {
      can_add = item->data(0, CatalogRolePlaceable).toBool();
      if (!can_add) disabled_reason = "Selected asset is not placeable with the current visual/primitive support.";
    } else {
      disabled_reason = "Select a visible catalog asset.";
    }
  }
  add_to_canvas_button_->setEnabled(can_add);
  add_to_canvas_button_->setToolTip(can_add ? "Start existing Place Asset mode for the selected catalog asset." : disabled_reason);
  update_place_again_action();
}

void MainWindow::record_recent_asset(const QString & asset_id)
{
  std::vector<std::string> current;
  current.reserve(static_cast<size_t>(recent_asset_ids_.size()));
  for (const auto & id : recent_asset_ids_) current.push_back(id.toStdString());
  const auto updated = record_recent_asset_id(current, asset_id.trimmed().toStdString(), 8);
  recent_asset_ids_.clear();
  for (const auto & id : updated) recent_asset_ids_.append(QString::fromStdString(id));
  QSettings().setValue(QStringLiteral("asset_library/recent_catalog_ids"), recent_asset_ids_);
  if (asset_filter_combo_ && asset_filter_combo_->currentData().toString() == QStringLiteral("recent")) {
    on_asset_filter_changed(asset_filter_combo_->currentIndex());
  } else {
    update_place_again_action();
  }
}

void MainWindow::update_place_again_action()
{
  if (!place_again_button_) return;
  auto * menu_action = findChild<QAction *>(QStringLiteral("assetLibraryPlaceAgainAction"));
  if (recent_asset_ids_.isEmpty()) {
    place_again_button_->setEnabled(false);
    if (menu_action) menu_action->setEnabled(false);
    place_again_button_->setToolTip("Place an asset successfully before using Place Again.");
    return;
  }
  const QString last_id = recent_asset_ids_.front();
  const auto match = std::find_if(asset_catalog_entries_.cbegin(), asset_catalog_entries_.cend(),
    [&last_id](const AssetCatalogEntry & entry) { return entry.asset_id == last_id; });
  const bool available = match != asset_catalog_entries_.cend() && match->editable &&
    match->disabled_reason.trimmed().isEmpty() && digital_twin_scene_;
  place_again_button_->setEnabled(available);
  if (menu_action) menu_action->setEnabled(available);
  if (available) {
    place_again_button_->setToolTip(QStringLiteral("Arm normal placement for %1 with default yaw 0.")
      .arg(match->display_name));
  } else {
    place_again_button_->setToolTip(QStringLiteral(
      "Last placed catalog asset '%1' is unavailable or not placeable in the current scene.").arg(last_id));
  }
}

void MainWindow::place_last_asset_again()
{
  update_place_again_action();
  if (!place_again_button_ || !place_again_button_->isEnabled() || recent_asset_ids_.isEmpty()) return;
  // Deliberately use the same catalog arming pipeline as Place Asset. It creates
  // no scene instance until the existing native placement commit succeeds.
  arm_place_asset_mode(recent_asset_ids_.front());
}


QString MainWindow::selected_catalog_item_path() const
{
  if (!asset_catalog_tree_ || !asset_catalog_tree_->currentItem()) {
    return "";
  }
  return asset_catalog_tree_->currentItem()->data(0, CatalogRoleSourcePath).toString();
}

QJsonObject MainWindow::scene3d_filter_diagnostics() const
{
  return scene3d_filter_diagnostics_;
}

void MainWindow::on_asset_filter_changed(int)
{
  const QString selected = asset_filter_combo_ ? asset_filter_combo_->currentData().toString() : "all";
  const QString query = asset_library_search_ ? asset_library_search_->text().trimmed().toLower() : QString();
  if (!asset_catalog_tree_) return;
  QSet<int> recent_indices;
  QVector<int> display_order;
  if (selected == QStringLiteral("recent")) {
    std::vector<::AssetCatalogEntry> model_entries;
    model_entries.reserve(static_cast<size_t>(asset_catalog_entries_.size()));
    for (const auto & e : asset_catalog_entries_) {
      ::AssetCatalogEntry entry;
      entry.id = e.asset_id.toStdString();
      entry.display_name = e.display_name.toStdString();
      entry.category = e.category.toStdString();
      entry.path = e.source_path.toStdString();
      entry.model = e.tags.toStdString();
      model_entries.push_back(entry);
    }
    std::vector<std::string> ids;
    for (const auto & id : recent_asset_ids_) ids.push_back(id.toStdString());
    for (const size_t idx : filter_recent_asset_catalog(model_entries, ids, query.toStdString())) {
      recent_indices.insert(static_cast<int>(idx));
      display_order.push_back(static_cast<int>(idx));
    }
  }
  int visible_count = 0;
  for (int i = 0; i < asset_catalog_tree_->topLevelItemCount(); ++i) {
    auto * item = asset_catalog_tree_->topLevelItem(i);
    const int idx = item->data(0, CatalogRoleIndex).toInt();
    bool visible = false;
    if (idx >= 0 && idx < asset_catalog_entries_.size()) {
      const auto & e = asset_catalog_entries_[idx];
      const bool category_match = selected == "all" ||
        (selected == "recent" && recent_indices.contains(idx)) ||
        (selected == "imported" ? e.provenance == "imported" : e.normalized_category == selected);
      const QString haystack = QString("%1 %2 %3 %4 %5 %6")
        .arg(e.display_name, e.category, e.tags, e.asset_id, e.source_path, e.package_hint).toLower();
      visible = category_match && (query.isEmpty() || haystack.contains(query));
    }
    item->setHidden(!visible);
    if (visible) ++visible_count;
  }
  if (selected == QStringLiteral("recent")) {
    QVector<QTreeWidgetItem *> rows;
    while (asset_catalog_tree_->topLevelItemCount() > 0)
      rows.push_back(asset_catalog_tree_->takeTopLevelItem(0));
    for (const int wanted : display_order) {
      const auto found = std::find_if(rows.cbegin(), rows.cend(), [wanted](const auto * row) {
        return row->data(0, CatalogRoleIndex).toInt() == wanted;
      });
      if (found != rows.cend()) asset_catalog_tree_->addTopLevelItem(*found);
    }
    for (auto * row : rows) if (row->treeWidget() != asset_catalog_tree_) asset_catalog_tree_->addTopLevelItem(row);
  } else {
    QVector<QTreeWidgetItem *> rows;
    while (asset_catalog_tree_->topLevelItemCount() > 0)
      rows.push_back(asset_catalog_tree_->takeTopLevelItem(0));
    std::sort(rows.begin(), rows.end(), [](const auto * a, const auto * b) {
      return a->data(0, CatalogRoleIndex).toInt() < b->data(0, CatalogRoleIndex).toInt();
    });
    for (auto * row : rows) asset_catalog_tree_->addTopLevelItem(row);
  }
  if (asset_library_result_count_) {
    asset_library_result_count_->setText(QString::number(visible_count));
    asset_library_result_count_->setToolTip(
      QString("%1 asset%2 shown").arg(visible_count).arg(visible_count == 1 ? "" : "s"));
  }
  if (asset_library_empty_state_) {
    QString empty_text;
    if (visible_count == 0 && !query.isEmpty())
      empty_text = QStringLiteral("No assets match this search.");
    else if (visible_count == 0 && selected == QStringLiteral("recent"))
      empty_text = QStringLiteral("No recently placed assets yet.");
    else if (visible_count == 0 && selected == QStringLiteral("imported"))
      empty_text = QStringLiteral("No imported assets yet.<br/>Import an asset to add one.");
    asset_library_empty_state_->setText(empty_text);
    asset_library_empty_state_->setVisible(!empty_text.isEmpty());
  }
  validate_asset_catalog_selection();
  update_asset_library_preview();
  request_visible_asset_thumbnails();
  update_place_again_action();
}

void MainWindow::request_visible_asset_thumbnails()
{
  if (!asset_thumbnail_service_ || !asset_catalog_tree_) return;
  // Bound each filter refresh. Cached/in-flight requests are deduplicated by the
  // service, so search remains metadata-only and never blocks on mesh parsing.
  int requested = 0;
  for (int row = 0; row < asset_catalog_tree_->topLevelItemCount() && requested < 32; ++row) {
    auto * item = asset_catalog_tree_->topLevelItem(row);
    if (!item || item->isHidden()) continue;
    const int idx = item->data(0, CatalogRoleIndex).toInt();
    if (idx < 0 || idx >= asset_catalog_entries_.size()) continue;
    const auto & e = asset_catalog_entries_[idx];
    const fs::path scene_dir = has_selected_scene() ? fs::path(selected_scene_path().toStdString()) : workcell_builder_repo_root_from_source();
    const QString resolved = resolve_visual_mesh_source_path(e.source_path,
      e.visual_uri.startsWith("package://") ? e.visual_uri : QString(), scene_dir, detect_workspace_root());
    AssetThumbnailService::Request request{e.asset_id, resolved.isEmpty() ? e.source_path : resolved, e.scale, QSize(256, 192)};
    const auto result = asset_thumbnail_service_->request(request);
    if (result.status == AssetThumbnailService::Status::Ready) refresh_asset_thumbnail(e.asset_id);
    ++requested;
  }
}

void MainWindow::refresh_asset_thumbnail(const QString & asset_id)
{
  if (!asset_thumbnail_service_ || !asset_catalog_tree_) return;
  const auto result = asset_thumbnail_service_->result(asset_id);
  auto * item = find_asset_catalog_item_by_id(asset_catalog_tree_, asset_id);
  if (item) {
    if (result.status == AssetThumbnailService::Status::Ready) {
      item->setIcon(0, QPixmap::fromImage(result.image));
      item->setToolTip(0, item->data(0, CatalogRoleBaseToolTip).toString());
    }
    else {
      item->setIcon(0, style()->standardIcon(QStyle::SP_FileIcon));
      item->setToolTip(0, item->data(0, CatalogRoleBaseToolTip).toString() +
        (result.status == AssetThumbnailService::Status::Failed ? "\nPreview unavailable: " + result.error : "\nLoading preview…"));
    }
  }
  auto * selected = asset_catalog_tree_->currentItem();
  if (!selected || selected->data(0, CatalogRoleAssetId).toString() != asset_id) return;
  if (result.status == AssetThumbnailService::Status::Ready) {
    const QPixmap preview_pixmap = QPixmap::fromImage(result.image);
    if (asset_library_thumbnail_preview_) {
      asset_library_thumbnail_preview_->setPixmap(preview_pixmap.scaled(
        asset_library_thumbnail_preview_->size(), Qt::KeepAspectRatio, Qt::SmoothTransformation));
      asset_library_thumbnail_preview_->setToolTip(QString());
    }
    if (asset_library_selected_preview_) {
      const int preview_width = qMax(240,
        asset_catalog_tree_ ? asset_catalog_tree_->viewport()->width() : asset_library_selected_preview_->width());
      asset_library_selected_preview_->setPixmap(preview_pixmap.scaled(
        QSize(preview_width, 280), Qt::KeepAspectRatio, Qt::SmoothTransformation));
      asset_library_selected_preview_->setToolTip(QString());
    }
  } else {
    const QString status_text = result.status == AssetThumbnailService::Status::Failed
      ? QStringLiteral("Preview unavailable") : QStringLiteral("Loading preview…");
    for (QLabel * preview_label : {asset_library_thumbnail_preview_, asset_library_selected_preview_}) {
      if (!preview_label) continue;
      preview_label->setPixmap(QPixmap());
      preview_label->setText(status_text);
      preview_label->setToolTip(result.status == AssetThumbnailService::Status::Failed ? result.error : QString());
    }
  }
}

void MainWindow::update_asset_library_preview()
{
  auto * item = asset_catalog_tree_ ? asset_catalog_tree_->currentItem() : nullptr;
  const int idx = item ? item->data(0, CatalogRoleIndex).toInt() : -1;
  if (!item || item->isHidden() || idx < 0 || idx >= asset_catalog_entries_.size()) {
    if (asset_library_details_) asset_library_details_->parentWidget()->hide();
    if (asset_library_thumbnail_preview_) { asset_library_thumbnail_preview_->setPixmap(QPixmap()); asset_library_thumbnail_preview_->clear(); }
    if (asset_library_selected_preview_) {
      asset_library_selected_preview_->setPixmap(QPixmap());
      asset_library_selected_preview_->clear();
      asset_library_selected_preview_->hide();
    }
    return;
  }
  const auto & e = asset_catalog_entries_[idx];
  if (asset_library_details_) {
    const bool ready = e.disabled_reason.trimmed().isEmpty() && e.editable;
    asset_library_details_->parentWidget()->show();
    asset_library_details_->setToolTip(e.source_path);
    asset_library_details_->setText(QString(
      "<span style='color:#7a8998;font-size:11px'>Selected asset</span><br/>"
      "<b>%1</b><br/><span style='color:#607284'>%2%3</span>%4")
      .arg(e.display_name.toHtmlEscaped(), e.category_label.toHtmlEscaped(),
        (e.format_label.isEmpty() ? QString() : QStringLiteral(" · ") + e.format_label.toHtmlEscaped()),
        (ready || e.disabled_reason.isEmpty() ? QString() : QString("<br/><span style='color:#a13b32'>%1</span>").arg(e.disabled_reason.toHtmlEscaped()))));
  }
  if (asset_library_selected_preview_) {
    asset_library_selected_preview_->show();
    asset_library_selected_preview_->setPixmap(QPixmap());
    asset_library_selected_preview_->setText(QStringLiteral("Loading preview…"));
  }
  if (!asset_thumbnail_service_) return;
  const fs::path scene_dir = has_selected_scene()
    ? fs::path(selected_scene_path().toStdString()) : workcell_builder_repo_root_from_source();
  const QString resolved = resolve_visual_mesh_source_path(e.source_path,
    e.visual_uri.startsWith("package://") ? e.visual_uri : QString(), scene_dir, detect_workspace_root());
  const AssetThumbnailService::Request request{
    e.asset_id, resolved.isEmpty() ? e.source_path : resolved, e.scale, QSize(256, 192)};
  asset_thumbnail_service_->request(request);
  refresh_asset_thumbnail(e.asset_id);
}

void MainWindow::on_hierarchy_item_selected(QTreeWidgetItem * item)
{
  if (!item || selection_update_guard_) return;
  const QString selected_id = item->data(0, TreeRoleId).toString().trimmed();
  const auto modifiers = hierarchy_click_modifiers_ | QApplication::keyboardModifiers();
  hierarchy_click_modifiers_ = Qt::NoModifier;
  if (!selected_id.isEmpty() && !mate_active()) {
    if (modifiers & (Qt::ControlModifier | Qt::MetaModifier)) { toggle_scene_selection(selected_id); return; }
    if (modifiers & Qt::ShiftModifier) { extend_scene_selection_to(selected_id); return; }
    hierarchy_range_anchor_ = selected_id;
  }
  const QString selected_role = item->data(0, TreeRoleRole).toString().trimmed();
  const auto * preview_item = scene_preview_widget_ ? scene_preview_widget_->preview_item_by_id(selected_id) : nullptr;
  // Hidden visuals are absent from the filtered viewport, but their authored
  // rows remain in the complete hierarchy/canvas model.
  if (!preview_item) {
    for (const auto & candidate : all_scene_preview_items_) {
      if (candidate.id == selected_id) { preview_item = &candidate; break; }
    }
  }
  if (preview_item && (preview_item->semantic_task_zone_helper ||
      preview_item->source_layer == QStringLiteral("overlay")) &&
      preview_layer_overlays_helpers_box_ && !preview_layer_overlays_helpers_box_->isChecked()) {
    // An explicit hierarchy choice is deterministic opt-in to seeing that
    // helper. Hidden helpers never participate in ordinary canvas picking.
    preview_layer_overlays_helpers_box_->setChecked(true);
  }
  apply_scene_selection(selected_id, selected_role, false, true);
}

void MainWindow::rename_selected_item()
{
  const auto target = resolve_selected_editable_layout_target();
  if (!target.ok) {
    statusBar()->showMessage(QStringLiteral("Rename is available for editable scene items."), 3500);
    return;
  }
  const QString current_name = target.state.display_name.trimmed().isEmpty()
    ? target.state.id : target.state.display_name.trimmed();
  bool accepted = false;
  const QString updated = QInputDialog::getText(
    this, QStringLiteral("Rename Scene Item"), QStringLiteral("Name"),
    QLineEdit::Normal, current_name, &accepted).trimmed();
  if (!accepted || updated.isEmpty() || updated == current_name) return;
  if (inspector_display_name_) inspector_display_name_->setText(updated);
  apply_inspector_pose_to_item();
  statusBar()->showMessage(QStringLiteral("Renamed %1 to %2").arg(current_name, updated), 4000);
}

void MainWindow::show_scene_hierarchy_context_menu(const QPoint & position)
{
  if (!scene_hierarchy_tree_) return;
  QTreeWidgetItem * item = scene_hierarchy_tree_->itemAt(position);
  if (!item || item->data(0, TreeRoleIsGroup).toBool()) return;
  on_hierarchy_item_selected(item);

  const auto state = current_selected_scene_item();
  const bool editable = state.valid && state.editable && !state.locked &&
    state.linked_to_editable_layout_state;
  QMenu menu(this);
  auto * rename = menu.addAction(QStringLiteral("Rename"));
  rename->setShortcut(QKeySequence(Qt::Key_F2));
  rename->setEnabled(editable);
  auto * duplicate = menu.addAction(QStringLiteral("Duplicate"));
  duplicate->setShortcut(QKeySequence(QStringLiteral("Ctrl+D")));
  duplicate->setEnabled(editable);
  menu.addSeparator();
  auto * remove = menu.addAction(QStringLiteral("Remove from Scene"));
  remove->setShortcut(QKeySequence(Qt::Key_Delete));
  remove->setEnabled(editable);
  menu.addSeparator();
  auto * focus = menu.addAction(QStringLiteral("Focus"));
  auto * properties = menu.addAction(QStringLiteral("Properties"));
  menu.addSeparator();
  auto * mate = menu.addAction(QStringLiteral("Mate by Picking Faces…"));
  mate->setObjectName(QStringLiteral("contextMenuMate"));
  mate->setEnabled(editable && !mate_active());
  auto * mount = menu.addAction(QStringLiteral("Mount To / Relative Pose…"));
  mount->setEnabled(editable && !mate_active());

  QAction * chosen = menu.exec(scene_hierarchy_tree_->viewport()->mapToGlobal(position));
  if (chosen == rename) rename_selected_item();
  else if (chosen == duplicate) duplicate_selected_item();
  else if (chosen == remove) delete_selected_item();
  else if (chosen == focus) {
    if (scene_preview_widget_) scene_preview_widget_->frame_selection();
  } else if (chosen == properties) {
    apply_scene_builder_panel_visibility(true, true);
    if (scene_builder_inspector_tabs_) scene_builder_inspector_tabs_->setCurrentIndex(0);
  } else if (chosen == mate) {
    begin_visual_mate();
  } else if (chosen == mount) {
    edit_selected_mounting();
  }
}

